-- ── 3. flatten_checks_from_job RPC ──────────────────────────
-- Upserts check_jobs.checks_data JSONB array → individual checks rows
CREATE OR REPLACE FUNCTION flatten_checks_from_job(p_job_id TEXT)
RETURNS void AS $$
DECLARE
    _job RECORD;
    _check JSONB;
    _ext JSONB;
    _micr JSONB;
    _amount_text TEXT;
    _amount_num NUMERIC;
    _date_text TEXT;
    _date_val DATE;
BEGIN
    SELECT * INTO _job FROM check_jobs WHERE job_id = p_job_id;
    IF NOT FOUND THEN RETURN; END IF;

    FOR _check IN SELECT jsonb_array_elements(_job.checks_data)
    LOOP
        _ext := _check->'extraction';
        IF _ext IS NULL THEN CONTINUE; END IF;
        _micr := _ext->'micr';

        -- Parse amount
        _amount_text := COALESCE(_ext->'amount'->>'value', _ext->>'amount');
        BEGIN
            _amount_num := regexp_replace(COALESCE(_amount_text,''), '[^0-9.]', '', 'g')::NUMERIC;
        EXCEPTION WHEN OTHERS THEN
            _amount_num := NULL;
        END;

        -- Parse date
        _date_text := COALESCE(_ext->'checkDate'->>'value', _ext->>'checkDate');
        BEGIN
            _date_val := _date_text::DATE;
        EXCEPTION WHEN OTHERS THEN
            _date_val := NULL;
        END;

        INSERT INTO checks (
            tenant_id, job_id, check_id, source_file,
            page_number, image_width, image_height, file_url,
            payee, payee_confidence, payee_source,
            amount, amount_raw, amount_confidence, amount_source,
            amount_written, amount_written_confidence,
            check_date, check_date_raw, check_date_confidence, check_date_source,
            check_number, check_number_confidence, check_number_source,
            bank_name, bank_name_confidence, bank_name_source,
            memo, memo_confidence,
            micr_routing, micr_routing_confidence,
            micr_account, micr_account_confidence,
            micr_serial, micr_raw,
            hybrid_results, ocr_results,
            status
        ) VALUES (
            COALESCE(_job.tenant_id, '00000000-0000-0000-0000-000000000000'::UUID),
            p_job_id,
            _check->>'check_id',
            _job.pdf_name,
            COALESCE((_check->>'page')::INT, 1),
            (_check->>'width')::INT,
            (_check->>'height')::INT,
            _check->>'image_url',
            -- payee
            COALESCE(_ext->'payee'->>'value', _ext->>'payee'),
            (_ext->'payee'->>'confidence')::NUMERIC,
            _ext->'payee'->>'source',
            -- amount
            _amount_num,
            _amount_text,
            (_ext->'amount'->>'confidence')::NUMERIC,
            _ext->'amount'->>'source',
            -- amount_written
            COALESCE(_ext->'amountWritten'->>'value', _ext->>'amountWritten'),
            (_ext->'amountWritten'->>'confidence')::NUMERIC,
            -- date
            _date_val,
            _date_text,
            (_ext->'checkDate'->>'confidence')::NUMERIC,
            _ext->'checkDate'->>'source',
            -- check_number
            COALESCE(_ext->'checkNumber'->>'value', _ext->>'checkNumber'),
            (_ext->'checkNumber'->>'confidence')::NUMERIC,
            _ext->'checkNumber'->>'source',
            -- bank
            COALESCE(_ext->'bankName'->>'value', _ext->>'bankName'),
            (_ext->'bankName'->>'confidence')::NUMERIC,
            _ext->'bankName'->>'source',
            -- memo
            COALESCE(_ext->'memo'->>'value', _ext->>'memo'),
            (_ext->'memo'->>'confidence')::NUMERIC,
            -- micr
            COALESCE(_micr->'routing'->>'value', _micr->>'routing'),
            (_micr->'routing'->>'confidence')::NUMERIC,
            COALESCE(_micr->'account'->>'value', _micr->>'account'),
            (_micr->'account'->>'confidence')::NUMERIC,
            COALESCE(_micr->'serial'->>'value', _micr->>'serial'),
            _micr->>'raw',
            -- raw results
            _ext,
            _check->'engine_results',
            'pending_review'
        )
        ON CONFLICT (job_id, check_id)
        DO UPDATE SET
            page_number     = EXCLUDED.page_number,
            image_width     = EXCLUDED.image_width,
            image_height    = EXCLUDED.image_height,
            file_url        = EXCLUDED.file_url,
            payee           = EXCLUDED.payee,
            payee_confidence = EXCLUDED.payee_confidence,
            amount          = EXCLUDED.amount,
            amount_raw      = EXCLUDED.amount_raw,
            amount_confidence = EXCLUDED.amount_confidence,
            check_date      = EXCLUDED.check_date,
            check_date_raw  = EXCLUDED.check_date_raw,
            check_date_confidence = EXCLUDED.check_date_confidence,
            check_number    = EXCLUDED.check_number,
            check_number_confidence = EXCLUDED.check_number_confidence,
            bank_name       = EXCLUDED.bank_name,
            bank_name_confidence = EXCLUDED.bank_name_confidence,
            memo            = EXCLUDED.memo,
            memo_confidence = EXCLUDED.memo_confidence,
            micr_routing    = EXCLUDED.micr_routing,
            micr_account    = EXCLUDED.micr_account,
            hybrid_results  = EXCLUDED.hybrid_results,
            ocr_results     = EXCLUDED.ocr_results,
            updated_at      = now();
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ── 4. updated_at triggers ──────────────────────────────────
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_check_jobs_updated ON check_jobs;
CREATE TRIGGER trg_check_jobs_updated
    BEFORE UPDATE ON check_jobs
    FOR EACH ROW EXECUTE FUNCTION update_updated_at();

DROP TRIGGER IF EXISTS trg_checks_updated ON checks;
CREATE TRIGGER trg_checks_updated
    BEFORE UPDATE ON checks
    FOR EACH ROW EXECUTE FUNCTION update_updated_at();

-- ── 5. Storage bucket + policies ────────────────────────────
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('checks', 'checks', true, 52428800, ARRAY['image/jpeg','image/png','image/jpg','image/webp','application/pdf'])
ON CONFLICT (id) DO NOTHING;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'public_read_checks' AND tablename = 'objects') THEN
        CREATE POLICY "public_read_checks" ON storage.objects FOR SELECT USING (bucket_id = 'checks');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'public_write_checks' AND tablename = 'objects') THEN
        CREATE POLICY "public_write_checks" ON storage.objects FOR INSERT WITH CHECK (bucket_id = 'checks');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'public_update_checks' AND tablename = 'objects') THEN
        CREATE POLICY "public_update_checks" ON storage.objects FOR UPDATE USING (bucket_id = 'checks');
    END IF;
END $$;

-- ========================================================================
-- 003_add_flatten_function.sql
-- ========================================================================
-- ============================================================================
-- Add flatten_checks_from_job function if missing
-- Run this in Supabase SQL Editor if you get 404 errors
-- ============================================================================

-- ── flatten_checks_from_job: upsert checks_data JSONB → checks table ──
CREATE OR REPLACE FUNCTION flatten_checks_from_job(p_job_id TEXT)
RETURNS void AS $$
DECLARE
    _job RECORD;
    _check JSONB;
    _ext JSONB;
    _micr JSONB;
    _amount_text TEXT;
    _amount_num NUMERIC;
    _date_text TEXT;
    _date_val DATE;
BEGIN
    SELECT * INTO _job FROM check_jobs WHERE job_id = p_job_id;
    IF NOT FOUND THEN RETURN; END IF;

    FOR _check IN SELECT jsonb_array_elements(_job.checks_data)
    LOOP
        _ext := _check->'extraction';
        _micr := _ext->'micr';

        -- Parse amount: handle {value, confidence} or plain string
        _amount_text := COALESCE(
            _ext->'amount'->>'value',
            _ext->>'amount'
        );
        BEGIN
            _amount_num := regexp_replace(COALESCE(_amount_text,''), '[^0-9.]', '', 'g')::NUMERIC;
        EXCEPTION WHEN OTHERS THEN
            _amount_num := NULL;
        END;

        -- Parse date
        _date_text := COALESCE(
            _ext->'checkDate'->>'value',
            _ext->>'checkDate'
        );
        BEGIN
            _date_val := _date_text::DATE;
        EXCEPTION WHEN OTHERS THEN
            _date_val := NULL;
        END;

        INSERT INTO checks (
            tenant_id, job_id, check_id, source_file,
            page_number, image_width, image_height, file_url,
            payee, payee_confidence, payee_source,
            amount, amount_raw, amount_confidence, amount_source,
            amount_written, amount_written_confidence,
            check_date, check_date_raw, check_date_confidence, check_date_source,
            check_number, check_number_confidence, check_number_source,
            bank_name, bank_name_confidence, bank_name_source,
            memo, memo_confidence,
            micr_routing, micr_routing_confidence,
            micr_account, micr_account_confidence,
            micr_serial, micr_raw,
            hybrid_results, ocr_results,
            status
        ) VALUES (
            COALESCE(_job.tenant_id, '00000000-0000-0000-0000-000000000000'::UUID),
            p_job_id,
            _check->>'check_id',
            _job.pdf_name,
            COALESCE((_check->>'page')::INT, 1),
            (_check->>'width')::INT,
            (_check->>'height')::INT,
            _check->>'image_url',
            -- payee
            COALESCE(_ext->'payee'->>'value', _ext->>'payee'),
            (_ext->'payee'->>'confidence')::NUMERIC,
            _ext->'payee'->>'source',
            -- amount
            _amount_num,
            _amount_text,
            (_ext->'amount'->>'confidence')::NUMERIC,
            _ext->'amount'->>'source',
            -- amount_written
            COALESCE(_ext->'amountWritten'->>'value', _ext->>'amountWritten'),
            (_ext->'amountWritten'->>'confidence')::NUMERIC,
            -- date
            _date_val,
            _date_text,
            (_ext->'checkDate'->>'confidence')::NUMERIC,
            _ext->'checkDate'->>'source',
            -- check_number
            COALESCE(_ext->'checkNumber'->>'value', _ext->>'checkNumber'),
            (_ext->'checkNumber'->>'confidence')::NUMERIC,
            _ext->'checkNumber'->>'source',
            -- bank
            COALESCE(_ext->'bankName'->>'value', _ext->>'bankName'),
            (_ext->'bankName'->>'confidence')::NUMERIC,
            _ext->'bankName'->>'source',
            -- memo
            COALESCE(_ext->'memo'->>'value', _ext->>'memo'),
            (_ext->'memo'->>'confidence')::NUMERIC,
            -- micr
            COALESCE(_micr->'routing'->>'value', _micr->>'routing'),
            (_micr->'routing'->>'confidence')::NUMERIC,
            COALESCE(_micr->'account'->>'value', _micr->>'account'),
            (_micr->'account'->>'confidence')::NUMERIC,
            COALESCE(_micr->'serial'->>'value', _micr->>'serial'),
            _micr->>'raw',
            -- raw results
            _ext,
            _check->'engine_results',
            'pending_review'
        )
        ON CONFLICT (job_id, check_id)
        DO UPDATE SET
            page_number     = EXCLUDED.page_number,
            image_width     = EXCLUDED.image_width,
            image_height    = EXCLUDED.image_height,
            file_url        = EXCLUDED.file_url,
            payee           = EXCLUDED.payee,
            payee_confidence = EXCLUDED.payee_confidence,
            amount          = EXCLUDED.amount,
            amount_raw      = EXCLUDED.amount_raw,
            amount_confidence = EXCLUDED.amount_confidence,
            check_date      = EXCLUDED.check_date,
            check_date_raw  = EXCLUDED.check_date_raw,
            check_date_confidence = EXCLUDED.check_date_confidence,
            check_number    = EXCLUDED.check_number,
            check_number_confidence = EXCLUDED.check_number_confidence,
            bank_name       = EXCLUDED.bank_name,
            bank_name_confidence = EXCLUDED.bank_name_confidence,
            memo            = EXCLUDED.memo,
            memo_confidence = EXCLUDED.memo_confidence,
            micr_routing    = EXCLUDED.micr_routing,
            micr_account    = EXCLUDED.micr_account,
            hybrid_results  = EXCLUDED.hybrid_results,
            updated_at      = now();
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ========================================================================
-- 004_add_qb_entries_table.sql
-- ========================================================================
-- Create qb_entries table for storing synced QuickBooks cheque data
CREATE TABLE IF NOT EXISTS qb_entries (
  id TEXT PRIMARY KEY,
  qb_type TEXT NOT NULL,          -- 'Purchase', 'BillPayment', 'Payment'
  qb_source TEXT NOT NULL,        -- 'cheque_written', 'bill_paid_by_cheque', 'cheque_received'
  check_number TEXT DEFAULT '',
  date TEXT DEFAULT '',
  amount TEXT DEFAULT '0',
  payee TEXT DEFAULT '',
  account TEXT DEFAULT '',
  memo TEXT DEFAULT '',
  raw_data JSONB,
  synced_at TIMESTAMPTZ DEFAULT NOW(),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Add columns to integrations table if they don't exist
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'integrations' AND column_name = 'qb_client_id') THEN
    ALTER TABLE integrations ADD COLUMN qb_client_id TEXT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'integrations' AND column_name = 'qb_client_secret') THEN
    ALTER TABLE integrations ADD COLUMN qb_client_secret TEXT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'integrations' AND column_name = 'qb_redirect_uri') THEN
    ALTER TABLE integrations ADD COLUMN qb_redirect_uri TEXT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'integrations' AND column_name = 'gemini_api_key') THEN
    ALTER TABLE integrations ADD COLUMN gemini_api_key TEXT;
  END IF;
END $$;

-- Enable RLS
ALTER TABLE qb_entries ENABLE ROW LEVEL SECURITY;

-- Service role can manage qb_entries
CREATE POLICY "Service role can manage qb_entries"
  ON qb_entries
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

-- Index for common queries
CREATE INDEX IF NOT EXISTS idx_qb_entries_date ON qb_entries (date DESC);
CREATE INDEX IF NOT EXISTS idx_qb_entries_qb_source ON qb_entries (qb_source);
CREATE INDEX IF NOT EXISTS idx_qb_entries_check_number ON qb_entries (check_number);


-- ------------------------------------------------------------------------
-- Merged from 004a_create_integrations_table.sql
-- 
-- Originally shipped as a second file also numbered 004. Supabase keys its
-- migration ledger on the version alone, so two files numbered 004 can never
-- both be recorded, and a non-numeric suffix is skipped outright. Folded in
-- here. It must stay ahead of 008, which adds a column to this table.
-- ------------------------------------------------------------------------

-- Create integrations table for storing OAuth tokens and API keys
CREATE TABLE IF NOT EXISTS integrations (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  provider TEXT NOT NULL,
  realm_id TEXT,
  access_token TEXT,
  refresh_token TEXT,
  expires_at TIMESTAMPTZ,
  -- QuickBooks OAuth credentials (stored in DB instead of env vars)
  qb_client_id TEXT,
  qb_client_secret TEXT,
  qb_redirect_uri TEXT,
  -- Other API keys
  gemini_api_key TEXT,
  api_keys JSONB DEFAULT '{}'::jsonb,
  metadata JSONB DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(provider)
);

-- Enable RLS
ALTER TABLE integrations ENABLE ROW LEVEL SECURITY;

-- Create policy for service role (backend can manage all integrations)
DROP POLICY IF EXISTS "Service role can manage integrations" ON integrations;
CREATE POLICY "Service role can manage integrations"
  ON integrations
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

-- Create index for faster lookups
CREATE INDEX IF NOT EXISTS idx_integrations_provider ON integrations(provider);
CREATE INDEX IF NOT EXISTS idx_integrations_realm_id ON integrations(realm_id);

-- Add comment
COMMENT ON TABLE integrations IS 'Stores OAuth tokens and API keys for third-party integrations (QuickBooks, etc.)';

