-- ------------------------------------------------------------------------
-- Merged from 009a_create_vouched_checks.sql
-- 
-- Originally shipped as a second file also numbered 009 - see the note in 004.
-- Folded in here. Nothing above touches vouched_checks, so appending is safe.
-- ------------------------------------------------------------------------

-- Create table to store vouched (manually approved) check issues
-- Uses composite key of check identifier to track which issues have been vouched
CREATE TABLE IF NOT EXISTS vouched_checks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Composite identifier for the check (can be from extraction or QB)
  check_identifier TEXT NOT NULL, -- Format: "ext-{job_id}-{check_id}" or "qb-{qb_id}" or "matched-{job_id}-{check_id}"
  check_number TEXT,
  
  -- Vouch metadata
  vouched_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  vouched_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  reason TEXT, -- Optional reason for vouching
  
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  
  -- Ensure one vouch per check per tenant
  UNIQUE(tenant_id, check_identifier)
);

-- Index for fast lookups
CREATE INDEX IF NOT EXISTS idx_vouched_checks_tenant ON vouched_checks(tenant_id);
CREATE INDEX IF NOT EXISTS idx_vouched_checks_identifier ON vouched_checks(check_identifier);

-- RLS policies
ALTER TABLE vouched_checks ENABLE ROW LEVEL SECURITY;

-- Users can only see vouched checks for their tenant
DROP POLICY IF EXISTS "Users can view vouched checks for their tenant" ON vouched_checks;
CREATE POLICY "Users can view vouched checks for their tenant"
  ON vouched_checks
  FOR SELECT
  USING (
    tenant_id IN (
      SELECT tenant_id FROM tenants WHERE tenant_id = (
        SELECT tenant_id FROM auth.users WHERE id = auth.uid()
      )
    )
  );

-- Users can insert vouched checks for their tenant
DROP POLICY IF EXISTS "Users can vouch checks for their tenant" ON vouched_checks;
CREATE POLICY "Users can vouch checks for their tenant"
  ON vouched_checks
  FOR INSERT
  WITH CHECK (
    tenant_id IN (
      SELECT tenant_id FROM tenants WHERE tenant_id = (
        SELECT tenant_id FROM auth.users WHERE id = auth.uid()
      )
    )
  );

-- Users can delete their own vouched checks
DROP POLICY IF EXISTS "Users can unvouch checks for their tenant" ON vouched_checks;
CREATE POLICY "Users can unvouch checks for their tenant"
  ON vouched_checks
  FOR DELETE
  USING (
    tenant_id IN (
      SELECT tenant_id FROM tenants WHERE tenant_id = (
        SELECT tenant_id FROM auth.users WHERE id = auth.uid()
      )
    )
  );

-- ========================================================================
-- 010_fix_user_profiles_rls_recursion.sql
-- ========================================================================
-- Fix infinite recursion in user_profiles RLS policies
-- The user_tenant_id() function queries user_profiles, so user_profiles policies
-- cannot use user_tenant_id() or it creates infinite recursion

-- Drop ALL existing policies on user_profiles
DROP POLICY IF EXISTS "Users can view profiles in their tenant" ON public.user_profiles;
DROP POLICY IF EXISTS "Users can view own tenant user_profiles" ON public.user_profiles;
DROP POLICY IF EXISTS "Users can update own tenant user_profiles" ON public.user_profiles;
DROP POLICY IF EXISTS "Users can insert own tenant user_profiles" ON public.user_profiles;
DROP POLICY IF EXISTS "Users can delete own tenant user_profiles" ON public.user_profiles;
DROP POLICY IF EXISTS "Allow all for user_profiles" ON public.user_profiles;

-- Drop the good policies too so we can recreate them
DROP POLICY IF EXISTS "Users can view own profile" ON public.user_profiles;
DROP POLICY IF EXISTS "Users can update own profile" ON public.user_profiles;
DROP POLICY IF EXISTS "Users can create their own profile" ON public.user_profiles;

-- Create simple, non-recursive policies using only auth.uid()
-- Users can view their own profile
CREATE POLICY "Users can view own profile"
  ON public.user_profiles
  FOR SELECT
  USING (id = auth.uid());

-- Users can update their own profile
CREATE POLICY "Users can update own profile"
  ON public.user_profiles
  FOR UPDATE
  USING (id = auth.uid())
  WITH CHECK (id = auth.uid());

-- Users can insert their own profile (for signup)
CREATE POLICY "Users can create their own profile"
  ON public.user_profiles
  FOR INSERT
  WITH CHECK (id = auth.uid());

-- ========================================================================
-- 011_fix_integrations_unique_constraint.sql
-- ========================================================================
-- Fix integrations table unique constraint to be per-tenant
-- Current: UNIQUE(provider) - only one row per provider globally (breaks multi-tenancy)
-- Fixed: UNIQUE(tenant_id, provider) - one row per provider per tenant

-- Drop the old constraint
ALTER TABLE public.integrations DROP CONSTRAINT IF EXISTS integrations_provider_key;

-- Add the new per-tenant constraint
ALTER TABLE public.integrations ADD CONSTRAINT integrations_tenant_provider_key 
  UNIQUE(tenant_id, provider);

-- ========================================================================
-- 012_add_api_usage_tracking.sql
-- ========================================================================
-- ============================================================================
-- Add API Usage Tracking for Accurate Billing
-- Tracks actual Google Cloud API usage (Gemini, Vision) and costs
-- ============================================================================

-- ── API Usage Logs (tracks every API call with exact costs from GCC) ──
CREATE TABLE IF NOT EXISTS api_usage_logs (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    job_id              TEXT REFERENCES check_jobs(job_id) ON DELETE CASCADE,
    check_id            TEXT,
    
    -- API Details
    api_provider        TEXT NOT NULL CHECK (api_provider IN ('gemini', 'openai', 'vision', 'numarkdown')),
    api_model           TEXT,
    api_endpoint        TEXT,
    
    -- Usage Metadata (from API response)
    prompt_tokens       INTEGER DEFAULT 0,
    completion_tokens   INTEGER DEFAULT 0,
    total_tokens        INTEGER DEFAULT 0,
    
    -- Cost (calculated from actual API pricing)
    cost_usd            NUMERIC(10, 6) DEFAULT 0,
    cost_input_usd      NUMERIC(10, 6) DEFAULT 0,
    cost_output_usd     NUMERIC(10, 6) DEFAULT 0,
    
    -- Timing
    processing_time_ms  INTEGER,
    
    -- Metadata
    request_metadata    JSONB DEFAULT '{}'::jsonb,
    response_metadata   JSONB DEFAULT '{}'::jsonb,
    
    created_at          TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_api_usage_tenant_id ON api_usage_logs(tenant_id);
CREATE INDEX IF NOT EXISTS idx_api_usage_job_id ON api_usage_logs(job_id);
CREATE INDEX IF NOT EXISTS idx_api_usage_created_at ON api_usage_logs(created_at);
CREATE INDEX IF NOT EXISTS idx_api_usage_provider ON api_usage_logs(api_provider);

-- ── Add usage tracking fields to check_jobs ──
ALTER TABLE check_jobs ADD COLUMN IF NOT EXISTS total_api_cost_usd NUMERIC(10, 6) DEFAULT 0;
ALTER TABLE check_jobs ADD COLUMN IF NOT EXISTS total_tokens INTEGER DEFAULT 0;
ALTER TABLE check_jobs ADD COLUMN IF NOT EXISTS api_usage_summary JSONB DEFAULT '{}'::jsonb;

-- ── Function to aggregate API usage for a job ──
CREATE OR REPLACE FUNCTION update_job_api_usage(p_job_id TEXT)
RETURNS void AS $$
DECLARE
    _total_cost NUMERIC;
    _total_tokens INTEGER;
    _usage_summary JSONB;
BEGIN
    -- Calculate totals
    SELECT 
        COALESCE(SUM(cost_usd), 0),
        COALESCE(SUM(total_tokens), 0),
        jsonb_build_object(
            'gemini', jsonb_build_object(
                'calls', COUNT(*) FILTER (WHERE api_provider = 'gemini'),
                'tokens', COALESCE(SUM(total_tokens) FILTER (WHERE api_provider = 'gemini'), 0),
                'cost_usd', COALESCE(SUM(cost_usd) FILTER (WHERE api_provider = 'gemini'), 0)
            ),
            'openai', jsonb_build_object(
                'calls', COUNT(*) FILTER (WHERE api_provider = 'openai'),
                'tokens', COALESCE(SUM(total_tokens) FILTER (WHERE api_provider = 'openai'), 0),
                'cost_usd', COALESCE(SUM(cost_usd) FILTER (WHERE api_provider = 'openai'), 0)
            ),
            'total_calls', COUNT(*),
            'total_tokens', COALESCE(SUM(total_tokens), 0),
            'total_cost_usd', COALESCE(SUM(cost_usd), 0)
        )
    INTO _total_cost, _total_tokens, _usage_summary
    FROM api_usage_logs
    WHERE job_id = p_job_id;
    
    -- Update job record
    UPDATE check_jobs
    SET 
        total_api_cost_usd = _total_cost,
        total_tokens = _total_tokens,
        api_usage_summary = _usage_summary,
        updated_at = now()
    WHERE job_id = p_job_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ── RLS Policies ──
ALTER TABLE api_usage_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "service_all" ON api_usage_logs FOR ALL USING (true) WITH CHECK (true);

-- ── Comments ──
COMMENT ON TABLE api_usage_logs IS 'Tracks actual API usage and costs from Google Cloud and OpenAI for accurate billing';
COMMENT ON COLUMN api_usage_logs.cost_usd IS 'Actual cost from API provider pricing, matches Google Cloud Console billing';
COMMENT ON FUNCTION update_job_api_usage IS 'Aggregates API usage costs for a job from individual API calls';

-- ========================================================================
-- 013_qb_multi_company_match.sql
-- ========================================================================
-- ============================================================
-- Migration: QB Multi-Company Switcher + Match Engine
-- Run in Supabase SQL Editor after all previous migrations
-- ============================================================

-- ── QB Connections: one row per QB company per tenant ────────
CREATE TABLE IF NOT EXISTS qb_connections (
  id                UUID        DEFAULT gen_random_uuid() PRIMARY KEY,
  tenant_id         UUID        NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  user_id           UUID        REFERENCES auth.users(id) ON DELETE SET NULL,
  realm_id          TEXT        NOT NULL,
  company_name      TEXT,
  company_logo_url  TEXT,
  access_token      TEXT        NOT NULL,
  refresh_token     TEXT        NOT NULL,
  token_expires_at  TIMESTAMPTZ NOT NULL,
  is_active         BOOLEAN     DEFAULT FALSE,
  connected_at      TIMESTAMPTZ DEFAULT NOW(),
  updated_at        TIMESTAMPTZ DEFAULT NOW(),

  UNIQUE(tenant_id, realm_id)
);

-- Only one active connection per tenant at a time
CREATE UNIQUE INDEX IF NOT EXISTS idx_qb_connections_one_active
  ON qb_connections(tenant_id)
  WHERE is_active = TRUE;

CREATE INDEX IF NOT EXISTS idx_qb_connections_tenant ON qb_connections(tenant_id);

-- ── QB Transactions: pulled from QuickBooks API per company ──
CREATE TABLE IF NOT EXISTS qb_transactions (
  id              UUID        DEFAULT gen_random_uuid() PRIMARY KEY,
  tenant_id       UUID        NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  user_id         UUID        REFERENCES auth.users(id) ON DELETE SET NULL,
  realm_id        TEXT        NOT NULL,

  txn_id          TEXT        NOT NULL,
  txn_type        TEXT,
  txn_date        DATE,
  payee           TEXT,
  payee_id        TEXT,
  amount          NUMERIC(12,2),
  memo            TEXT,
  account         TEXT,
  doc_number      TEXT,

  synced_at       TIMESTAMPTZ DEFAULT NOW(),

  UNIQUE(tenant_id, realm_id, txn_id)
);

CREATE INDEX IF NOT EXISTS idx_qb_transactions_tenant_realm ON qb_transactions(tenant_id, realm_id);
CREATE INDEX IF NOT EXISTS idx_qb_transactions_txn_date ON qb_transactions(txn_date);

-- ── Add realm_id to existing checks table ────────────────────
ALTER TABLE public.checks ADD COLUMN IF NOT EXISTS realm_id TEXT;
CREATE INDEX IF NOT EXISTS idx_checks_realm_id ON public.checks(realm_id);

-- ── Matches: check-to-QB-transaction reconciliation ──────────
CREATE TABLE IF NOT EXISTS matches (
  id                  UUID    DEFAULT gen_random_uuid() PRIMARY KEY,
  tenant_id           UUID    NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  user_id             UUID    REFERENCES auth.users(id) ON DELETE SET NULL,
  realm_id            TEXT    NOT NULL,

  check_id            UUID    NOT NULL REFERENCES public.checks(id) ON DELETE CASCADE,
  qb_txn_id           UUID    REFERENCES qb_transactions(id) ON DELETE SET NULL,

  confidence_score    NUMERIC(5,2) DEFAULT 0,
  confidence_reasons  JSONB,

  status              TEXT DEFAULT 'pending'
    CHECK (status IN ('pending','matched','approved','flagged','discrepancy','unmatched','rejected')),

  discrepancy_amount  NUMERIC(12,2),
  discrepancy_type    TEXT,
  discrepancy_notes   TEXT,

  resolution          TEXT,
  resolution_notes    TEXT,
  resolved_by         UUID REFERENCES auth.users(id),
  resolved_at         TIMESTAMPTZ,

  approved_by         UUID REFERENCES auth.users(id),
  approved_at         TIMESTAMPTZ,

  notes               TEXT,
  flagged_reason      TEXT,

  created_at          TIMESTAMPTZ DEFAULT NOW(),
  updated_at          TIMESTAMPTZ DEFAULT NOW(),

  UNIQUE(check_id)
);

CREATE INDEX IF NOT EXISTS idx_matches_tenant_realm ON matches(tenant_id, realm_id);
CREATE INDEX IF NOT EXISTS idx_matches_status ON matches(status);
CREATE INDEX IF NOT EXISTS idx_matches_check_id ON matches(check_id);
CREATE INDEX IF NOT EXISTS idx_matches_confidence ON matches(confidence_score);

-- ── Match Audit Log ──────────────────────────────────────────
CREATE TABLE IF NOT EXISTS match_audit_log (
  id          UUID    DEFAULT gen_random_uuid() PRIMARY KEY,
  match_id    UUID    NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  user_id     UUID    REFERENCES auth.users(id),
  action      TEXT    NOT NULL,
  old_status  TEXT,
  new_status  TEXT,
  details     JSONB,
  created_at  TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_match_audit_log_match ON match_audit_log(match_id);

-- ── Auto-update updated_at triggers ─────────────────────────
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS qb_connections_updated_at ON qb_connections;
CREATE TRIGGER qb_connections_updated_at
  BEFORE UPDATE ON qb_connections FOR EACH ROW EXECUTE FUNCTION update_updated_at();

DROP TRIGGER IF EXISTS matches_updated_at ON matches;
CREATE TRIGGER matches_updated_at
  BEFORE UPDATE ON matches FOR EACH ROW EXECUTE FUNCTION update_updated_at();

-- ── Row Level Security ──────────────────────────────────────
ALTER TABLE qb_connections   ENABLE ROW LEVEL SECURITY;
ALTER TABLE qb_transactions  ENABLE ROW LEVEL SECURITY;
ALTER TABLE matches          ENABLE ROW LEVEL SECURITY;
ALTER TABLE match_audit_log  ENABLE ROW LEVEL SECURITY;

