-- ========================================================================
-- 014_save_plan_on_signup.sql
-- ========================================================================
-- ============================================================================
-- 014: Save plan tier on signup + update CHECK constraint
-- ============================================================================

-- 1. Add plan column if it doesn't exist, then set up CHECK constraint
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'tenants' AND column_name = 'plan'
    ) THEN
        ALTER TABLE tenants ADD COLUMN plan TEXT NOT NULL DEFAULT 'free';
    END IF;
END $$;

ALTER TABLE tenants DROP CONSTRAINT IF EXISTS tenants_plan_check;
ALTER TABLE tenants ADD CONSTRAINT tenants_plan_check 
    CHECK (plan IN ('free', 'starter', 'professional', 'enterprise', 'pro'));

-- 2. Migrate any existing 'free' plans to 'starter' (optional, keeps old data valid)
-- UPDATE tenants SET plan = 'starter' WHERE plan = 'free';

-- 3. Update handle_new_user trigger to save plan from signup metadata
-- Handles both user_profiles and profiles table names (see migration 007)
DO $$
BEGIN
    IF EXISTS (SELECT FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'user_profiles') THEN
        CREATE OR REPLACE FUNCTION handle_new_user()
        RETURNS TRIGGER AS $func$
        DECLARE
            _tenant_id UUID;
            _company_name TEXT;
            _full_name TEXT;
            _plan TEXT;
        BEGIN
            _company_name := COALESCE(
                NEW.raw_user_meta_data->>'company_name',
                NEW.raw_user_meta_data->>'full_name',
                split_part(NEW.email, '@', 1)
            );
            _full_name := COALESCE(
                NEW.raw_user_meta_data->>'full_name',
                split_part(NEW.email, '@', 1)
            );
            _plan := COALESCE(NEW.raw_user_meta_data->>'plan', 'starter');
            IF _plan NOT IN ('starter', 'professional', 'enterprise') THEN
                _plan := 'starter';
            END IF;

            INSERT INTO tenants (name, slug, plan)
            VALUES (
                _company_name,
                lower(regexp_replace(_company_name, '[^a-zA-Z0-9]+', '-', 'g')) || '-' || substr(NEW.id::text, 1, 8),
                _plan
            )
            RETURNING id INTO _tenant_id;

            INSERT INTO user_profiles (id, tenant_id, email, full_name, role)
            VALUES (NEW.id, _tenant_id, NEW.email, _full_name, 'admin');

            IF EXISTS (SELECT FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'tenant_settings') THEN
                INSERT INTO tenant_settings (tenant_id) VALUES (_tenant_id);
            END IF;

            RETURN NEW;
        EXCEPTION
            WHEN OTHERS THEN
                RAISE WARNING 'Error in handle_new_user: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
                RAISE EXCEPTION 'Database error saving new user: %', SQLERRM;
        END;
        $func$ LANGUAGE plpgsql SECURITY DEFINER;
    ELSE
        CREATE OR REPLACE FUNCTION handle_new_user()
        RETURNS TRIGGER AS $func$
        DECLARE
            _tenant_id UUID;
            _company_name TEXT;
            _full_name TEXT;
            _plan TEXT;
        BEGIN
            _company_name := COALESCE(
                NEW.raw_user_meta_data->>'company_name',
                NEW.raw_user_meta_data->>'full_name',
                split_part(NEW.email, '@', 1)
            );
            _full_name := COALESCE(
                NEW.raw_user_meta_data->>'full_name',
                split_part(NEW.email, '@', 1)
            );
            _plan := COALESCE(NEW.raw_user_meta_data->>'plan', 'starter');
            IF _plan NOT IN ('starter', 'professional', 'enterprise') THEN
                _plan := 'starter';
            END IF;

            INSERT INTO tenants (name, slug, plan)
            VALUES (
                _company_name,
                lower(regexp_replace(_company_name, '[^a-zA-Z0-9]+', '-', 'g')) || '-' || substr(NEW.id::text, 1, 8),
                _plan
            )
            RETURNING id INTO _tenant_id;

            INSERT INTO profiles (id, tenant_id, email, full_name, role)
            VALUES (NEW.id, _tenant_id, NEW.email, _full_name, 'admin');

            IF EXISTS (SELECT FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'tenant_settings') THEN
                INSERT INTO tenant_settings (tenant_id) VALUES (_tenant_id);
            END IF;

            RETURN NEW;
        EXCEPTION
            WHEN OTHERS THEN
                RAISE WARNING 'Error in handle_new_user: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
                RAISE EXCEPTION 'Database error saving new user: %', SQLERRM;
        END;
        $func$ LANGUAGE plpgsql SECURITY DEFINER;
    END IF;
END $$;

-- Recreate the trigger
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
    AFTER INSERT ON auth.users
    FOR EACH ROW EXECUTE FUNCTION handle_new_user();

-- ========================================================================
-- 018_fix_flatten_checks_scalar_error.sql
-- ========================================================================
-- ============================================================================
-- Fix flatten_checks_from_job: handle checks_data as TEXT that needs parsing
-- Error: "cannot extract elements from a scalar"
-- Root cause: checks_data is stored as TEXT, not JSONB
-- ============================================================================

CREATE OR REPLACE FUNCTION flatten_checks_from_job(p_job_id TEXT)
RETURNS void AS $$
DECLARE
    _job RECORD;
    _check JSONB;
    _ext JSONB;
    _micr JSONB;
    _amount_text TEXT;
    _amount_num NUMERIC;
    _date_text TEXT;
    _date_val DATE;
    _checks_array JSONB;
BEGIN
    SELECT * INTO _job FROM check_jobs WHERE job_id = p_job_id;
    IF NOT FOUND THEN RETURN; END IF;

    -- Parse checks_data from TEXT to JSONB array
    -- Handle both TEXT and JSONB column types
    BEGIN
        IF _job.checks_data IS NULL OR _job.checks_data = '' THEN
            RETURN;
        END IF;
        
        -- Try to parse as JSONB (handles both TEXT and JSONB columns)
        _checks_array := _job.checks_data::JSONB;
        
        -- Ensure it's an array
        IF jsonb_typeof(_checks_array) != 'array' THEN
            RAISE NOTICE 'checks_data is not an array for job %', p_job_id;
            RETURN;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Failed to parse checks_data for job %: %', p_job_id, SQLERRM;
        RETURN;
    END;

    -- Iterate over each check in the array
    FOR _check IN SELECT jsonb_array_elements(_checks_array)
    LOOP
        _ext := _check->'extraction';
        _micr := _ext->'micr';

        -- Parse amount: handle {value, confidence} or plain string
        _amount_text := COALESCE(
            _ext->'amount'->>'value',
            _ext->>'amount'
        );
        BEGIN
            _amount_num := regexp_replace(COALESCE(_amount_text,''), '[^0-9.]', '', 'g')::NUMERIC;
        EXCEPTION WHEN OTHERS THEN
            _amount_num := NULL;
        END;

        -- Parse date
        _date_text := COALESCE(
            _ext->'checkDate'->>'value',
            _ext->>'checkDate'
        );
        BEGIN
            _date_val := _date_text::DATE;
        EXCEPTION WHEN OTHERS THEN
            _date_val := NULL;
        END;

        INSERT INTO checks (
            tenant_id, job_id, check_id, source_file,
            page_number, image_width, image_height, file_url,
            payee, payee_confidence, payee_source,
            amount, amount_raw, amount_confidence, amount_source,
            amount_written, amount_written_confidence,
            check_date, check_date_raw, check_date_confidence, check_date_source,
            check_number, check_number_confidence, check_number_source,
            bank_name, bank_name_confidence, bank_name_source,
            memo, memo_confidence,
            micr_routing, micr_routing_confidence,
            micr_account, micr_account_confidence,
            micr_serial, micr_raw,
            hybrid_results, ocr_results,
            status
        ) VALUES (
            COALESCE(_job.tenant_id, '00000000-0000-0000-0000-000000000000'::UUID),
            p_job_id,
            _check->>'check_id',
            _job.pdf_name,
            COALESCE((_check->>'page')::INT, 1),
            (_check->>'width')::INT,
            (_check->>'height')::INT,
            _check->>'image_url',
            -- payee
            COALESCE(_ext->'payee'->>'value', _ext->>'payee'),
            (_ext->'payee'->>'confidence')::NUMERIC,
            _ext->'payee'->>'source',
            -- amount
            _amount_num,
            _amount_text,
            (_ext->'amount'->>'confidence')::NUMERIC,
            _ext->'amount'->>'source',
            -- amount_written
            COALESCE(_ext->'amountWritten'->>'value', _ext->>'amountWritten'),
            (_ext->'amountWritten'->>'confidence')::NUMERIC,
            -- date
            _date_val,
            _date_text,
            (_ext->'checkDate'->>'confidence')::NUMERIC,
            _ext->'checkDate'->>'source',
            -- check_number
            COALESCE(_ext->'checkNumber'->>'value', _ext->>'checkNumber'),
            (_ext->'checkNumber'->>'confidence')::NUMERIC,
            _ext->'checkNumber'->>'source',
            -- bank
            COALESCE(_ext->'bankName'->>'value', _ext->>'bankName'),
            (_ext->'bankName'->>'confidence')::NUMERIC,
            _ext->'bankName'->>'source',
            -- memo
            COALESCE(_ext->'memo'->>'value', _ext->>'memo'),
            (_ext->'memo'->>'confidence')::NUMERIC,
            -- micr
            COALESCE(_micr->'routing'->>'value', _micr->>'routing'),
            (_micr->'routing'->>'confidence')::NUMERIC,
            COALESCE(_micr->'account'->>'value', _micr->>'account'),
            (_micr->'account'->>'confidence')::NUMERIC,
            COALESCE(_micr->'serial'->>'value', _micr->>'serial'),
            _micr->>'raw',
            -- raw results
            _ext,
            _check->'engine_results',
            'pending_review'
        )
        ON CONFLICT (job_id, check_id)
        DO UPDATE SET
            page_number     = EXCLUDED.page_number,
            image_width     = EXCLUDED.image_width,
            image_height    = EXCLUDED.image_height,
            file_url        = EXCLUDED.file_url,
            payee           = EXCLUDED.payee,
            payee_confidence = EXCLUDED.payee_confidence,
            amount          = EXCLUDED.amount,
            amount_raw      = EXCLUDED.amount_raw,
            amount_confidence = EXCLUDED.amount_confidence,
            check_date      = EXCLUDED.check_date,
            check_date_raw  = EXCLUDED.check_date_raw,
            check_date_confidence = EXCLUDED.check_date_confidence,
            check_number    = EXCLUDED.check_number,
            check_number_confidence = EXCLUDED.check_number_confidence,
            bank_name       = EXCLUDED.bank_name,
            bank_name_confidence = EXCLUDED.bank_name_confidence,
            memo            = EXCLUDED.memo,
            memo_confidence = EXCLUDED.memo_confidence,
            micr_routing    = EXCLUDED.micr_routing,
            micr_account    = EXCLUDED.micr_account,
            hybrid_results  = EXCLUDED.hybrid_results,
            updated_at      = now();
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ========================================================================
-- 020_align_checks_schema_with_live_db.sql
-- ========================================================================
-- ============================================================================
-- Migration 020: Align checks table schema with live DB
-- Fixes backend flatten_checks_from_job to work with actual live DB columns
-- ============================================================================

-- The live DB has a simpler schema than migrations 001/018 defined
-- This migration updates the flatten_checks_from_job function to only insert
-- columns that actually exist in the live checks table

CREATE OR REPLACE FUNCTION flatten_checks_from_job(p_job_id TEXT)
RETURNS void AS $$
DECLARE
    _job RECORD;
    _check JSONB;
    _ext JSONB;
    _amount_text TEXT;
    _amount_num NUMERIC;
    _date_text TEXT;
    _date_val DATE;
    _checks_array JSONB;
BEGIN
    SELECT * INTO _job FROM check_jobs WHERE job_id = p_job_id;
    IF NOT FOUND THEN RETURN; END IF;

    -- Parse checks_data from TEXT/JSONB to JSONB array
    BEGIN
        IF _job.checks_data IS NULL OR _job.checks_data = '' THEN
            RETURN;
        END IF;
        
        _checks_array := _job.checks_data::JSONB;
        
        IF jsonb_typeof(_checks_array) != 'array' THEN
            RAISE NOTICE 'checks_data is not an array for job %', p_job_id;
            RETURN;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Failed to parse checks_data for job %: %', p_job_id, SQLERRM;
        RETURN;
    END;

    -- Iterate over each check in the array
    FOR _check IN SELECT jsonb_array_elements(_checks_array)
    LOOP
        _ext := _check->'extraction';

        -- Parse amount
        _amount_text := COALESCE(
            _ext->'amount'->>'value',
            _ext->>'amount'
        );
        BEGIN
            _amount_num := regexp_replace(COALESCE(_amount_text,''), '[^0-9.]', '', 'g')::NUMERIC;
        EXCEPTION WHEN OTHERS THEN
            _amount_num := NULL;
        END;

        -- Parse date
        _date_text := COALESCE(
            _ext->'checkDate'->>'value',
            _ext->>'checkDate'
        );
        BEGIN
            _date_val := _date_text::DATE;
        EXCEPTION WHEN OTHERS THEN
            _date_val := NULL;
        END;

        -- Insert only columns that exist in live DB
        INSERT INTO checks (
            tenant_id,
            file_url,
            file_type,
            check_number,
            check_number_confidence,
            check_number_source,
            payee,
            payee_confidence,
            payee_source,
            amount,
            amount_confidence,
            amount_source,
            check_date,
            check_date_confidence,
            check_date_source,
            bank_name,
            bank_name_confidence,
            bank_name_source,
            memo,
            status,
            confidence_summary,
            processing_method,
            realm_id,
            check_id
        ) VALUES (
            COALESCE(_job.tenant_id, '00000000-0000-0000-0000-000000000000'::UUID),
            _check->>'image_url',
            'image/png',
            COALESCE(_ext->'checkNumber'->>'value', _ext->>'checkNumber'),
            (_ext->'checkNumber'->>'confidence')::NUMERIC,
            _ext->'checkNumber'->>'source',
            COALESCE(_ext->'payee'->>'value', _ext->>'payee'),
            (_ext->'payee'->>'confidence')::NUMERIC,
            _ext->'payee'->>'source',
            _amount_num,
            (_ext->'amount'->>'confidence')::NUMERIC,
            _ext->'amount'->>'source',
            _date_val,
            (_ext->'checkDate'->>'confidence')::NUMERIC,
            _ext->'checkDate'->>'source',
            COALESCE(_ext->'bankName'->>'value', _ext->>'bankName'),
            (_ext->'bankName'->>'confidence')::NUMERIC,
            _ext->'bankName'->>'source',
            COALESCE(_ext->'memo'->>'value', _ext->>'memo'),
            'pending_review',
            GREATEST(
                COALESCE((_ext->'checkNumber'->>'confidence')::NUMERIC, 0),
                COALESCE((_ext->'amount'->>'confidence')::NUMERIC, 0),
                COALESCE((_ext->'checkDate'->>'confidence')::NUMERIC, 0),
                COALESCE((_ext->'payee'->>'confidence')::NUMERIC, 0)
            ) / 4.0,
            CASE 
                WHEN _ext->>'source' IS NOT NULL THEN _ext->>'source'
                ELSE 'hybrid'
            END,
            NULL,
            _check->>'check_id'
        )
        ON CONFLICT (id) DO UPDATE SET
            file_url = EXCLUDED.file_url,
            payee = EXCLUDED.payee,
            payee_confidence = EXCLUDED.payee_confidence,
            amount = EXCLUDED.amount,
            amount_confidence = EXCLUDED.amount_confidence,
            check_date = EXCLUDED.check_date,
            check_date_confidence = EXCLUDED.check_date_confidence,
            check_number = EXCLUDED.check_number,
            check_number_confidence = EXCLUDED.check_number_confidence,
            bank_name = EXCLUDED.bank_name,
            bank_name_confidence = EXCLUDED.bank_name_confidence,
            memo = EXCLUDED.memo,
            confidence_summary = EXCLUDED.confidence_summary,
            updated_at = now();
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ========================================================================
-- 021_add_qb_source_to_transactions.sql
-- ========================================================================
-- Add qb_source to qb_transactions for entity-type filtering
-- Values: 'cheque_written' | 'bill_paid_by_cheque' | 'payroll_check'
-- Derived from txn_type when not explicitly provided (backward compatible)

ALTER TABLE public.qb_transactions
  ADD COLUMN IF NOT EXISTS qb_source TEXT;

CREATE INDEX IF NOT EXISTS idx_qb_transactions_qb_source ON qb_transactions(qb_source);

-- Back-fill existing rows from txn_type so nothing is null
UPDATE public.qb_transactions
SET qb_source = CASE
  WHEN txn_type = 'Purchase'    THEN 'cheque_written'
  WHEN txn_type = 'BillPayment' THEN 'bill_paid_by_cheque'
  WHEN txn_type = 'Check'       THEN 'payroll_check'
  ELSE NULL
END
WHERE qb_source IS NULL;

-- ========================================================================
-- 022_add_intuit_id_to_qb_entries.sql
-- ========================================================================
-- Migration 022: Add intuit_id column to qb_entries
-- intuit_id stores the raw Intuit entity ID (e.g. "614") extracted from the
-- compound id field (e.g. "purchase-614"). Storing it separately eliminates
-- string-parsing in APPROVE_AND_CLEAR and SAVE_QB_TXN handlers.

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_name = 'qb_entries' AND column_name = 'intuit_id'
  ) THEN
    ALTER TABLE qb_entries ADD COLUMN intuit_id TEXT;
  END IF;
END $$;

-- Back-fill existing rows: extract everything after the first dash in the id
-- e.g. "purchase-614" → "614", "billpayment-456" → "456"
UPDATE qb_entries
SET intuit_id = substring(id from position('-' in id) + 1)
WHERE intuit_id IS NULL AND id LIKE '%-%';

-- Index for lookups by intuit_id + tenant
CREATE INDEX IF NOT EXISTS idx_qb_entries_intuit_id ON qb_entries (intuit_id);

-- ========================================================================
-- 023_fix_qb_entries_rls_and_checks_status.sql
-- ========================================================================
-- Migration 023: Fix qb_entries RLS + add 'rejected' to checks.status constraint
--
-- Problem 1: Migration 005 created policies on qb_entries using `user_id = auth.uid()`
--   but qb_entries has NO user_id column → those CREATE POLICY statements errored,
--   leaving only the service_role policy. Authenticated users (anon key + JWT) cannot
--   SELECT or UPDATE qb_entries. Fix: replace with tenant_id-based policies.
--
-- Problem 2: checks.status CHECK constraint missing 'rejected'. The "Reject" button
--   sends status='rejected', which violates the constraint if it ever touches checks.id.
--   Fix: drop and recreate the constraint to include 'rejected'.

-- ── 1. Fix qb_entries RLS ─────────────────────────────────────────────────────

-- Drop the broken user_id-based policies (they may or may not exist)
DROP POLICY IF EXISTS "Users can view own qb entries" ON public.qb_entries;
DROP POLICY IF EXISTS "Users can manage own qb entries" ON public.qb_entries;

-- Ensure RLS is enabled
ALTER TABLE public.qb_entries ENABLE ROW LEVEL SECURITY;

-- Drop new policies too in case migration was partially applied
DROP POLICY IF EXISTS "Users can select own tenant qb_entries" ON public.qb_entries;
DROP POLICY IF EXISTS "Users can insert own tenant qb_entries" ON public.qb_entries;
DROP POLICY IF EXISTS "Users can update own tenant qb_entries" ON public.qb_entries;
DROP POLICY IF EXISTS "Users can delete own tenant qb_entries" ON public.qb_entries;

-- SELECT: authenticated users can read their own tenant's entries
CREATE POLICY "Users can select own tenant qb_entries"
  ON public.qb_entries FOR SELECT
  USING (tenant_id = public.user_tenant_id());

-- INSERT: authenticated users can insert for their own tenant
CREATE POLICY "Users can insert own tenant qb_entries"
  ON public.qb_entries FOR INSERT
  WITH CHECK (tenant_id = public.user_tenant_id());

-- UPDATE: authenticated users can update their own tenant's entries (needed for SAVE_QB_TXN)
CREATE POLICY "Users can update own tenant qb_entries"
  ON public.qb_entries FOR UPDATE
  USING (tenant_id = public.user_tenant_id())
  WITH CHECK (tenant_id = public.user_tenant_id());

-- DELETE: authenticated users can delete their own tenant's entries (used by pull-checks re-sync)
CREATE POLICY "Users can delete own tenant qb_entries"
  ON public.qb_entries FOR DELETE
  USING (tenant_id = public.user_tenant_id());

-- Service role retains full access
DROP POLICY IF EXISTS "Service role can manage qb_entries" ON public.qb_entries;
DROP POLICY IF EXISTS "Service role full access to qb_entries" ON public.qb_entries;
CREATE POLICY "Service role full access to qb_entries"
  ON public.qb_entries FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

-- ── 2. Add 'rejected' to checks.status constraint ────────────────────────────

ALTER TABLE public.checks
  DROP CONSTRAINT IF EXISTS checks_status_check;

ALTER TABLE public.checks
  ADD CONSTRAINT checks_status_check CHECK (
    status = ANY (ARRAY[
      'pending'::text,
      'processing'::text,
      'pending_review'::text,
      'approved'::text,
      'rejected'::text,
      'exported'::text,
      'error'::text
    ])
  );

-- ========================================================================
-- 024_add_cleared_status_to_qb_transactions.sql
-- ========================================================================
-- Migration 024: Add cleared_status to qb_transactions
-- Stores QB ClearedStatus ('None', 'Cleared', 'Reconciled') per transaction
-- Used by sync-qb.ts to auto-approve matches for transactions already cleared in QB

ALTER TABLE public.qb_transactions
  ADD COLUMN IF NOT EXISTS cleared_status TEXT;

COMMENT ON COLUMN public.qb_transactions.cleared_status IS
  'QB ClearedStatus value: NULL | None | Cleared | Reconciled';

-- ========================================================================
-- 025_fix_api_usage_logs_rls.sql
-- ========================================================================
-- ============================================================================
-- Fix tenant isolation on api_usage_logs
--
-- 012_add_api_usage_tracking.sql created:
--   CREATE POLICY "service_all" ON api_usage_logs FOR ALL USING (true) WITH CHECK (true);
--
-- That policy has no TO clause, so it applies to every role including
-- `authenticated`. Because permissive policies combine with OR, it grants
-- every signed-in user full read/write access to every tenant's usage rows
-- (tenant_id, job_id, check_id, token counts, costs) via the anon key.
--
-- 005_add_user_rls_policies.sql already dropped the equivalent policies on the
-- nine tables created in 001. api_usage_logs was added afterwards and missed
-- that cleanup. This migration applies the same pattern used in 005 and 013.
-- ============================================================================

DROP POLICY IF EXISTS "service_all" ON api_usage_logs;

-- Tenant members may read their own firm's usage (the billing page needs this).
CREATE POLICY "Users can view own tenant api usage"
  ON api_usage_logs FOR SELECT
  USING (tenant_id = public.user_tenant_id());

-- Writes come from the backend extraction pipeline only, never the browser.
CREATE POLICY "Service role full access to api_usage_logs"
  ON api_usage_logs FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

-- ========================================================================
-- 026_plans_trial_and_billing_period.sql
-- ========================================================================
-- ============================================================================
-- 026: Real plan names, trial clock, and the billing-period helper
--
-- Three things, all prerequisites for the usage ledger (027) and the trial
-- gate (029):
--
--   1. tenants.plan only allowed ('free','starter','professional',
--      'enterprise','pro') after migration 014. The real plans are
--      Essential / Professional / Scale (CHECKLIST section 7). The constraint
--      is WIDENED, not replaced: every legacy value stays valid so no existing
--      row breaks.
--   2. The trial clock (14 days / 250 successfully processed cheques) needs
--      somewhere to live. It goes on tenants, backfilled from created_at so
--      existing firms are not handed a fresh 14 days.
--   3. One function that answers "which billing period is this tenant in right
--      now", so the ledger, the Stripe reporter and the read endpoint all agree.
--
-- Idempotent: safe to re-run.
-- ============================================================================

-- ──────────────────────────────────────────────────────────────────────────────
-- 1. Widen tenants.plan
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'tenants' AND column_name = 'plan'
    ) THEN
        ALTER TABLE public.tenants ADD COLUMN plan TEXT NOT NULL DEFAULT 'free';
    END IF;
END $$;

ALTER TABLE public.tenants DROP CONSTRAINT IF EXISTS tenants_plan_check;
ALTER TABLE public.tenants ADD CONSTRAINT tenants_plan_check
    CHECK (plan IN (
        -- current plans (STRIPE-BILLING-REQUIREMENTS.md)
        'essential', 'professional', 'scale',
        -- legacy values already present in live rows; kept so nothing breaks
        'free', 'starter', 'enterprise', 'pro'
    ));

COMMENT ON COLUMN public.tenants.plan IS
    'Plan tier. Current: essential | professional | scale. Legacy values (free, starter, enterprise, pro) remain accepted for rows created before migration 026.';

-- ──────────────────────────────────────────────────────────────────────────────
-- 2. Trial clock + subscription status on tenants
-- ──────────────────────────────────────────────────────────────────────────────
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS trial_started_at   TIMESTAMPTZ;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS trial_ends_at      TIMESTAMPTZ;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS trial_check_limit  INTEGER NOT NULL DEFAULT 250;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS trial_days         INTEGER NOT NULL DEFAULT 14;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS subscription_status TEXT;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS subscription_started_at TIMESTAMPTZ;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS plan_check_allowance INTEGER;

-- Backfill: the trial started when the firm was created, not when this
-- migration ran. Running this twice must not extend anybody's trial, hence
-- the IS NULL guards.
UPDATE public.tenants
   SET trial_started_at = COALESCE(created_at, now())
 WHERE trial_started_at IS NULL;

UPDATE public.tenants
   SET trial_ends_at = trial_started_at + (COALESCE(trial_days, 14) || ' days')::interval
 WHERE trial_ends_at IS NULL;

UPDATE public.tenants
   SET subscription_status = 'trialing'
 WHERE subscription_status IS NULL;

ALTER TABLE public.tenants ALTER COLUMN subscription_status SET DEFAULT 'trialing';

ALTER TABLE public.tenants DROP CONSTRAINT IF EXISTS tenants_subscription_status_check;
ALTER TABLE public.tenants ADD CONSTRAINT tenants_subscription_status_check
    CHECK (subscription_status IN ('trialing', 'active', 'past_due', 'canceled', 'expired'));

COMMENT ON COLUMN public.tenants.trial_check_limit IS
    '250 successfully processed cheques, per CHECKLIST section 1/6. Counted from usage_ledger, not from check_jobs.';
COMMENT ON COLUMN public.tenants.plan_check_allowance IS
    'Included cheques per billing period once subscribed (Essential 1200, Professional 4500, Scale 10000). NULL while on trial.';

-- New signups get the clock set at insert time rather than relying on a
-- backfill. A trigger, not a column DEFAULT, because trial_ends_at depends on
-- trial_days which the row itself supplies.
CREATE OR REPLACE FUNCTION public.set_tenant_trial_window()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.trial_started_at IS NULL THEN
        NEW.trial_started_at := COALESCE(NEW.created_at, now());
    END IF;
    IF NEW.trial_ends_at IS NULL THEN
        NEW.trial_ends_at := NEW.trial_started_at
                             + (COALESCE(NEW.trial_days, 14) || ' days')::interval;
    END IF;
    IF NEW.subscription_status IS NULL THEN
        NEW.subscription_status := 'trialing';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = public;

DROP TRIGGER IF EXISTS trg_tenants_trial_window ON public.tenants;
CREATE TRIGGER trg_tenants_trial_window
    BEFORE INSERT ON public.tenants
    FOR EACH ROW EXECUTE FUNCTION public.set_tenant_trial_window();

-- ──────────────────────────────────────────────────────────────────────────────
-- 3. Billing period helper
--
--    "Renewal on the same date each month, regardless of when someone
--    subscribed" (CHECKLIST item 17). So the period is a monthly window
--    anchored on the tenant's anchor day, clamped for short months: an anchor
--    of the 31st lands on the 28th/29th/30th where that month has no 31st.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.current_billing_period(
    p_tenant_id UUID,
    p_at        TIMESTAMPTZ DEFAULT now()
)
RETURNS TABLE (period_start DATE, period_end DATE) AS $$
DECLARE
    _anchor_ts  TIMESTAMPTZ;
    _anchor_day INTEGER;
    _at         DATE := (p_at AT TIME ZONE 'UTC')::date;
    _month      DATE;
    _start      DATE;
BEGIN
    SELECT COALESCE(t.subscription_started_at, t.trial_started_at, t.created_at, p_at)
      INTO _anchor_ts
      FROM public.tenants t
     WHERE t.id = p_tenant_id;

    -- Unknown tenant: fall back to a calendar month so a caller still gets a
    -- usable, non-NULL window instead of an exception.
    _anchor_day := LEAST(EXTRACT(DAY FROM COALESCE(_anchor_ts, p_at))::int, 28);

    _month := date_trunc('month', _at)::date;
    _start := _month + (_anchor_day - 1);
    IF _start > _at THEN
        _month := (_month - INTERVAL '1 month')::date;
        _start := _month + (_anchor_day - 1);
    END IF;

    period_start := _start;
    period_end   := (_start + INTERVAL '1 month' - INTERVAL '1 day')::date;
    RETURN NEXT;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public;

GRANT EXECUTE ON FUNCTION public.current_billing_period(UUID, TIMESTAMPTZ) TO authenticated, service_role;

COMMENT ON FUNCTION public.current_billing_period(UUID, TIMESTAMPTZ) IS
    'The monthly billing window containing p_at for one tenant, anchored on the subscription (or trial) start day, clamped to day 28 so every month has the anchor.';

-- ========================================================================
-- 027_usage_ledger.sql
-- ========================================================================
-- ============================================================================
-- 027: The immutable usage ledger (CHECKLIST section 8)
--
-- One row per SUCCESSFULLY processed cheque. This table is the billing source
-- of truth, so it is append-only and the append is idempotent.
--
--   * Count on success only      — nothing inserts a row for a failed engine run.
--   * Several cheques on a page  — one row each; page_number is recorded, never
--                                  aggregated.
--   * Detected cheques, not pages — a 40-page statement with 6 cheques makes 6
--                                  rows, because the writer iterates detected
--                                  cheques.
--   * Idempotency                — UNIQUE (tenant_id, idempotency_key). An
--                                  automatic retry hits the constraint, not an
--                                  application-level "have I seen this" check.
--   * Repeat uploads count again — a new job_id produces a new idempotency key,
--                                  so the row is written. The warning before
--                                  that happens is upload_fingerprints (028).
--   * Immutable                  — a BEFORE UPDATE OR DELETE trigger raises,
--                                  and UPDATE/DELETE are revoked from anon and
--                                  authenticated. Belt and braces, because
--                                  either one alone has been bypassed before.
--
-- Idempotent: safe to re-run.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.usage_ledger (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Who is billed. ON DELETE RESTRICT, not CASCADE: a billing ledger that
    -- disappears with the tenant cannot be reconciled against Stripe after a
    -- dispute. Deleting a tenant now requires an explicit archival decision.
    tenant_id            UUID NOT NULL REFERENCES public.tenants(id) ON DELETE RESTRICT,

    -- Who caused it, and which QuickBooks company it belongs to.
    user_id              UUID REFERENCES auth.users(id) ON DELETE SET NULL,
    realm_id             TEXT,

    -- What was processed. check_jobs.job_id and checks.check_id are both TEXT
    -- in 001_schema.sql; no FK on check_id because checks rows are rewritten by
    -- flatten_checks_from_job() and the ledger must outlive that.
    job_id               TEXT REFERENCES public.check_jobs(job_id) ON DELETE SET NULL,
    check_id             TEXT NOT NULL,
    page_number          INTEGER,

    -- The processing event.
    event_type           TEXT NOT NULL DEFAULT 'check_processed'
        CHECK (event_type IN ('check_processed')),
    idempotency_key      TEXT NOT NULL,
    quantity             INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0),
    engines              TEXT[],
    occurred_at          TIMESTAMPTZ NOT NULL DEFAULT now(),

    -- Billing period, resolved at write time by current_billing_period().
    billing_period_start DATE NOT NULL,
    billing_period_end   DATE NOT NULL,

    -- TRUE when the tenant was warned the file was uploaded before and chose to
    -- process and be counted anyway (CHECKLIST section 8, Michael 30 Sept).
    is_reupload          BOOLEAN NOT NULL DEFAULT FALSE,

    -- Stripe reference. Nullable: metered-event submission is section 7 work.
    -- Write-once, enforced by the immutability trigger below.
    stripe_event_id      TEXT,
    stripe_reported_at   TIMESTAMPTZ,

    metadata             JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ── The idempotency guarantee ────────────────────────────────────────────────
-- This index IS the no-double-count rule. Scoped by tenant so two firms cannot
-- collide on a key, and so a key is never a cross-tenant oracle.
CREATE UNIQUE INDEX IF NOT EXISTS usage_ledger_idempotency_key_uniq
    ON public.usage_ledger (tenant_id, idempotency_key);

CREATE INDEX IF NOT EXISTS idx_usage_ledger_tenant_occurred
    ON public.usage_ledger (tenant_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_usage_ledger_tenant_period
    ON public.usage_ledger (tenant_id, billing_period_start);
CREATE INDEX IF NOT EXISTS idx_usage_ledger_job
    ON public.usage_ledger (job_id);
-- Partial index for the Stripe reporter: "rows not yet reported".
CREATE INDEX IF NOT EXISTS idx_usage_ledger_unreported
    ON public.usage_ledger (tenant_id, occurred_at)
    WHERE stripe_event_id IS NULL;

-- ──────────────────────────────────────────────────────────────────────────────
-- Immutability
--
-- The service role is allowed exactly one mutation: stamping stripe_event_id /
-- stripe_reported_at once, so section 7 can reconcile without a second table.
-- Everything else raises, including every DELETE from every role.
--
-- The service-role test is inlined rather than calling public.is_service_request()
-- (migration 030) so this migration does not depend on one numbered after it.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.usage_ledger_append_only()
RETURNS TRIGGER AS $$
DECLARE
    _claims TEXT := current_setting('request.jwt.claims', TRUE);
    _is_service BOOLEAN;
BEGIN
    -- No JWT at all means psql / a migration / the service key without claims.
    _is_service := _claims IS NULL
                OR _claims = ''
                OR COALESCE(_claims::jsonb ->> 'role' = 'service_role', FALSE);

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            'usage_ledger is append-only: DELETE is not permitted (id %)', OLD.id
            USING ERRCODE = 'restrict_violation';
    END IF;

    IF NOT _is_service THEN
        RAISE EXCEPTION
            'usage_ledger is append-only: UPDATE is not permitted'
            USING ERRCODE = 'restrict_violation';
    END IF;

    -- Service role: only the two Stripe columns may differ.
    IF (to_jsonb(NEW) - 'stripe_event_id' - 'stripe_reported_at')
       IS DISTINCT FROM
       (to_jsonb(OLD) - 'stripe_event_id' - 'stripe_reported_at') THEN
        RAISE EXCEPTION
            'usage_ledger is append-only: only stripe_event_id and stripe_reported_at may be updated'
            USING ERRCODE = 'restrict_violation';
    END IF;

    IF OLD.stripe_event_id IS NOT NULL
       AND NEW.stripe_event_id IS DISTINCT FROM OLD.stripe_event_id THEN
        RAISE EXCEPTION
            'usage_ledger.stripe_event_id is write-once (id %)', OLD.id
            USING ERRCODE = 'restrict_violation';
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = public;

DROP TRIGGER IF EXISTS trg_usage_ledger_append_only ON public.usage_ledger;
CREATE TRIGGER trg_usage_ledger_append_only
    BEFORE UPDATE OR DELETE ON public.usage_ledger
    FOR EACH ROW EXECUTE FUNCTION public.usage_ledger_append_only();

-- Second, independent lock: the grant. Even if the trigger were dropped, a
-- tenant session has no UPDATE or DELETE privilege to use.
REVOKE UPDATE, DELETE, TRUNCATE ON public.usage_ledger FROM authenticated;
REVOKE UPDATE, DELETE, TRUNCATE ON public.usage_ledger FROM anon;
REVOKE INSERT ON public.usage_ledger FROM authenticated;
REVOKE INSERT ON public.usage_ledger FROM anon;
GRANT SELECT ON public.usage_ledger TO authenticated;

-- ──────────────────────────────────────────────────────────────────────────────
-- RLS: a tenant member reads their own firm's rows and nothing else.
-- There is deliberately no INSERT/UPDATE/DELETE policy for `authenticated`;
-- writes come from the backend pipeline under the service key.
-- ──────────────────────────────────────────────────────────────────────────────
ALTER TABLE public.usage_ledger ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own tenant usage_ledger" ON public.usage_ledger;
CREATE POLICY "Users can view own tenant usage_ledger"
    ON public.usage_ledger FOR SELECT
    TO authenticated
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Service role full access to usage_ledger" ON public.usage_ledger;
CREATE POLICY "Service role full access to usage_ledger"
    ON public.usage_ledger FOR ALL
    TO service_role
    USING (true)
    WITH CHECK (true);

-- ──────────────────────────────────────────────────────────────────────────────
-- The one writer.
--
-- SECURITY DEFINER so the backend can call it as an RPC, and so the billing
-- period is computed inside the same statement as the insert. ON CONFLICT DO
-- NOTHING leans on the unique index: a retry is absorbed by the constraint.
--
-- Returns {recorded, duplicate, ledger_id, billing_period_start/end}. A caller
-- that gets duplicate=true has learnt the retry was already counted; it must
-- not treat that as an error.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.record_check_processed(
    p_tenant_id       UUID,
    p_check_id        TEXT,
    p_idempotency_key TEXT,
    p_job_id          TEXT    DEFAULT NULL,
    p_user_id         UUID    DEFAULT NULL,
    p_realm_id        TEXT    DEFAULT NULL,
    p_page_number     INTEGER DEFAULT NULL,
    p_engines         TEXT[]  DEFAULT NULL,
    p_is_reupload     BOOLEAN DEFAULT FALSE,
    p_occurred_at     TIMESTAMPTZ DEFAULT now(),
    p_metadata        JSONB   DEFAULT '{}'::jsonb
)
RETURNS JSONB AS $$
DECLARE
    _start DATE;
    _end   DATE;
    _id    UUID;
BEGIN
    IF p_tenant_id IS NULL THEN
        RAISE EXCEPTION 'record_check_processed: tenant_id is required';
    END IF;
    IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
        RAISE EXCEPTION 'record_check_processed: idempotency_key is required';
    END IF;
    IF p_check_id IS NULL OR btrim(p_check_id) = '' THEN
        RAISE EXCEPTION 'record_check_processed: check_id is required';
    END IF;

    SELECT period_start, period_end
      INTO _start, _end
      FROM public.current_billing_period(p_tenant_id, p_occurred_at);

    INSERT INTO public.usage_ledger (
        tenant_id, user_id, realm_id, job_id, check_id, page_number,
        event_type, idempotency_key, quantity, engines, occurred_at,
        billing_period_start, billing_period_end, is_reupload, metadata
    ) VALUES (
        p_tenant_id, p_user_id, p_realm_id, p_job_id, p_check_id, p_page_number,
        'check_processed', p_idempotency_key, 1, p_engines, p_occurred_at,
        _start, _end, COALESCE(p_is_reupload, FALSE), COALESCE(p_metadata, '{}'::jsonb)
    )
    ON CONFLICT (tenant_id, idempotency_key) DO NOTHING
    RETURNING id INTO _id;

    IF _id IS NULL THEN
        SELECT id INTO _id
          FROM public.usage_ledger
         WHERE tenant_id = p_tenant_id AND idempotency_key = p_idempotency_key;
        RETURN jsonb_build_object(
            'recorded', FALSE, 'duplicate', TRUE, 'ledger_id', _id,
            'billing_period_start', _start, 'billing_period_end', _end
        );
    END IF;

    RETURN jsonb_build_object(
        'recorded', TRUE, 'duplicate', FALSE, 'ledger_id', _id,
        'billing_period_start', _start, 'billing_period_end', _end
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- Only the backend records usage. `authenticated` must not be able to mint
-- billable events, and must not be able to suppress them either.
REVOKE ALL ON FUNCTION public.record_check_processed(
    UUID, TEXT, TEXT, TEXT, UUID, TEXT, INTEGER, TEXT[], BOOLEAN, TIMESTAMPTZ, JSONB
) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.record_check_processed(
    UUID, TEXT, TEXT, TEXT, UUID, TEXT, INTEGER, TEXT[], BOOLEAN, TIMESTAMPTZ, JSONB
) FROM authenticated, anon;
GRANT EXECUTE ON FUNCTION public.record_check_processed(
    UUID, TEXT, TEXT, TEXT, UUID, TEXT, INTEGER, TEXT[], BOOLEAN, TIMESTAMPTZ, JSONB
) TO service_role;

COMMENT ON TABLE public.usage_ledger IS
    'Append-only billing ledger: one row per successfully processed cheque. Immutable by trigger and by revoked privileges. Idempotent on (tenant_id, idempotency_key).';
COMMENT ON COLUMN public.usage_ledger.idempotency_key IS
    'Stable per processing event. Backend format: <job_id>:<check_id>:<attempt-scope>. The UNIQUE index on (tenant_id, idempotency_key) is what prevents double-counting.';
COMMENT ON FUNCTION public.record_check_processed(UUID, TEXT, TEXT, TEXT, UUID, TEXT, INTEGER, TEXT[], BOOLEAN, TIMESTAMPTZ, JSONB) IS
    'The only writer of usage_ledger. Service role only. Absorbs retries via ON CONFLICT DO NOTHING on the idempotency index.';

-- ========================================================================
-- 028_upload_fingerprints.sql
-- ========================================================================
-- ============================================================================
-- 028: Database-backed duplicate detection (CHECKLIST section 1, blocking)
--
-- backend/api_server.py compared each upload against the in-memory `jobs`
-- dict, with a comment admitting it ("check in-memory jobs only, not DB").
-- After a restart the same PDF produced a brand new job, so identical customer
-- behaviour was billed differently. That makes the usage ledger untrustworthy,
-- which is why this is a prerequisite for 027 in practice.
--
-- One row per (tenant, content hash). The content hash is of the PDF BYTES, so
-- a renamed copy is still recognised; file_name and file_size are recorded for
-- the message, not for the match.
--
-- Idempotent: safe to re-run.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.upload_fingerprints (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id         UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    user_id           UUID REFERENCES auth.users(id) ON DELETE SET NULL,

    -- Algorithm-prefixed, e.g. 'sha256:ab12…'. Prefixed so the older md5
    -- fingerprints the backend used can coexist without being mistaken for
    -- sha256 ones.
    content_hash      TEXT NOT NULL,

    file_name         TEXT NOT NULL,
    file_size         BIGINT,

    -- The job the FIRST upload created, and the most recent one.
    first_job_id      TEXT,
    last_job_id       TEXT,

    first_uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_uploaded_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    upload_count      INTEGER NOT NULL DEFAULT 1 CHECK (upload_count > 0),

    UNIQUE (tenant_id, content_hash)
);

CREATE INDEX IF NOT EXISTS idx_upload_fingerprints_tenant_hash
    ON public.upload_fingerprints (tenant_id, content_hash);
CREATE INDEX IF NOT EXISTS idx_upload_fingerprints_tenant_recent
    ON public.upload_fingerprints (tenant_id, last_uploaded_at DESC);

-- ── RLS ──────────────────────────────────────────────────────────────────────
ALTER TABLE public.upload_fingerprints ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own tenant upload_fingerprints" ON public.upload_fingerprints;
CREATE POLICY "Users can view own tenant upload_fingerprints"
    ON public.upload_fingerprints FOR SELECT
    TO authenticated
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Service role full access to upload_fingerprints" ON public.upload_fingerprints;
CREATE POLICY "Service role full access to upload_fingerprints"
    ON public.upload_fingerprints FOR ALL
    TO service_role
    USING (true)
    WITH CHECK (true);

-- The browser never writes a fingerprint: a tenant that could insert one could
-- claim a file was "already uploaded" and a tenant that could delete one could
-- erase the warning.
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.upload_fingerprints FROM authenticated;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.upload_fingerprints FROM anon;
GRANT SELECT ON public.upload_fingerprints TO authenticated;

-- ──────────────────────────────────────────────────────────────────────────────
-- register_upload_fingerprint()
--
-- Records this upload and returns what was known BEFORE it, so the caller can
-- say "uploaded previously on <date>". Returns:
--   { duplicate, previous_uploaded_at, previous_job_id, previous_upload_count,
--     previous_file_name, upload_count }
--
-- One statement, so two concurrent uploads of the same file cannot both see
-- "no previous upload".
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.register_upload_fingerprint(
    p_tenant_id    UUID,
    p_content_hash TEXT,
    p_file_name    TEXT,
    p_file_size    BIGINT DEFAULT NULL,
    p_job_id       TEXT   DEFAULT NULL,
    p_user_id      UUID   DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
    _prev public.upload_fingerprints;
    _new_count INTEGER;
BEGIN
    IF p_tenant_id IS NULL THEN
        RAISE EXCEPTION 'register_upload_fingerprint: tenant_id is required';
    END IF;
    IF p_content_hash IS NULL OR btrim(p_content_hash) = '' THEN
        RAISE EXCEPTION 'register_upload_fingerprint: content_hash is required';
    END IF;

    SELECT * INTO _prev
      FROM public.upload_fingerprints
     WHERE tenant_id = p_tenant_id AND content_hash = p_content_hash;

    INSERT INTO public.upload_fingerprints (
        tenant_id, user_id, content_hash, file_name, file_size,
        first_job_id, last_job_id
    ) VALUES (
        p_tenant_id, p_user_id, p_content_hash,
        COALESCE(p_file_name, 'unknown.pdf'), p_file_size,
        p_job_id, p_job_id
    )
    ON CONFLICT (tenant_id, content_hash) DO UPDATE
        SET last_uploaded_at = now(),
            last_job_id      = COALESCE(EXCLUDED.last_job_id, upload_fingerprints.last_job_id),
            upload_count     = upload_fingerprints.upload_count + 1,
            file_name        = COALESCE(EXCLUDED.file_name, upload_fingerprints.file_name)
    RETURNING upload_count INTO _new_count;

    RETURN jsonb_build_object(
        'duplicate',             _prev.id IS NOT NULL,
        'previous_uploaded_at',  _prev.first_uploaded_at,
        'previous_job_id',       COALESCE(_prev.last_job_id, _prev.first_job_id),
        'previous_upload_count', COALESCE(_prev.upload_count, 0),
        'previous_file_name',    _prev.file_name,
        'upload_count',          _new_count
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

REVOKE ALL ON FUNCTION public.register_upload_fingerprint(UUID, TEXT, TEXT, BIGINT, TEXT, UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.register_upload_fingerprint(UUID, TEXT, TEXT, BIGINT, TEXT, UUID) FROM authenticated, anon;
GRANT EXECUTE ON FUNCTION public.register_upload_fingerprint(UUID, TEXT, TEXT, BIGINT, TEXT, UUID) TO service_role;

COMMENT ON TABLE public.upload_fingerprints IS
    'Durable duplicate detection: one row per (tenant, PDF content hash). Replaces the in-memory check in backend/api_server.py that reset on every restart.';
COMMENT ON COLUMN public.upload_fingerprints.content_hash IS
    'Algorithm-prefixed hash of the PDF bytes, e.g. sha256:<hex>. Matches on content, so a renamed copy is still detected.';

-- ========================================================================
-- 029_comp_grants_and_trial_gate.sql
-- ========================================================================
-- ============================================================================
-- 029: Comp accounts (CHECKLIST section 5) and the server-side trial gate
--      (CHECKLIST sections 1 and 6)
--
-- Trial: 14 days OR 250 successfully processed cheques, whichever comes first.
-- No card. When it ends, PROCESSING stops and HISTORY stays readable — so the
-- gate is a single function the write paths call, and nothing is revoked from
-- the read paths.
--
-- Comp account: a Super Admin grants a free account for a set period, with a
-- reason and an expiry. A live comp grant overrides the trial limits so a pilot
-- firm is never cut off mid-test. Every grant and revocation is written to
-- audit_logs by a trigger, so the log cannot be skipped by a caller that
-- forgets.
--
-- Idempotent: safe to re-run.
-- ============================================================================

-- ──────────────────────────────────────────────────────────────────────────────
-- 1. comp_grants
-- ──────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.comp_grants (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id      UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,

    -- Who granted it. The email is stored as well as the id because Super Admin
    -- is an email allowlist (frontend/lib/super-admin.ts), not a database role,
    -- and the log has to remain readable if the account is later removed.
    granted_by       UUID REFERENCES auth.users(id) ON DELETE SET NULL,
    granted_by_email TEXT NOT NULL,

    -- Required, and required to be meaningful. "This is how the pilot firms get
    -- in" — a blank reason makes the audit log worthless.
    reason         TEXT NOT NULL CHECK (length(btrim(reason)) >= 3),

    starts_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at     TIMESTAMPTZ NOT NULL,

    -- NULL = unlimited cheques for the comp period. A number caps it.
    check_limit    INTEGER CHECK (check_limit IS NULL OR check_limit > 0),

    revoked_at     TIMESTAMPTZ,
    revoked_by     UUID REFERENCES auth.users(id) ON DELETE SET NULL,
    revoke_reason  TEXT,

    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT comp_grants_window_check CHECK (expires_at > starts_at)
);

CREATE INDEX IF NOT EXISTS idx_comp_grants_tenant ON public.comp_grants (tenant_id);
-- "Which grant is live" is resolved by window, not by a partial unique index:
-- the predicate would need now(), which is not immutable, and a lapsed but
-- un-revoked grant would otherwise block ever granting a new one.
-- tenant_usage_state() takes the grant with the latest expires_at.
CREATE INDEX IF NOT EXISTS idx_comp_grants_tenant_window
    ON public.comp_grants (tenant_id, expires_at DESC)
    WHERE revoked_at IS NULL;

-- ── RLS: a tenant may SEE that it is comped (the meter says so) but may not
--    create, extend or revoke a grant. All writes are service-role.
ALTER TABLE public.comp_grants ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own tenant comp_grants" ON public.comp_grants;
CREATE POLICY "Users can view own tenant comp_grants"
    ON public.comp_grants FOR SELECT
    TO authenticated
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Service role full access to comp_grants" ON public.comp_grants;
CREATE POLICY "Service role full access to comp_grants"
    ON public.comp_grants FOR ALL
    TO service_role
    USING (true)
    WITH CHECK (true);

REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.comp_grants FROM authenticated;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.comp_grants FROM anon;
GRANT SELECT ON public.comp_grants TO authenticated;

-- ──────────────────────────────────────────────────────────────────────────────
-- 2. "Every override is logged" — enforced by trigger, not by the caller
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.log_comp_grant_change()
RETURNS TRIGGER AS $$
DECLARE
    _action TEXT;
    _actor  UUID;
    -- Captured before the branch: OLD is unassigned on INSERT, so it must not
    -- be touched inside a CASE whose evaluation order is not guaranteed.
    _old    TEXT := NULL;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        _old := to_jsonb(OLD)::text;
    END IF;

    IF TG_OP = 'INSERT' THEN
        _action := 'comp_account.granted';
        _actor  := NEW.granted_by;
    ELSIF NEW.revoked_at IS NOT NULL AND OLD.revoked_at IS NULL THEN
        _action := 'comp_account.revoked';
        _actor  := NEW.revoked_by;
    ELSE
        _action := 'comp_account.updated';
        _actor  := NEW.granted_by;
    END IF;

    INSERT INTO public.audit_logs (tenant_id, user_id, action, old_value, new_value, metadata)
    VALUES (
        NEW.tenant_id,
        _actor,
        _action,
        _old,
        to_jsonb(NEW)::text,
        jsonb_build_object(
            'comp_grant_id',    NEW.id,
            'granted_by_email', NEW.granted_by_email,
            'reason',           NEW.reason,
            'starts_at',        NEW.starts_at,
            'expires_at',       NEW.expires_at,
            'check_limit',      NEW.check_limit,
            'revoke_reason',    NEW.revoke_reason
        )
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

DROP TRIGGER IF EXISTS trg_comp_grants_audit ON public.comp_grants;
CREATE TRIGGER trg_comp_grants_audit
    AFTER INSERT OR UPDATE ON public.comp_grants
    FOR EACH ROW EXECUTE FUNCTION public.log_comp_grant_change();

-- ──────────────────────────────────────────────────────────────────────────────
-- 3. tenant_usage_state() — the one answer the UI and both write paths read
--
-- SECURITY DEFINER so it can read tenants and count the ledger, with an
-- explicit caller check: a signed-in user may only ask about their own firm.
-- Without that check a DEFINER function would be a cross-tenant read.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.tenant_usage_state(
    p_tenant_id UUID,
    p_at        TIMESTAMPTZ DEFAULT now()
)
RETURNS JSONB AS $$
DECLARE
    _claims     TEXT := current_setting('request.jwt.claims', TRUE);
    _is_service BOOLEAN;
    _t          public.tenants;
    _comp       public.comp_grants;
    _is_comped  BOOLEAN := FALSE;
    _p_start    DATE;
    _p_end      DATE;
    _used_period  INTEGER := 0;
    _used_trial   INTEGER := 0;
    _used_comp    INTEGER := 0;
    _days_left    INTEGER;
    _checks_left  INTEGER;
    _allowed      BOOLEAN;
    _reason       TEXT := NULL;
    _allowance    INTEGER;
BEGIN
    _is_service := _claims IS NULL
                OR _claims = ''
                OR COALESCE(_claims::jsonb ->> 'role' = 'service_role', FALSE);

    IF NOT _is_service AND p_tenant_id IS DISTINCT FROM public.user_tenant_id() THEN
        RAISE EXCEPTION 'tenant_usage_state: not permitted for another tenant'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO _t FROM public.tenants WHERE id = p_tenant_id;
    IF _t.id IS NULL THEN
        RETURN jsonb_build_object(
            'tenant_id', p_tenant_id,
            'processing_allowed', FALSE,
            'block_reason', 'unknown_tenant'
        );
    END IF;

    SELECT period_start, period_end INTO _p_start, _p_end
      FROM public.current_billing_period(p_tenant_id, p_at);

    SELECT COALESCE(SUM(quantity), 0) INTO _used_period
      FROM public.usage_ledger
     WHERE tenant_id = p_tenant_id
       AND billing_period_start = _p_start;

    SELECT COALESCE(SUM(quantity), 0) INTO _used_trial
      FROM public.usage_ledger
     WHERE tenant_id = p_tenant_id
       AND occurred_at >= COALESCE(_t.trial_started_at, _t.created_at, p_at);

    -- Live comp grant: not revoked, and p_at inside its window.
    SELECT * INTO _comp
      FROM public.comp_grants
     WHERE tenant_id = p_tenant_id
       AND revoked_at IS NULL
       AND starts_at <= p_at
       AND expires_at > p_at
     ORDER BY expires_at DESC
     LIMIT 1;

    _is_comped := _comp.id IS NOT NULL;

    IF _is_comped THEN
        SELECT COALESCE(SUM(quantity), 0) INTO _used_comp
          FROM public.usage_ledger
         WHERE tenant_id = p_tenant_id
           AND occurred_at >= _comp.starts_at;
    END IF;

    _allowance := _t.plan_check_allowance;

    -- ── Resolution order. Comp first, so a pilot firm is never cut off. ──
    IF _is_comped THEN
        _days_left   := GREATEST(0, CEIL(EXTRACT(EPOCH FROM (_comp.expires_at - p_at)) / 86400.0))::int;
        _checks_left := CASE WHEN _comp.check_limit IS NULL
                            THEN NULL
                            ELSE GREATEST(0, _comp.check_limit - _used_comp) END;
        _allowed := _comp.check_limit IS NULL OR _used_comp < _comp.check_limit;
        IF NOT _allowed THEN _reason := 'comp_check_limit_reached'; END IF;

    ELSIF _t.subscription_status = 'active' THEN
        -- Paid: overage is billed, not blocked (CHECKLIST section 7).
        _days_left   := NULL;
        _checks_left := CASE WHEN _allowance IS NULL
                            THEN NULL
                            ELSE GREATEST(0, _allowance - _used_period) END;
        _allowed := TRUE;

    ELSIF _t.subscription_status IN ('past_due', 'canceled', 'expired') THEN
        _days_left   := 0;
        _checks_left := 0;
        _allowed     := FALSE;
        _reason      := 'subscription_' || _t.subscription_status;

    ELSE
        -- Trialing. 14 days OR 250 cheques, whichever comes first.
        _days_left   := GREATEST(0, CEIL(EXTRACT(EPOCH FROM (_t.trial_ends_at - p_at)) / 86400.0))::int;
        _checks_left := GREATEST(0, COALESCE(_t.trial_check_limit, 250) - _used_trial);
        IF _t.trial_ends_at <= p_at THEN
            _allowed := FALSE;
            _reason  := 'trial_expired';
        ELSIF _used_trial >= COALESCE(_t.trial_check_limit, 250) THEN
            _allowed := FALSE;
            _reason  := 'trial_check_limit_reached';
        ELSE
            _allowed := TRUE;
        END IF;
    END IF;

    RETURN jsonb_build_object(
        'tenant_id',               p_tenant_id,
        'plan',                    _t.plan,
        'subscription_status',     _t.subscription_status,
        'as_of',                   p_at,

        'trial_started_at',        _t.trial_started_at,
        'trial_ends_at',           _t.trial_ends_at,
        'trial_check_limit',       COALESCE(_t.trial_check_limit, 250),
        'trial_checks_used',       _used_trial,

        'days_remaining',          _days_left,
        'checks_remaining',        _checks_left,

        'billing_period_start',    _p_start,
        'billing_period_end',      _p_end,
        'checks_used_this_period', _used_period,
        'plan_check_allowance',    _allowance,

        'is_comped',               _is_comped,
        'comp_expires_at',         _comp.expires_at,
        'comp_reason',             _comp.reason,
        'comp_check_limit',        _comp.check_limit,
        'comp_checks_used',        CASE WHEN _is_comped THEN _used_comp ELSE NULL END,

        'processing_allowed',      _allowed,
        'block_reason',            _reason
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public;

GRANT EXECUTE ON FUNCTION public.tenant_usage_state(UUID, TIMESTAMPTZ) TO authenticated, service_role;

-- ──────────────────────────────────────────────────────────────────────────────
-- 4. processing_allowed() — the gate itself, so a write path is one call
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.processing_allowed(
    p_tenant_id UUID,
    p_at        TIMESTAMPTZ DEFAULT now()
)
RETURNS BOOLEAN AS $$
  SELECT COALESCE(
           (public.tenant_usage_state(p_tenant_id, p_at) ->> 'processing_allowed')::boolean,
           FALSE
         )
$$ LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = public;

GRANT EXECUTE ON FUNCTION public.processing_allowed(UUID, TIMESTAMPTZ) TO authenticated, service_role;

COMMENT ON TABLE public.comp_grants IS
    'Super Admin comp accounts: free access for a set period, with a mandatory reason and expiry. A live grant overrides the trial limits. Every change is written to audit_logs by trigger.';
COMMENT ON FUNCTION public.tenant_usage_state(UUID, TIMESTAMPTZ) IS
    'Single resolver for trial/comp/subscription state: days remaining, cheques remaining, cheques used this period, processing_allowed, is_comped. Read by the trial meter endpoint and by both write paths.';
COMMENT ON FUNCTION public.processing_allowed(UUID, TIMESTAMPTZ) IS
    'The server-side trial gate. Blocks processing only; nothing here restricts reading history.';

-- ========================================================================
-- 030_roles_team_rls_and_mfa.sql
-- ========================================================================
-- ============================================================================
-- 030: Two product roles (Administrator / User), team-invitation RLS, MFA
-- ============================================================================
-- Product role mapping (see frontend/lib/roles.ts — single source of truth):
--   Administrator -> user_profiles.role = 'admin'
--   User          -> user_profiles.role = 'member'  (and legacy 'viewer')
-- No new role column is introduced. 'viewer' is kept for backwards
-- compatibility and behaves as a read-only User.
--
-- Defect-history notes honoured here:
--   * Migration 010 exists because policies ON user_profiles that read
--     user_profiles recursed. NOTHING in this file adds a policy on
--     user_profiles. Role escalation is blocked with a BEFORE UPDATE trigger
--     that only reads OLD/NEW — no query, no recursion.
--   * 001_schema.sql left `service_all ... USING (true)` permissive policies on
--     several tables. Permissive policies OR together, so a new permissive
--     policy cannot restrict anything. Every gate below is AS RESTRICTIVE,
--     which ANDs, and therefore holds even with `USING (true)` still present.
--     Restrictive policies with no TO clause also apply to `anon`, where
--     user_tenant_id() is NULL -> zero rows.
--   * service_role has BYPASSRLS in Supabase, so backend writes are unaffected.
-- Fully idempotent; follows the guarded DO $$ style of 014.
-- ============================================================================

-- ──────────────────────────────────────────────────────────────────────────────
-- 1. Role column exists on whichever profile table this database has
--    (001 created `profiles`; the live database uses `user_profiles` — see 007)
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
    t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY['user_profiles', 'profiles'] LOOP
        IF EXISTS (
            SELECT 1 FROM information_schema.tables
            WHERE table_schema = 'public' AND table_name = t
        ) THEN
            IF NOT EXISTS (
                SELECT 1 FROM information_schema.columns
                WHERE table_schema = 'public' AND table_name = t AND column_name = 'role'
            ) THEN
                EXECUTE format('ALTER TABLE public.%I ADD COLUMN role TEXT NOT NULL DEFAULT ''member''', t);
            END IF;

            EXECUTE format('ALTER TABLE public.%I DROP CONSTRAINT IF EXISTS %I', t, t || '_role_check');
            EXECUTE format(
                'ALTER TABLE public.%I ADD CONSTRAINT %I CHECK (role IN (''admin'',''member'',''viewer''))',
                t, t || '_role_check'
            );

            -- MFA enrolment timestamp (cache for UI + Super Admin view; the
            -- authoritative factor list lives in auth.mfa_factors)
            EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS mfa_enrolled_at TIMESTAMPTZ', t);
        END IF;
    END LOOP;
END $$;

-- ──────────────────────────────────────────────────────────────────────────────
-- 2. Non-recursive role helpers
--    SECURITY DEFINER so they run as the owner and do not re-enter RLS.
--    They read the profile table but are only ever CALLED FROM POLICIES ON
--    OTHER TABLES, so there is no recursion even if the definer bypass fails.
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
    profile_table TEXT;
BEGIN
    SELECT table_name INTO profile_table
    FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name IN ('user_profiles', 'profiles')
    ORDER BY CASE table_name WHEN 'user_profiles' THEN 0 ELSE 1 END
    LIMIT 1;

    IF profile_table IS NULL THEN
        RAISE WARNING '030: no user_profiles/profiles table found; skipping role helpers';
        RETURN;
    END IF;

    EXECUTE format($f$
        CREATE OR REPLACE FUNCTION public.user_role()
        RETURNS TEXT AS $body$
          SELECT role FROM public.%I WHERE id = auth.uid()
        $body$ LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = public;
    $f$, profile_table);

    -- user_tenant_id() already exists (migration 008) but recreate defensively
    -- against the same table so fresh databases get it too.
    EXECUTE format($f$
        CREATE OR REPLACE FUNCTION public.user_tenant_id()
        RETURNS UUID AS $body$
          SELECT tenant_id FROM public.%I WHERE id = auth.uid()
        $body$ LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = public;
    $f$, profile_table);
END $$;

CREATE OR REPLACE FUNCTION public.is_tenant_admin()
RETURNS BOOLEAN AS $$
  SELECT COALESCE(public.user_role() = 'admin', FALSE)
$$ LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = public;

-- True for a service-role API request, and for a direct database session with
-- no JWT at all (psql / migrations), so operators are not locked out.
-- Deliberately does NOT look at current_user: callers below are SECURITY
-- DEFINER, where current_user is the function owner and would always match.
CREATE OR REPLACE FUNCTION public.is_service_request()
RETURNS BOOLEAN AS $$
  SELECT current_setting('request.jwt.claims', TRUE) IS NULL
      OR current_setting('request.jwt.claims', TRUE) = ''
      OR COALESCE(
           current_setting('request.jwt.claims', TRUE)::jsonb ->> 'role' = 'service_role',
           FALSE
         )
$$ LANGUAGE SQL STABLE;

GRANT EXECUTE ON FUNCTION public.user_role() TO authenticated, anon;
GRANT EXECUTE ON FUNCTION public.is_tenant_admin() TO authenticated, anon;

-- ──────────────────────────────────────────────────────────────────────────────
-- 3. Privilege-escalation guard on the profile table
--    A self-only UPDATE policy (migration 010) would otherwise let a 'member'
--    set their own role to 'admin'. Trigger only, to avoid RLS recursion.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.guard_profile_privileges()
RETURNS TRIGGER AS $$
BEGIN
    IF public.is_service_request() THEN
        RETURN NEW;
    END IF;

    -- Nobody may move themselves between firms.
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN
        RAISE EXCEPTION 'tenant_id cannot be changed by a user request';
    END IF;

    -- Role changes never happen on the caller's own row, and only an existing
    -- admin may change anyone's role. OLD.role is read from the row itself,
    -- so no query and no recursion.
    IF NEW.role IS DISTINCT FROM OLD.role THEN
        IF auth.uid() = OLD.id THEN
            RAISE EXCEPTION 'you cannot change your own role';
        END IF;
        IF COALESCE(public.user_role(), '') <> 'admin' THEN
            RAISE EXCEPTION 'only an Administrator may change roles';
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = public;

DO $$
DECLARE
    t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY['user_profiles', 'profiles'] LOOP
        IF EXISTS (
            SELECT 1 FROM information_schema.tables
            WHERE table_schema = 'public' AND table_name = t
        ) THEN
            EXECUTE format('DROP TRIGGER IF EXISTS guard_profile_privileges ON public.%I', t);
            EXECUTE format(
                'CREATE TRIGGER guard_profile_privileges BEFORE UPDATE ON public.%I '
                || 'FOR EACH ROW EXECUTE FUNCTION public.guard_profile_privileges()', t
            );
        END IF;
    END LOOP;
END $$;

-- ──────────────────────────────────────────────────────────────────────────────
-- 4. team_invitations: tenant-scoped AND Administrator-only
--    RESTRICTIVE with no TO clause => applies to anon too (zero rows).
-- ──────────────────────────────────────────────────────────────────────────────
-- VERIFIED AGAINST THE LIVE DATABASE: team_invitations does NOT exist there.
-- 001_schema.sql declares it, but 001 was never fully applied (`profiles` and
-- `tenant_settings` are missing too). So create it here, with 001's definition
-- verbatim, rather than assuming it is present.
CREATE TABLE IF NOT EXISTS public.team_invitations (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    email       TEXT NOT NULL,
    role        TEXT NOT NULL DEFAULT 'member'
        CHECK (role IN ('admin','member','viewer')),
    invited_by  UUID REFERENCES auth.users(id),
    status      TEXT NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending','accepted','expired')),
    token       TEXT NOT NULL DEFAULT encode(gen_random_bytes(32), 'hex') UNIQUE,
    expires_at  TIMESTAMPTZ NOT NULL DEFAULT (now() + interval '7 days'),
    created_at  TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS team_invitations_tenant_idx
    ON public.team_invitations (tenant_id, status);
CREATE INDEX IF NOT EXISTS team_invitations_email_idx
    ON public.team_invitations (lower(email));

ALTER TABLE public.team_invitations ENABLE ROW LEVEL SECURITY;

-- The invite token is a bearer secret; it is only ever read through the
-- service client in /api/team/invitations/[token]. No anon read path.
DROP POLICY IF EXISTS "team_invitations_tenant_admin_only" ON public.team_invitations;
CREATE POLICY "team_invitations_tenant_admin_only"
  ON public.team_invitations
  AS RESTRICTIVE
  FOR ALL
  USING (tenant_id = public.user_tenant_id() AND public.is_tenant_admin())
  WITH CHECK (tenant_id = public.user_tenant_id() AND public.is_tenant_admin());

-- Permissive counterpart so Administrators actually can read and write.
DROP POLICY IF EXISTS "team_invitations_admin_rw" ON public.team_invitations;
CREATE POLICY "team_invitations_admin_rw"
  ON public.team_invitations
  FOR ALL
  TO authenticated
  USING (tenant_id = public.user_tenant_id())
  WITH CHECK (tenant_id = public.user_tenant_id());

-- ──────────────────────────────────────────────────────────────────────────────
-- 5. Administrator-only writes on the account-editing / reporting surfaces
--    (Users get no billing, no reports, no account editing.)
--    RESTRICTIVE so it holds alongside any pre-existing USING (true) policy.
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
    t TEXT;
    has_tenant BOOLEAN;
BEGIN
    FOREACH t IN ARRAY ARRAY[
        'tenant_settings',   -- account editing (absent in the live db; guarded)
        'integrations',      -- QB credentials / account editing
        'qb_connections',    -- QB company connections
        'export_history'     -- reports / exports
    ] LOOP
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.tables
            WHERE table_schema = 'public' AND table_name = t
        ) THEN
            CONTINUE;
        END IF;

        SELECT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema = 'public' AND table_name = t AND column_name = 'tenant_id'
        ) INTO has_tenant;

        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);

        EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_admin_write_only', t);
        EXECUTE format(
            'CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR INSERT WITH CHECK (public.is_tenant_admin())',
            t || '_admin_write_only', t
        );

        EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_admin_update_only', t);
        EXECUTE format(
            'CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR UPDATE USING (public.is_tenant_admin()) WITH CHECK (public.is_tenant_admin())',
            t || '_admin_update_only', t
        );

        EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_admin_delete_only', t);
        EXECUTE format(
            'CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR DELETE USING (public.is_tenant_admin())',
            t || '_admin_delete_only', t
        );

        -- Tenant isolation on every operation, anon included.
        IF has_tenant THEN
            EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_tenant_isolation', t);
            EXECUTE format(
                'CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR ALL '
                || 'USING (tenant_id = public.user_tenant_id()) '
                || 'WITH CHECK (tenant_id = public.user_tenant_id())',
                t || '_tenant_isolation', t
            );
        END IF;
    END LOOP;
END $$;

-- export_history SELECT is a report, so Users may not read it either.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'export_history'
    ) THEN
        DROP POLICY IF EXISTS "export_history_admin_read_only" ON public.export_history;
        CREATE POLICY "export_history_admin_read_only"
          ON public.export_history
          AS RESTRICTIVE
          FOR SELECT
          USING (public.is_tenant_admin());
    END IF;
END $$;

-- ──────────────────────────────────────────────────────────────────────────────
-- 5b. app_settings — close a live secret leak.
--
--  VERIFIED ON THE LIVE DATABASE: a plain anon-key SELECT on public.app_settings
--  returned a row, and that row carries gemini_api_key, qbo_access_token and
--  qbo_refresh_token. Anyone holding the public anon key could read them.
--
--  The only reader anywhere in the codebase is backend/api_server.py, which
--  talks to PostgREST with the SERVICE key and therefore bypasses RLS. Nothing
--  in frontend/ or chrome-extension/ touches the table. So the correct policy
--  is: no client access at all, by any key but the service key.
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'app_settings'
    ) THEN
        ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
        DROP POLICY IF EXISTS "app_settings_no_client_access" ON public.app_settings;
        CREATE POLICY "app_settings_no_client_access"
          ON public.app_settings
          AS RESTRICTIVE
          FOR ALL
          USING (FALSE)
          WITH CHECK (FALSE);
    END IF;
END $$;

-- ──────────────────────────────────────────────────────────────────────────────
-- 5c. audit_logs — reconcile with the live column names.
--
--  001_schema.sql declares (field, old_value, new_value, job_id). The LIVE
--  table has (entity_type, entity_id, old_values, new_values) instead. The
--  application writer (frontend/lib/team-helpers.ts auditLog) targets the LIVE
--  shape; these guards add those columns to any database built from 001 so the
--  same writer works on both.
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'audit_logs'
    ) THEN
        ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS entity_type TEXT;
        ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS entity_id    TEXT;
        ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS old_values   JSONB;
        ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS new_values   JSONB;
        ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS metadata     JSONB DEFAULT '{}'::jsonb;

        -- Audit entries are not a report a User may read, and no client should
        -- ever rewrite one. Reads are Administrator + own tenant; writes are
        -- service-only (every writer in the app uses the service client).
        ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;

        DROP POLICY IF EXISTS "audit_logs_admin_read" ON public.audit_logs;
        CREATE POLICY "audit_logs_admin_read"
          ON public.audit_logs
          AS RESTRICTIVE
          FOR SELECT
          USING (tenant_id = public.user_tenant_id() AND public.is_tenant_admin());

        DROP POLICY IF EXISTS "audit_logs_no_client_write" ON public.audit_logs;
        CREATE POLICY "audit_logs_no_client_write"
          ON public.audit_logs
          AS RESTRICTIVE
          FOR UPDATE
          USING (FALSE)
          WITH CHECK (FALSE);

        DROP POLICY IF EXISTS "audit_logs_no_client_delete" ON public.audit_logs;
        CREATE POLICY "audit_logs_no_client_delete"
          ON public.audit_logs
          AS RESTRICTIVE
          FOR DELETE
          USING (FALSE);
    END IF;
END $$;

-- ──────────────────────────────────────────────────────────────────────────────
-- 6. MFA recovery codes
--    Supabase TOTP has no built-in backup codes. A redeemed code lets the user
--    unenrol their factor and re-enrol (see /api/auth/mfa/recover).
-- ──────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.mfa_recovery_codes (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    code_hash   TEXT NOT NULL,
    used_at     TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS mfa_recovery_codes_user_idx
    ON public.mfa_recovery_codes (user_id) WHERE used_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS mfa_recovery_codes_unique
    ON public.mfa_recovery_codes (user_id, code_hash);

ALTER TABLE public.mfa_recovery_codes ENABLE ROW LEVEL SECURITY;

-- Hashes are never served to the browser. Only the service client reads them.
-- Deliberately NO permissive policy: authenticated and anon both get zero rows.
DROP POLICY IF EXISTS "mfa_recovery_codes_no_client_access" ON public.mfa_recovery_codes;
CREATE POLICY "mfa_recovery_codes_no_client_access"
  ON public.mfa_recovery_codes
  AS RESTRICTIVE
  FOR ALL
  USING (FALSE)
  WITH CHECK (FALSE);

-- ──────────────────────────────────────────────────────────────────────────────
-- 7. Tenant-level MFA policy flag (Administrators are always required;
--    this lets a firm additionally require it of every member)
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'tenants'
    ) THEN
        ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS require_mfa_all_users BOOLEAN NOT NULL DEFAULT FALSE;
    END IF;
END $$;

-- ========================================================================
-- 031_close_app_settings_anon_read.sql
-- ========================================================================
-- ============================================================================
-- 031: Close the anon-key read on public.app_settings
--
-- WHY THIS IS SEPARATE FROM 030
-- 030 also closes this, but 030 is a large roles/RLS/MFA migration. This hole
-- should be closable on its own, immediately, without taking the rest.
--
-- VERIFIED ON THE LIVE DATABASE (2026-10-05):
--   GET /rest/v1/app_settings?select=*   with the PUBLIC anon key
--   -> 200, 1 row, columns:
--      gemini_api_key, qbo_access_token, qbo_refresh_token, qbo_company_id,
--      qbo_token_expires_at, qbo_connected, tenant_id, id, created_at, updated_at
--
-- At the time of verification those three secret columns were all NULL, so
-- nothing was actually exposed yet. This is an open door on an empty safe --
-- which matters, because the safe is wired to fill itself: the live endpoint at
-- backend/api_server.py (save-settings, ~line 2731) writes gemini_api_key into
-- this very row. The first time anyone saves a key through Settings, that key
-- becomes readable by anybody holding the anon key -- and the anon key is
-- shipped in the frontend bundle AND in the Chrome extension's
-- BOOTSTRAP_CONFIG, so "anybody" means any visitor or any extension user.
--
-- 009 intended to enable RLS here, but 009 was never applied to this database
-- (its tenant_id column is absent from `integrations` live), so the table has
-- been open since it was created.
--
-- NO CLIENT NEEDS THIS TABLE. The only reader anywhere in the codebase is
-- backend/api_server.py, which uses the SERVICE key and therefore bypasses RLS.
-- Nothing in frontend/ or chrome-extension/ touches it. So the correct policy
-- is not "scope it per tenant", it is "no client access at all".
-- ============================================================================

DO $$
DECLARE
    pol RECORD;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'app_settings'
    ) THEN
        RAISE NOTICE '031: public.app_settings does not exist, nothing to close';
        RETURN;
    END IF;

    ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;

    -- Drop every policy on the table. Permissive policies OR together, so one
    -- leftover permissive policy would keep the table readable no matter what
    -- is added alongside it. 009 named two; drop whatever is actually there.
    FOR pol IN
        SELECT policyname FROM pg_policies
        WHERE schemaname = 'public' AND tablename = 'app_settings'
    LOOP
        EXECUTE format('DROP POLICY IF EXISTS %I ON public.app_settings', pol.policyname);
    END LOOP;

    -- Deny-all for every client role. RESTRICTIVE so it ANDs with anything
    -- added later rather than being OR'd away, and with no TO clause so it
    -- covers anon and authenticated alike. service_role has BYPASSRLS, so the
    -- backend is unaffected.
    CREATE POLICY "app_settings_no_client_access"
        ON public.app_settings
        AS RESTRICTIVE
        FOR ALL
        USING (false)
        WITH CHECK (false);

    -- Belt and braces: if the policy were ever dropped, there is still no
    -- privilege to use.
    REVOKE ALL ON public.app_settings FROM anon, authenticated;

    RAISE NOTICE '031: public.app_settings closed to all client roles';
END $$;

COMMENT ON TABLE public.app_settings IS
    'Service-role only. Holds provider credentials; no client role may read or '
    'write it (see migration 031). Read exclusively by the Python backend with '
    'the service key.';

-- ========================================================================
-- 032_batches.sql
-- ========================================================================
-- ============================================================================
-- Migration 032: batches — one reconciliation run
--
-- A batch is a company (QB realm) + a bank account + a period + a position in
-- the four-step flow Upload -> Match -> Review -> Approve. It is what the
-- stepper, the Continue Reconciliation card and the History page read their
-- state from. Michael's mock is the spec for what one row must be able to
-- render:
--
--   "ABC Construction LLC · Operating Checking / August 2026
--    / Step 3 of 4 — 24 checks need attention."
--
-- DESIGN NOTE — why there is no `current_step` column
-- ---------------------------------------------------
-- CHECKLIST section 3: "Step state comes from the batch record, not from which
-- page is open. Forward steps stay locked until the prior one is genuinely
-- complete."  A settable integer is exactly what the v17 prototype got wrong:
-- Approve was reachable from Upload because the step was a link, not a fact.
-- So this table stores *facts* (which jobs belong to the batch, which cheques
-- came out of them, which matches are resolved, who approved) and the step is
-- DERIVED from them by public.batch_counts() + the gating rule. The only
-- mutable position marker is `status`, and a trigger refuses to move it to
-- 'complete' while the derived preconditions are unmet — so a crafted request
-- straight at PostgREST, even with the service key (which bypasses RLS but not
-- triggers), cannot jump the flow either.
--
-- Idempotent: safe to re-run, and safe to run on a database where migrations
-- 026-031 were never applied (nothing here depends on their tables).
-- ============================================================================


-- ──────────────────────────────────────────────────────────────────────────────
-- 0. Prerequisites that earlier migrations may not have applied
--    public.user_tenant_id() is declared in 008 and re-declared in 030; 030 has
--    never been applied anywhere, so create it defensively against the live
--    profile table (user_profiles — `profiles` does not exist live).
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
    profile_table TEXT;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'user_tenant_id'
    ) THEN
        SELECT table_name INTO profile_table
        FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name IN ('user_profiles', 'profiles')
        ORDER BY CASE table_name WHEN 'user_profiles' THEN 0 ELSE 1 END
        LIMIT 1;

        IF profile_table IS NULL THEN
            RAISE EXCEPTION '032: no user_profiles/profiles table — cannot build tenant RLS';
        END IF;

        EXECUTE format($f$
            CREATE OR REPLACE FUNCTION public.user_tenant_id()
            RETURNS UUID AS $body$
              SELECT tenant_id FROM public.%I WHERE id = auth.uid()
            $body$ LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = public;
        $f$, profile_table);

        GRANT EXECUTE ON FUNCTION public.user_tenant_id() TO authenticated, anon;
    END IF;
END $$;

-- update_updated_at() comes from 013; create it if this database predates that.
CREATE OR REPLACE FUNCTION public.update_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;


-- ──────────────────────────────────────────────────────────────────────────────
-- 1. The table
-- ──────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.batches (
    id              UUID        PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Every write carries tenant_id. NOT NULL, FK, and the RLS WITH CHECK
    -- below all have to agree before a row lands.
    tenant_id       UUID        NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    created_by      UUID        REFERENCES auth.users(id) ON DELETE SET NULL,

    -- Company: the QuickBooks realm. Not an FK to qb_connections, because
    -- disconnecting a company must not delete its reconciliation history.
    -- company_name is a display snapshot, so History still reads correctly
    -- after a rename or a disconnect.
    realm_id        TEXT        NOT NULL,
    company_name    TEXT,

    -- Account: "Operating Checking". account_id is the QB account id when one
    -- is known; today AccountSwitcher only has names (CHECKLIST 4), so the
    -- name is the part that is always present.
    account_id      TEXT,
    account_name    TEXT,

    -- Period: a closed date range. period_label is the rendered form
    -- ("August 2026"); it is a column rather than a generated one because
    -- to_char() is STABLE, not IMMUTABLE, and so cannot back a stored
    -- generated column.
    period_start    DATE        NOT NULL,
    period_end      DATE        NOT NULL,
    period_label    TEXT,

    -- The only mutable position marker. 'open' is resumable; 'complete' is
    -- gated by the trigger below; 'abandoned' is the user discarding a run.
    status          TEXT        NOT NULL DEFAULT 'open',

    -- Approval provenance, for History's approver column.
    approved_by     UUID        REFERENCES auth.users(id) ON DELETE SET NULL,
    approved_at     TIMESTAMPTZ,

    notes           TEXT,

    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at    TIMESTAMPTZ
);

-- Constraints added separately so a re-run on an existing table still applies
-- them (CREATE TABLE IF NOT EXISTS is a no-op once the table is there).
ALTER TABLE public.batches DROP CONSTRAINT IF EXISTS batches_status_check;
ALTER TABLE public.batches ADD CONSTRAINT batches_status_check
    CHECK (status IN ('open', 'complete', 'abandoned'));

ALTER TABLE public.batches DROP CONSTRAINT IF EXISTS batches_period_order;
ALTER TABLE public.batches ADD CONSTRAINT batches_period_order
    CHECK (period_end >= period_start);

CREATE INDEX IF NOT EXISTS idx_batches_tenant_status
    ON public.batches(tenant_id, status, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_batches_tenant_realm
    ON public.batches(tenant_id, realm_id);
CREATE INDEX IF NOT EXISTS idx_batches_created_by
    ON public.batches(created_by);

-- One open run per company+account+period, so "create or open" is idempotent
-- and the Continue card can never be ambiguous. Completed and abandoned runs
-- are unconstrained, so a period can be reconciled again later.
CREATE UNIQUE INDEX IF NOT EXISTS idx_batches_one_open_per_scope
    ON public.batches(tenant_id, realm_id, COALESCE(account_id, account_name, ''),
                      period_start, period_end)
    WHERE status = 'open';

DROP TRIGGER IF EXISTS batches_updated_at ON public.batches;
CREATE TRIGGER batches_updated_at
    BEFORE UPDATE ON public.batches
    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();


-- ──────────────────────────────────────────────────────────────────────────────
-- 2. The link: jobs -> batch, and the two derived tables that follow from it
--
--    Direction: batch_id lives on check_jobs (many jobs to one batch), not an
--    array of job ids on batches. A reconciliation run takes several PDFs, a
--    PDF belongs to exactly one run, and the write happens when the job is
--    created — one column on the child is the normalised form and keeps the
--    insert a single statement.
--
--    checks.batch_id and matches.batch_id are denormalised copies so the step
--    counts are one indexed scan instead of a three-table join. They are kept
--    correct by the triggers below plus the backend stamp after flatten;
--    checks.job_id is not relied on because the live checks table does not
--    have it (see migration 020, which dropped it from the insert list).
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables
               WHERE table_schema = 'public' AND table_name = 'check_jobs') THEN
        ALTER TABLE public.check_jobs
            ADD COLUMN IF NOT EXISTS batch_id UUID
            REFERENCES public.batches(id) ON DELETE SET NULL;
        CREATE INDEX IF NOT EXISTS idx_check_jobs_batch ON public.check_jobs(batch_id);
    ELSE
        RAISE WARNING '032: check_jobs missing — jobs cannot be attached to batches';
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.tables
               WHERE table_schema = 'public' AND table_name = 'checks') THEN
        ALTER TABLE public.checks
            ADD COLUMN IF NOT EXISTS batch_id UUID
            REFERENCES public.batches(id) ON DELETE SET NULL;
        CREATE INDEX IF NOT EXISTS idx_checks_batch ON public.checks(batch_id);
    ELSE
        RAISE WARNING '032: checks missing — batch cheque counts will be zero';
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.tables
               WHERE table_schema = 'public' AND table_name = 'matches') THEN
        ALTER TABLE public.matches
            ADD COLUMN IF NOT EXISTS batch_id UUID
            REFERENCES public.batches(id) ON DELETE SET NULL;
        CREATE INDEX IF NOT EXISTS idx_matches_batch_status
            ON public.matches(batch_id, status);
    ELSE
        RAISE WARNING '032: matches missing — batch match counts will be zero';
    END IF;
END $$;


-- ──────────────────────────────────────────────────────────────────────────────
-- 3. The facts behind each step
--
--    plpgsql (not SQL) on purpose: a plpgsql body is not resolved against the
--    catalog at CREATE time, so this applies cleanly on a database that is
--    missing `matches` and only fails at call time, with a readable error.
--
--    SECURITY INVOKER: the counts a user reads go through that user's RLS.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.batch_counts(p_batch_id UUID)
RETURNS JSONB AS $$
DECLARE
    result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'jobs_total',      (SELECT count(*) FROM public.check_jobs j
                             WHERE j.batch_id = p_batch_id),
        'jobs_complete',   (SELECT count(*) FROM public.check_jobs j
                             WHERE j.batch_id = p_batch_id AND j.status = 'complete'),
        'jobs_failed',     (SELECT count(*) FROM public.check_jobs j
                             WHERE j.batch_id = p_batch_id AND j.status = 'error'),
        'jobs_running',    (SELECT count(*) FROM public.check_jobs j
                             WHERE j.batch_id = p_batch_id
                               AND j.status IN ('pending','detecting','extracting',
                                                'analyzed','ocr','ocr_running')),
        'checks_total',    (SELECT count(*) FROM public.checks c
                             WHERE c.batch_id = p_batch_id),
        'matches_total',   (SELECT count(*) FROM public.matches m
                             WHERE m.batch_id = p_batch_id),
        -- "needs attention" — the number Michael's card renders.
        'needs_attention', (SELECT count(*) FROM public.matches m
                             WHERE m.batch_id = p_batch_id
                               AND m.status IN ('pending','flagged','discrepancy','unmatched')),
        'matched',         (SELECT count(*) FROM public.matches m
                             WHERE m.batch_id = p_batch_id AND m.status = 'matched'),
        'approved',        (SELECT count(*) FROM public.matches m
                             WHERE m.batch_id = p_batch_id AND m.status = 'approved'),
        'rejected',        (SELECT count(*) FROM public.matches m
                             WHERE m.batch_id = p_batch_id AND m.status = 'rejected')
    ) INTO result;
    RETURN result;
END;
$$ LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = public;

GRANT EXECUTE ON FUNCTION public.batch_counts(UUID) TO authenticated;

-- Counts for a page of batches in one round trip, so the History list is not
-- one RPC per row. Keyed by batch id as text. Bounded at 100 ids.
CREATE OR REPLACE FUNCTION public.batch_counts_many(p_batch_ids UUID[])
RETURNS JSONB AS $$
DECLARE
    result JSONB := '{}'::jsonb;
    bid UUID;
BEGIN
    IF p_batch_ids IS NULL OR array_length(p_batch_ids, 1) IS NULL THEN
        RETURN result;
    END IF;
    IF array_length(p_batch_ids, 1) > 100 THEN
        RAISE EXCEPTION 'batch_counts_many: at most 100 ids per call';
    END IF;
    FOREACH bid IN ARRAY p_batch_ids LOOP
        result := result || jsonb_build_object(bid::text, public.batch_counts(bid));
    END LOOP;
    RETURN result;
END;
$$ LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = public;

GRANT EXECUTE ON FUNCTION public.batch_counts_many(UUID[]) TO authenticated;

-- The step-3 (Review) completion rule, as the database sees it. This is the
-- one piece of the gating rule that must survive a caller with a narrower view
-- of `matches` than of `batches`, so it is SECURITY DEFINER: a user who could
-- see the batch but not its matches would otherwise read needs_attention = 0
-- and look finished.
--
-- Keep in step with deriveBatchSteps() in frontend/lib/batch-state.ts, which is
-- the same rule for the API layer.
CREATE OR REPLACE FUNCTION public.batch_can_complete(p_batch_id UUID)
RETURNS BOOLEAN AS $$
DECLARE
    n_checks  BIGINT;
    n_matches BIGINT;
    n_open    BIGINT;
BEGIN
    SELECT count(*) INTO n_checks  FROM public.checks  c WHERE c.batch_id = p_batch_id;
    SELECT count(*) INTO n_matches FROM public.matches m WHERE m.batch_id = p_batch_id;
    SELECT count(*) INTO n_open    FROM public.matches m
     WHERE m.batch_id = p_batch_id
       AND m.status IN ('pending','flagged','discrepancy','unmatched');

    RETURN n_checks > 0 AND n_matches >= n_checks AND n_open = 0;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public;

GRANT EXECUTE ON FUNCTION public.batch_can_complete(UUID) TO authenticated;


-- ──────────────────────────────────────────────────────────────────────────────
-- 4. The server-side lock on a forward jump
--
--    Completing a batch is the only irreversible step, so it is the one the
--    database refuses outright when the facts do not support it. An API bug, a
--    hand-rolled PostgREST call, or a service-key script all hit this.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.guard_batch_transition()
RETURNS TRIGGER AS $$
DECLARE
    -- OLD is unassigned on INSERT, so it is read exactly once, under TG_OP.
    was_complete BOOLEAN := FALSE;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN
            RAISE EXCEPTION 'batches.tenant_id is immutable'
                USING ERRCODE = 'check_violation';
        END IF;
        was_complete := (OLD.status = 'complete');
        -- A completed run is history: reopening it would un-approve writes
        -- already pushed to QuickBooks.
        IF was_complete AND NEW.status <> 'complete' THEN
            RAISE EXCEPTION 'batch % is complete and cannot be reopened', OLD.id
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;

    IF NEW.status = 'complete' AND NOT was_complete THEN
        IF NOT public.batch_can_complete(NEW.id) THEN
            RAISE EXCEPTION
                'batch % cannot be approved: step 3 (Review) is not complete — every cheque needs a resolved match first'
                , NEW.id
                USING ERRCODE = 'check_violation';
        END IF;
        NEW.approved_by  := COALESCE(NEW.approved_by, auth.uid());
        NEW.approved_at  := COALESCE(NEW.approved_at, NOW());
        NEW.completed_at := COALESCE(NEW.completed_at, NOW());
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER SET search_path = public;

DROP TRIGGER IF EXISTS batches_guard_transition ON public.batches;
CREATE TRIGGER batches_guard_transition
    BEFORE INSERT OR UPDATE ON public.batches
    FOR EACH ROW EXECUTE FUNCTION public.guard_batch_transition();


-- ──────────────────────────────────────────────────────────────────────────────
-- 5. Keeping the denormalised batch_id correct without touching the match
--    engine or migration 020's flatten function
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public' AND table_name = 'matches'
                     AND column_name = 'batch_id') THEN
        RAISE WARNING '032: matches.batch_id absent — skipping batch stamp triggers';
        RETURN;
    END IF;

    CREATE OR REPLACE FUNCTION public.stamp_match_batch()
    RETURNS TRIGGER AS $f$
    BEGIN
        IF NEW.batch_id IS NULL AND NEW.check_id IS NOT NULL THEN
            SELECT c.batch_id INTO NEW.batch_id
            FROM public.checks c WHERE c.id = NEW.check_id;
        END IF;
        RETURN NEW;
    END;
    $f$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

    DROP TRIGGER IF EXISTS matches_stamp_batch ON public.matches;
    CREATE TRIGGER matches_stamp_batch
        BEFORE INSERT OR UPDATE OF check_id ON public.matches
        FOR EACH ROW EXECUTE FUNCTION public.stamp_match_batch();

    -- The reverse order also happens: matching can run before the backend has
    -- stamped the cheques. When a cheque is attached, carry it to its match.
    CREATE OR REPLACE FUNCTION public.backfill_match_batch()
    RETURNS TRIGGER AS $f$
    BEGIN
        UPDATE public.matches SET batch_id = NEW.batch_id WHERE check_id = NEW.id;
        RETURN NULL;
    END;
    $f$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

    DROP TRIGGER IF EXISTS checks_backfill_match_batch ON public.checks;
    CREATE TRIGGER checks_backfill_match_batch
        AFTER UPDATE OF batch_id ON public.checks
        FOR EACH ROW WHEN (NEW.batch_id IS DISTINCT FROM OLD.batch_id)
        EXECUTE FUNCTION public.backfill_match_batch();
END $$;


-- ──────────────────────────────────────────────────────────────────────────────
-- 6. RLS. An anon-key request must return zero rows: user_tenant_id() is NULL
--    without a session, and `tenant_id = NULL` is never true.
--    There is deliberately no DELETE policy — batches are history. The
--    tenants FK cascade still works, because FK actions run as the table owner.
-- ──────────────────────────────────────────────────────────────────────────────
ALTER TABLE public.batches ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Tenant isolation batches select" ON public.batches;
CREATE POLICY "Tenant isolation batches select"
    ON public.batches FOR SELECT
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Tenant isolation batches insert" ON public.batches;
CREATE POLICY "Tenant isolation batches insert"
    ON public.batches FOR INSERT
    WITH CHECK (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Tenant isolation batches update" ON public.batches;
CREATE POLICY "Tenant isolation batches update"
    ON public.batches FOR UPDATE
    USING (tenant_id = public.user_tenant_id())
    WITH CHECK (tenant_id = public.user_tenant_id());

GRANT SELECT, INSERT, UPDATE ON public.batches TO authenticated;


-- ──────────────────────────────────────────────────────────────────────────────
-- 7. Documentation that travels with the schema
-- ──────────────────────────────────────────────────────────────────────────────
COMMENT ON TABLE public.batches IS
    'One reconciliation run: company (realm) + bank account + period + position in Upload/Match/Review/Approve. Step state is DERIVED (see public.batch_counts and frontend/lib/batch-state.ts); there is no settable step column. public.batch_can_complete gates the move to status=complete.';
COMMENT ON COLUMN public.batches.status IS
    'open | complete | abandoned. The move to complete is refused by trigger batches_guard_transition unless public.batch_can_complete() holds.';
COMMENT ON COLUMN public.check_jobs.batch_id IS
    'The reconciliation run this PDF belongs to. Many jobs to one batch.';

-- ========================================================================
-- 033_stripe_billing.sql
-- ========================================================================
-- ============================================================================
-- 033: Stripe billing (CHECKLIST section 7)
--
-- What this adds, and why each piece is in the DATABASE rather than in the
-- application:
--
--   1. tenants.stripe_* / billing_frequency / paid_through / cancellation and
--      payment columns. These are 1:1 with a tenant, so they go on tenants
--      rather than into a subscriptions table nobody would ever join twice.
--      They are exactly the fields frontend/lib/admin/billing-data.ts lists in
--      STRIPE_FIELDS as having no source.
--
--   2. plan_check_allowance is POPULATED, and the mapping lives in ONE SQL
--      function (plan_check_allowance_for). The allowance is per BILLING
--      PERIOD, and current_billing_period() (026) is monthly for everybody —
--      so an annual customer gets a monthly allowance that resets monthly,
--      not one annual pool. Nothing here multiplies by 12 on purpose.
--
--   3. stripe_events with the event id as PRIMARY KEY. Webhook idempotency is
--      therefore a UNIQUE constraint, not an application "have I seen this?"
--      check. begin_stripe_event() returns 'new' | 'retry' | 'duplicate':
--      a Stripe retry of an event we FINISHED is a no-op, while a retry of one
--      that crashed mid-processing is still allowed through. Those two cases
--      are different and collapsing them either double-applies or loses data.
--
--   4. billing_invoices — the real invoice history. The billing page previously
--      stamped closed months "Paid" from an array index. There is now a row
--      per Stripe invoice or there is no invoice history; there is no third
--      option.
--
--   5. billing_refunds — a refund requires a Super Admin and a recorded
--      reason. The reason is a CHECK constraint and the audit entry is written
--      by a TRIGGER, so a caller that forgets to log cannot refund silently.
--      Same shape as comp_grants (029), deliberately.
--
--   6. billing_notices — "renewal reminder roughly 30 days before an annual
--      charge" needs to be send-once. UNIQUE (tenant_id, kind, period_key).
--
-- Deliberately NOT changed: public.tenant_usage_state() (029) and
-- public.usage_ledger (027). The payment-failure grace period is Stripe's own
-- dunning window: while Stripe retries, the subscription is still `active` and
-- 029's gate still allows processing; when Stripe gives up it sends
-- customer.subscription.updated with status past_due, which 029 already turns
-- into processing_allowed = false with block_reason subscription_past_due,
-- while every read path stays open. No new gate logic exists or is needed.
--
-- Idempotent: safe to re-run.
-- ============================================================================

-- ──────────────────────────────────────────────────────────────────────────────
-- 1. Stripe + subscription columns on tenants
-- ──────────────────────────────────────────────────────────────────────────────
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS stripe_customer_id     TEXT;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS stripe_subscription_id TEXT;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS billing_frequency      TEXT;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS payment_status         TEXT;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS payment_grace_until    TIMESTAMPTZ;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS paid_through           TIMESTAMPTZ;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS cancel_at_period_end   BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS cancel_at              TIMESTAMPTZ;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS canceled_at            TIMESTAMPTZ;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS stripe_synced_at       TIMESTAMPTZ;

ALTER TABLE public.tenants DROP CONSTRAINT IF EXISTS tenants_billing_frequency_check;
ALTER TABLE public.tenants ADD CONSTRAINT tenants_billing_frequency_check
    CHECK (billing_frequency IS NULL OR billing_frequency IN ('monthly', 'annual'));

-- Stripe invoice statuses, plus NULL for "never invoiced".
ALTER TABLE public.tenants DROP CONSTRAINT IF EXISTS tenants_payment_status_check;
ALTER TABLE public.tenants ADD CONSTRAINT tenants_payment_status_check
    CHECK (payment_status IS NULL OR payment_status IN
        ('draft', 'open', 'paid', 'uncollectible', 'void', 'failed'));

-- One Stripe customer maps to one tenant. A second tenant claiming the same
-- customer id would mean two firms billed as one.
CREATE UNIQUE INDEX IF NOT EXISTS tenants_stripe_customer_uniq
    ON public.tenants (stripe_customer_id) WHERE stripe_customer_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS tenants_stripe_subscription_uniq
    ON public.tenants (stripe_subscription_id) WHERE stripe_subscription_id IS NOT NULL;

COMMENT ON COLUMN public.tenants.paid_through IS
    'End of the paid period (Stripe current_period_end). Cancellation runs to this date; reactivation is only possible before it.';
COMMENT ON COLUMN public.tenants.payment_grace_until IS
    'Stripe next_payment_attempt after a failed invoice. The in-app warning window; processing is not restricted until Stripe itself moves the subscription to past_due.';

-- ──────────────────────────────────────────────────────────────────────────────
-- 2. The plan allowance mapping — ONE place (CHECKLIST section 7 table)
--
--    Essential 1,200 · Professional 4,500 · Scale 10,000 cheques PER MONTH.
--    Monthly and annual customers get the same monthly number; annual buys a
--    cheaper rate, not a bigger pool.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.plan_check_allowance_for(p_plan TEXT)
RETURNS INTEGER AS $$
    SELECT CASE lower(btrim(COALESCE(p_plan, '')))
        WHEN 'essential'    THEN 1200
        WHEN 'professional' THEN 4500
        WHEN 'scale'        THEN 10000
        ELSE NULL            -- trial, comp, and the legacy plan names
    END
$$ LANGUAGE SQL IMMUTABLE;

GRANT EXECUTE ON FUNCTION public.plan_check_allowance_for(TEXT) TO authenticated, service_role;

COMMENT ON FUNCTION public.plan_check_allowance_for(TEXT) IS
    'Included cheques PER BILLING PERIOD for a plan. The period is monthly for every customer (current_billing_period), so an annual subscriber''s allowance resets monthly. CHECKLIST section 7.';

-- Populate the column 026 added but left NULL, for any row already on a real
-- plan. IS NULL guarded so a re-run never overwrites a hand-set allowance.
UPDATE public.tenants
   SET plan_check_allowance = public.plan_check_allowance_for(plan)
 WHERE plan_check_allowance IS NULL
   AND public.plan_check_allowance_for(plan) IS NOT NULL;

-- ──────────────────────────────────────────────────────────────────────────────
-- 3. stripe_events — webhook idempotency as a constraint
-- ──────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.stripe_events (
    event_id     TEXT PRIMARY KEY,
    type         TEXT NOT NULL,
    tenant_id    UUID REFERENCES public.tenants(id) ON DELETE SET NULL,
    api_version  TEXT,
    livemode     BOOLEAN,
    received_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    processed_at TIMESTAMPTZ,
    attempts     INTEGER NOT NULL DEFAULT 1,
    error        TEXT,
    payload      JSONB NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS idx_stripe_events_type ON public.stripe_events (type, received_at DESC);
CREATE INDEX IF NOT EXISTS idx_stripe_events_unfinished
    ON public.stripe_events (received_at) WHERE processed_at IS NULL;

ALTER TABLE public.stripe_events ENABLE ROW LEVEL SECURITY;
-- No policy for `authenticated` at all: raw Stripe payloads are not tenant
-- data to be browsed, and the webhook runs under the service key.
DROP POLICY IF EXISTS "Service role full access to stripe_events" ON public.stripe_events;
CREATE POLICY "Service role full access to stripe_events"
    ON public.stripe_events FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON public.stripe_events FROM authenticated, anon;

/*
 * Claim an event for processing.
 *
 * Returns 'new'       — first time we have seen this id; process it.
 *         'retry'     — seen before but never finished (we crashed, or Stripe
 *                       retried before we committed); process it again.
 *         'duplicate' — already processed to completion; the caller must do
 *                       NOTHING and answer 200 so Stripe stops retrying.
 *
 * The INSERT ... ON CONFLICT is the whole mechanism. Two concurrent deliveries
 * of the same event cannot both get 'new', because the primary key serialises
 * them.
 */
CREATE OR REPLACE FUNCTION public.begin_stripe_event(
    p_event_id    TEXT,
    p_type        TEXT,
    p_payload     JSONB   DEFAULT '{}'::jsonb,
    p_livemode    BOOLEAN DEFAULT NULL,
    p_api_version TEXT    DEFAULT NULL
)
RETURNS TEXT AS $$
DECLARE
    _inserted BOOLEAN := FALSE;
    _done     TIMESTAMPTZ;
BEGIN
    IF p_event_id IS NULL OR btrim(p_event_id) = '' THEN
        RAISE EXCEPTION 'begin_stripe_event: event_id is required';
    END IF;

    INSERT INTO public.stripe_events (event_id, type, payload, livemode, api_version)
    VALUES (p_event_id, COALESCE(p_type, 'unknown'), COALESCE(p_payload, '{}'::jsonb),
            p_livemode, p_api_version)
    ON CONFLICT (event_id) DO NOTHING;

    _inserted := FOUND;
    IF _inserted THEN
        RETURN 'new';
    END IF;

    SELECT processed_at INTO _done FROM public.stripe_events WHERE event_id = p_event_id;
    IF _done IS NOT NULL THEN
        RETURN 'duplicate';
    END IF;

    UPDATE public.stripe_events
       SET attempts = attempts + 1, error = NULL
     WHERE event_id = p_event_id;
    RETURN 'retry';
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

CREATE OR REPLACE FUNCTION public.finish_stripe_event(
    p_event_id  TEXT,
    p_tenant_id UUID DEFAULT NULL,
    p_error     TEXT DEFAULT NULL
)
RETURNS VOID AS $$
    UPDATE public.stripe_events
       SET processed_at = CASE WHEN p_error IS NULL THEN now() ELSE NULL END,
           error        = p_error,
           tenant_id    = COALESCE(p_tenant_id, tenant_id)
     WHERE event_id = p_event_id;
$$ LANGUAGE SQL SECURITY DEFINER SET search_path = public;

REVOKE ALL ON FUNCTION public.begin_stripe_event(TEXT, TEXT, JSONB, BOOLEAN, TEXT) FROM PUBLIC, authenticated, anon;
REVOKE ALL ON FUNCTION public.finish_stripe_event(TEXT, UUID, TEXT) FROM PUBLIC, authenticated, anon;
GRANT EXECUTE ON FUNCTION public.begin_stripe_event(TEXT, TEXT, JSONB, BOOLEAN, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.finish_stripe_event(TEXT, UUID, TEXT) TO service_role;

COMMENT ON TABLE public.stripe_events IS
    'Every webhook Stripe has delivered, keyed by Stripe event id. The PRIMARY KEY is the idempotency guarantee: a retry of a finished event is absorbed by the constraint, not by an application check.';

-- ──────────────────────────────────────────────────────────────────────────────
-- 4. Subscription state applied from a VERIFIED webhook, never from a redirect
--
--    This is the only function that turns a tenant's access on. It is service
--    role only, so the success page cannot reach it: a redirect URL is
--    attacker-controllable and must not be able to grant paid access.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.apply_stripe_subscription(
    p_tenant_id       UUID,
    p_customer_id     TEXT,
    p_subscription_id TEXT,
    p_plan            TEXT,
    p_frequency       TEXT,
    p_status          TEXT,
    p_paid_through    TIMESTAMPTZ DEFAULT NULL,
    p_cancel_at_period_end BOOLEAN DEFAULT FALSE,
    p_cancel_at       TIMESTAMPTZ DEFAULT NULL,
    p_canceled_at     TIMESTAMPTZ DEFAULT NULL,
    p_started_at      TIMESTAMPTZ DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
    _allowance INTEGER;
    _status    TEXT;
    _t         public.tenants;
BEGIN
    IF p_tenant_id IS NULL THEN
        RAISE EXCEPTION 'apply_stripe_subscription: tenant_id is required';
    END IF;

    -- Unrecognised Stripe statuses must not land in the column and break the
    -- 026 CHECK; they are mapped, and anything unknown is treated as expired
    -- rather than silently granting access.
    _status := CASE lower(COALESCE(p_status, ''))
        WHEN 'active'             THEN 'active'
        WHEN 'trialing'           THEN 'trialing'
        WHEN 'past_due'           THEN 'past_due'
        WHEN 'unpaid'             THEN 'past_due'
        WHEN 'canceled'           THEN 'canceled'
        WHEN 'incomplete'         THEN 'past_due'
        WHEN 'incomplete_expired' THEN 'expired'
        WHEN 'paused'             THEN 'expired'
        ELSE 'expired'
    END;

    _allowance := public.plan_check_allowance_for(p_plan);

    UPDATE public.tenants
       SET stripe_customer_id     = COALESCE(p_customer_id, stripe_customer_id),
           stripe_subscription_id = COALESCE(p_subscription_id, stripe_subscription_id),
           plan                   = COALESCE(lower(btrim(p_plan)), plan),
           plan_check_allowance   = COALESCE(_allowance, plan_check_allowance),
           billing_frequency      = COALESCE(p_frequency, billing_frequency),
           subscription_status    = _status,
           -- The anchor day for current_billing_period(). Set once, on the
           -- first activation, so the renewal date does not move when the
           -- plan changes mid-month.
           subscription_started_at = COALESCE(subscription_started_at, p_started_at, now()),
           paid_through           = COALESCE(p_paid_through, paid_through),
           cancel_at_period_end   = COALESCE(p_cancel_at_period_end, FALSE),
           cancel_at              = p_cancel_at,
           canceled_at            = COALESCE(p_canceled_at, canceled_at),
           stripe_synced_at       = now()
     WHERE id = p_tenant_id
     RETURNING * INTO _t;

    IF _t.id IS NULL THEN
        RAISE EXCEPTION 'apply_stripe_subscription: unknown tenant %', p_tenant_id;
    END IF;

    RETURN jsonb_build_object(
        'tenant_id', _t.id,
        'plan', _t.plan,
        'plan_check_allowance', _t.plan_check_allowance,
        'billing_frequency', _t.billing_frequency,
        'subscription_status', _t.subscription_status,
        'paid_through', _t.paid_through
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

REVOKE ALL ON FUNCTION public.apply_stripe_subscription(
    UUID, TEXT, TEXT, TEXT, TEXT, TEXT, TIMESTAMPTZ, BOOLEAN, TIMESTAMPTZ, TIMESTAMPTZ, TIMESTAMPTZ
) FROM PUBLIC, authenticated, anon;
GRANT EXECUTE ON FUNCTION public.apply_stripe_subscription(
    UUID, TEXT, TEXT, TEXT, TEXT, TEXT, TIMESTAMPTZ, BOOLEAN, TIMESTAMPTZ, TIMESTAMPTZ, TIMESTAMPTZ
) TO service_role;

COMMENT ON FUNCTION public.apply_stripe_subscription(
    UUID, TEXT, TEXT, TEXT, TEXT, TEXT, TIMESTAMPTZ, BOOLEAN, TIMESTAMPTZ, TIMESTAMPTZ, TIMESTAMPTZ
) IS
    'The ONLY path that grants paid access. Service role only, called from the signature-verified webhook handler. Never callable by a browser, because a success-page redirect is attacker-controllable.';

-- ──────────────────────────────────────────────────────────────────────────────
-- 5. billing_invoices — real invoice history or none
-- ──────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.billing_invoices (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES public.tenants(id) ON DELETE RESTRICT,
    stripe_invoice_id   TEXT NOT NULL UNIQUE,
    stripe_customer_id  TEXT,
    stripe_subscription_id TEXT,
    number              TEXT,
    -- Stripe's invoice status verbatim. The UI never invents one.
    status              TEXT NOT NULL,
    currency            TEXT NOT NULL DEFAULT 'usd',
    amount_due          BIGINT NOT NULL DEFAULT 0,   -- minor units, as Stripe sends
    amount_paid         BIGINT NOT NULL DEFAULT 0,
    amount_remaining    BIGINT NOT NULL DEFAULT 0,
    subtotal            BIGINT,
    total               BIGINT,
    period_start        TIMESTAMPTZ,
    period_end          TIMESTAMPTZ,
    due_date            TIMESTAMPTZ,
    paid_at             TIMESTAMPTZ,
    attempt_count       INTEGER,
    next_payment_attempt TIMESTAMPTZ,
    hosted_invoice_url  TEXT,
    invoice_pdf         TEXT,
    -- Overage lines are metered usage; kept so the page can show what the
    -- charge was for without a second Stripe call.
    line_summary        JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_billing_invoices_tenant
    ON public.billing_invoices (tenant_id, period_start DESC);

ALTER TABLE public.billing_invoices ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own tenant invoices" ON public.billing_invoices;
CREATE POLICY "Users can view own tenant invoices"
    ON public.billing_invoices FOR SELECT TO authenticated
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Service role full access to billing_invoices" ON public.billing_invoices;
CREATE POLICY "Service role full access to billing_invoices"
    ON public.billing_invoices FOR ALL TO service_role USING (true) WITH CHECK (true);

REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.billing_invoices FROM authenticated, anon;
GRANT SELECT ON public.billing_invoices TO authenticated;

COMMENT ON TABLE public.billing_invoices IS
    'Invoice history, written only by the verified Stripe webhook. One row per Stripe invoice; status is Stripe''s own. The billing page shows these rows or shows no history — it never derives a "paid" month from a date.';

-- ──────────────────────────────────────────────────────────────────────────────
-- 6. billing_refunds — Super Admin only, reason mandatory, logged by trigger
-- ──────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.billing_refunds (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id          UUID NOT NULL REFERENCES public.tenants(id) ON DELETE RESTRICT,

    -- Super Admin is an email allowlist (frontend/lib/super-admin.ts), not a
    -- database role, so the email is stored alongside the id — same reasoning
    -- as comp_grants.granted_by_email.
    refunded_by        UUID REFERENCES auth.users(id) ON DELETE SET NULL,
    refunded_by_email  TEXT NOT NULL,

    reason             TEXT NOT NULL CHECK (length(btrim(reason)) >= 3),

    stripe_refund_id   TEXT UNIQUE,
    stripe_invoice_id  TEXT,
    stripe_charge_id   TEXT,
    stripe_payment_intent_id TEXT,
    amount             BIGINT NOT NULL CHECK (amount > 0),  -- minor units
    currency           TEXT NOT NULL DEFAULT 'usd',
    status             TEXT,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_billing_refunds_tenant
    ON public.billing_refunds (tenant_id, created_at DESC);

ALTER TABLE public.billing_refunds ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own tenant refunds" ON public.billing_refunds;
CREATE POLICY "Users can view own tenant refunds"
    ON public.billing_refunds FOR SELECT TO authenticated
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Service role full access to billing_refunds" ON public.billing_refunds;
CREATE POLICY "Service role full access to billing_refunds"
    ON public.billing_refunds FOR ALL TO service_role USING (true) WITH CHECK (true);

REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.billing_refunds FROM authenticated, anon;
GRANT SELECT ON public.billing_refunds TO authenticated;

CREATE OR REPLACE FUNCTION public.log_billing_refund()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO public.audit_logs (tenant_id, user_id, action, old_value, new_value, metadata)
    VALUES (
        NEW.tenant_id,
        NEW.refunded_by,
        'billing.refunded',
        NULL,
        to_jsonb(NEW)::text,
        jsonb_build_object(
            'refund_id',         NEW.id,
            'stripe_refund_id',  NEW.stripe_refund_id,
            'stripe_invoice_id', NEW.stripe_invoice_id,
            'amount',            NEW.amount,
            'currency',          NEW.currency,
            'reason',            NEW.reason,
            'refunded_by_email', NEW.refunded_by_email
        )
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

DROP TRIGGER IF EXISTS trg_billing_refunds_audit ON public.billing_refunds;
CREATE TRIGGER trg_billing_refunds_audit
    AFTER INSERT ON public.billing_refunds
    FOR EACH ROW EXECUTE FUNCTION public.log_billing_refund();

COMMENT ON TABLE public.billing_refunds IS
    'Refunds issued by a Super Admin. The reason is a CHECK constraint and the audit entry is written by trigger, so a refund cannot be issued without both.';

-- ──────────────────────────────────────────────────────────────────────────────
-- 7. billing_notices — send-once reminders (annual renewal, ~30 days out)
-- ──────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.billing_notices (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    kind        TEXT NOT NULL,
    -- What the notice is ABOUT, e.g. the renewal date '2027-03-01'. Makes the
    -- unique constraint below mean "once per renewal", not "once ever".
    period_key  TEXT NOT NULL,
    sent_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    channel     TEXT NOT NULL DEFAULT 'in_app',
    metadata    JSONB NOT NULL DEFAULT '{}'::jsonb,
    CONSTRAINT billing_notices_once UNIQUE (tenant_id, kind, period_key)
);

CREATE INDEX IF NOT EXISTS idx_billing_notices_tenant
    ON public.billing_notices (tenant_id, sent_at DESC);

ALTER TABLE public.billing_notices ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own tenant billing_notices" ON public.billing_notices;
CREATE POLICY "Users can view own tenant billing_notices"
    ON public.billing_notices FOR SELECT TO authenticated
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Service role full access to billing_notices" ON public.billing_notices;
CREATE POLICY "Service role full access to billing_notices"
    ON public.billing_notices FOR ALL TO service_role USING (true) WITH CHECK (true);

REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.billing_notices FROM authenticated, anon;
GRANT SELECT ON public.billing_notices TO authenticated;

COMMENT ON TABLE public.billing_notices IS
    'One row per notice actually sent. UNIQUE (tenant_id, kind, period_key) makes the renewal reminder send-once per renewal, so a cron that runs hourly does not email daily.';

-- ========================================================================
-- 034_email_and_qb_health.sql
-- ========================================================================
-- ============================================================================
-- 034: Email delivery, unsubscribe preferences, and QuickBooks connection
--      health (CHECKLIST section 9, docs/EMAIL-SPEC-REVIEW.md sections 2 and 5)
--
-- What this adds, and why each piece is in the DATABASE rather than in the
-- application:
--
--   1. qb_connections.status / status_detail / status_checked_at /
--      status_changed_at. `is_active` means "the company currently selected",
--      NOT "the connection works" — the unique partial index in migration 013
--      allows exactly one active row per tenant, so is_active can never carry
--      health. Both token-refresh paths previously wrote a console line and
--      returned, so a dead connection was invisible until a user tripped over
--      it. These columns are where a refresh failure now lands, and they are
--      the trigger for emails 11/12/13.
--
--   2. email_log — one row per send ATTEMPT, including attempts that never
--      left the process because RESEND_API_KEY is unset. A missing email has
--      to be diagnosable later, and "we never tried" and "the provider
--      rejected it" are different answers.
--
--   3. email_preferences — the unsubscribe store the published privacy policy
--      already promises. One row per (tenant, email) with an opaque token, so
--      the unsubscribe link carries no address in its query string and can be
--      revoked by rotating one row. `unsubscribed_at IS NULL` means subscribed.
--
--   4. NO new send-once table. Send-once already exists as a database
--      constraint: billing_notices' UNIQUE (tenant_id, kind, period_key) from
--      migration 033. This migration only widens its COMMENT, because the
--      mailer now claims a row there before every non-repeatable email. Adding
--      a second mechanism would mean two things to keep in step.
--
-- Idempotent, and guarded rather than assuming earlier migrations ran:
-- migrations 026-033 have never been applied to any database, so every block
-- below checks for what it depends on instead of failing the whole file.
-- ============================================================================

-- ──────────────────────────────────────────────────────────────────────────────
-- 1. qb_connections health
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
BEGIN
    IF to_regclass('public.qb_connections') IS NULL THEN
        RAISE NOTICE '034: public.qb_connections absent, skipping health columns';
        RETURN;
    END IF;

    ALTER TABLE public.qb_connections
        ADD COLUMN IF NOT EXISTS status            TEXT        NOT NULL DEFAULT 'connected',
        ADD COLUMN IF NOT EXISTS status_detail     TEXT,
        ADD COLUMN IF NOT EXISTS status_checked_at TIMESTAMPTZ,
        ADD COLUMN IF NOT EXISTS status_changed_at TIMESTAMPTZ;

    -- 'connected'       working as far as we know
    -- 'needs_reconnect' the refresh token is dead; only the user can fix it
    -- 'error'           a transient failure (network, Intuit 5xx, rate limit)
    -- 'revoked'         Intuit says the grant is gone
    -- 'unknown'         we could not find out. The health check records this
    --                   when credentials are absent or Intuit is unreachable,
    --                   because a connection wrongly marked dead emails a firm
    --                   a reconnect notice for no reason. Only 'needs_reconnect'
    --                   and 'revoked' ever send that email.
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'public.qb_connections'::regclass
           AND conname  = 'qb_connections_status_check'
    ) THEN
        ALTER TABLE public.qb_connections
            ADD CONSTRAINT qb_connections_status_check
            CHECK (status IN ('connected', 'needs_reconnect', 'error', 'revoked', 'unknown'));
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_qb_connections_status
    ON public.qb_connections (status, status_changed_at DESC);

DO $$
BEGIN
    IF to_regclass('public.qb_connections') IS NOT NULL THEN
        COMMENT ON COLUMN public.qb_connections.status IS
            'Connection HEALTH: connected | needs_reconnect | error | revoked | unknown. Distinct from is_active, which means "the company currently selected". Written by both token-refresh paths (lib/qb-health.ts) and by the scheduled health check.';
    END IF;
END $$;

-- ──────────────────────────────────────────────────────────────────────────────
-- 2. email_log — every send attempt, including the ones we never made
-- ──────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.email_log (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    -- Nullable: a send can precede tenant resolution (an invite to an address
    -- that has no account yet still belongs to the inviting firm, but a
    -- provider bounce handler may not know one).
    tenant_id     UUID REFERENCES public.tenants(id) ON DELETE SET NULL,
    to_email      TEXT NOT NULL,
    template      TEXT NOT NULL,
    subject       TEXT NOT NULL,
    -- sent                   the provider accepted it
    -- failed                 we tried and the provider or network said no
    -- skipped_unconfigured   no RESEND_API_KEY; nothing left the process
    -- suppressed             recipient has unsubscribed from this category
    -- already_sent           send-once claim was already held
    status        TEXT NOT NULL,
    category      TEXT NOT NULL DEFAULT 'transactional',
    provider_id   TEXT,
    error         TEXT,
    metadata      JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT email_log_status_check
        CHECK (status IN ('sent', 'failed', 'skipped_unconfigured', 'suppressed', 'already_sent')),
    CONSTRAINT email_log_category_check
        CHECK (category IN ('transactional', 'notification'))
);

CREATE INDEX IF NOT EXISTS idx_email_log_tenant   ON public.email_log (tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_email_log_to       ON public.email_log (to_email, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_email_log_template ON public.email_log (template, status, created_at DESC);

ALTER TABLE public.email_log ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own tenant email_log" ON public.email_log;
CREATE POLICY "Users can view own tenant email_log"
    ON public.email_log FOR SELECT TO authenticated
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Service role full access to email_log" ON public.email_log;
CREATE POLICY "Service role full access to email_log"
    ON public.email_log FOR ALL TO service_role USING (true) WITH CHECK (true);

REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.email_log FROM authenticated, anon;
GRANT SELECT ON public.email_log TO authenticated;

COMMENT ON TABLE public.email_log IS
    'One row per send ATTEMPT. status=skipped_unconfigured means RESEND_API_KEY was unset and nothing was sent — the transport never pretends. A missing email is diagnosed from here.';

-- ──────────────────────────────────────────────────────────────────────────────
-- 3. email_preferences — the unsubscribe store
-- ──────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.email_preferences (
    tenant_id       UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    -- Stored lower-cased by the application (lib/team-helpers.normaliseEmail).
    email           TEXT NOT NULL,
    -- Opaque, revocable, and NOT derived from the address, so the unsubscribe
    -- URL carries no personal data and rotating the row kills old links.
    token           TEXT NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(32), 'hex'),
    -- NULL = subscribed. One switch: there is one non-transactional category
    -- today (usage and trial notices) and a second column nobody reads is a
    -- second thing to keep in step.
    unsubscribed_at TIMESTAMPTZ,
    source          TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, email)
);

CREATE INDEX IF NOT EXISTS idx_email_preferences_email ON public.email_preferences (email);

ALTER TABLE public.email_preferences ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own tenant email_preferences" ON public.email_preferences;
CREATE POLICY "Users can view own tenant email_preferences"
    ON public.email_preferences FOR SELECT TO authenticated
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Service role full access to email_preferences" ON public.email_preferences;
CREATE POLICY "Service role full access to email_preferences"
    ON public.email_preferences FOR ALL TO service_role USING (true) WITH CHECK (true);

-- The unsubscribe route is unauthenticated by necessity (the recipient clicks
-- a link in a mail client), so it runs under the service role and the token is
-- the authorisation. `anon` gets nothing: a token must not be enumerable.
REVOKE ALL ON public.email_preferences FROM anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.email_preferences FROM authenticated;
GRANT SELECT ON public.email_preferences TO authenticated;

COMMENT ON TABLE public.email_preferences IS
    'Unsubscribe store for non-transactional email. unsubscribed_at IS NULL means subscribed. The token is random, not derived from the address, so the unsubscribe URL leaks nothing and can be revoked.';

-- ──────────────────────────────────────────────────────────────────────────────
-- 4. billing_notices is now the app-wide send-once ledger (no new table)
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
BEGIN
    IF to_regclass('public.billing_notices') IS NULL THEN
        RAISE NOTICE '034: public.billing_notices absent (apply 033 first) — the mailer will report send_once_unavailable at runtime';
        RETURN;
    END IF;

    COMMENT ON TABLE public.billing_notices IS
        'One row per notice actually sent, for ANY send-once email and not only billing ones (migration 034 widened this). UNIQUE (tenant_id, kind, period_key) is the send-once guarantee: lib/email/send.ts claims a row BEFORE sending, so a retried cron is a no-op by constraint rather than by an application "have I sent this?" check.';
END $$;

-- ========================================================================
-- 035_history_reports_and_retention.sql
-- ========================================================================
-- ============================================================================
-- Migration 035: History, Reports and upload retention (CHECKLIST section 13)
--
-- Three things live here:
--
--   1. public.upload_retention — the durable record of which uploaded source
--      PDF is to be deleted and WHEN. 14 days, counted from the moment the
--      reconciliation COMPLETED, not from upload: a firm that pauses mid-month
--      would otherwise lose files it still needs. Michael asked 7 or 14; 14 is
--      the agreed default.
--
--      The row is written by a trigger when a batch moves to 'complete', so the
--      promise cannot be forgotten by an API path that skipped a helper. Only
--      the source PDF is ever in scope — the extracted cheque data, the check
--      images, the OCR JSON and the batch itself are not recorded here and are
--      never touched by the sweep.
--
--   2. public.report_summary() — ONE read-only aggregator behind the Reports
--      page. It adds no new storage: every figure is counted out of batches,
--      checks, matches, usage_ledger (027) and export_history (001). It reports
--      which of those tables it actually found, so a figure is never silently
--      zero because a migration was not applied.
--
--   3. Nothing for History — History reads GET /api/batches, which already
--      exists (migration 032). There is deliberately no second list.
--
-- Idempotent: safe to re-run. Safe to apply on a database where migrations
-- 026-034 were never applied: every reference to a table those added is behind
-- a to_regclass() guard, and a plpgsql branch that is not taken is never
-- planned, so a missing table costs a NULL figure rather than an error.
-- ============================================================================


-- ──────────────────────────────────────────────────────────────────────────────
-- 0. Prerequisites earlier migrations may not have applied.
-- ──────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
    profile_table TEXT;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'user_tenant_id'
    ) THEN
        SELECT table_name INTO profile_table
        FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name IN ('user_profiles', 'profiles')
        ORDER BY CASE table_name WHEN 'user_profiles' THEN 0 ELSE 1 END
        LIMIT 1;

        IF profile_table IS NULL THEN
            RAISE EXCEPTION '035: no user_profiles/profiles table — cannot build tenant RLS';
        END IF;

        EXECUTE format($f$
            CREATE OR REPLACE FUNCTION public.user_tenant_id()
            RETURNS UUID AS $body$
              SELECT tenant_id FROM public.%I WHERE id = auth.uid()
            $body$ LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = public;
        $f$, profile_table);

        GRANT EXECUTE ON FUNCTION public.user_tenant_id() TO authenticated, anon;
    END IF;
END $$;

CREATE OR REPLACE FUNCTION public.update_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;


-- ============================================================================
-- PART 1 — UPLOAD RETENTION
-- ============================================================================

-- The retention window, in ONE place. A function rather than a constant in the
-- application so the sweep, the trigger and anyone reading the schema all see
-- the same 14. frontend/lib/retention.ts carries the same number and
-- scripts/check-history-reports.ts asserts the two agree.
CREATE OR REPLACE FUNCTION public.upload_retention_days()
RETURNS INTEGER AS $$ SELECT 14 $$ LANGUAGE SQL IMMUTABLE;

GRANT EXECUTE ON FUNCTION public.upload_retention_days() TO authenticated;


-- One row per uploaded source PDF that is due for deletion.
--
-- `storage_prefix` is the job folder, and the sweep deletes only objects
-- DIRECTLY inside it whose name ends in .pdf. That is why the extracted data
-- survives: images/, pages/ and ocr_results/ are sub-folders, not direct
-- children, and extraction_summary.json is not a .pdf. Nothing in this table
-- references a checks, matches or batches row for deletion.
CREATE TABLE IF NOT EXISTS public.upload_retention (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    tenant_id       UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,

    -- What the file belongs to. Both nullable-safe on delete: losing the batch
    -- must not lose the obligation to delete the file.
    batch_id        UUID,
    job_id          TEXT NOT NULL,

    -- Where the file is. Bucket + folder are what the sweep lists; the exact
    -- object path is kept for the audit trail, and is not trusted as the only
    -- way to find the file (upload-time filename mangling has happened).
    storage_bucket  TEXT NOT NULL DEFAULT 'checks',
    storage_prefix  TEXT NOT NULL,
    storage_path    TEXT,
    pdf_url         TEXT,

    -- When. delete_after = reconciliation completion + upload_retention_days().
    completed_at    TIMESTAMPTZ NOT NULL,
    delete_after    TIMESTAMPTZ NOT NULL,

    status          TEXT NOT NULL DEFAULT 'pending',
    attempts        INTEGER NOT NULL DEFAULT 0,
    objects_deleted INTEGER NOT NULL DEFAULT 0,
    last_error      TEXT,
    deleted_at      TIMESTAMPTZ,

    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.upload_retention DROP CONSTRAINT IF EXISTS upload_retention_status_check;
ALTER TABLE public.upload_retention ADD CONSTRAINT upload_retention_status_check
    -- 'deleted'  the file was removed.
    -- 'missing'  the file was already gone. That is a SUCCESS, not a failure:
    --            a sweep that ran twice, or an operator who tidied the bucket,
    --            must not leave a row retrying forever.
    -- 'failed'   storage refused. Retried on the next sweep.
    CHECK (status IN ('pending', 'deleted', 'missing', 'failed'));

-- THE idempotency guarantee for scheduling: one obligation per file, ever.
-- Completing a batch twice, re-running this migration's backfill, or two
-- requests racing the trigger all collide here instead of queuing duplicates.
CREATE UNIQUE INDEX IF NOT EXISTS upload_retention_object_uniq
    ON public.upload_retention (tenant_id, storage_bucket, storage_prefix, job_id);

-- The sweep's one query: pending rows whose time has come, oldest first.
CREATE INDEX IF NOT EXISTS idx_upload_retention_due
    ON public.upload_retention (delete_after)
    WHERE status IN ('pending', 'failed');
CREATE INDEX IF NOT EXISTS idx_upload_retention_tenant
    ON public.upload_retention (tenant_id, delete_after DESC);
CREATE INDEX IF NOT EXISTS idx_upload_retention_batch
    ON public.upload_retention (batch_id);

DROP TRIGGER IF EXISTS upload_retention_updated_at ON public.upload_retention;
CREATE TRIGGER upload_retention_updated_at
    BEFORE UPDATE ON public.upload_retention
    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();


-- ──────────────────────────────────────────────────────────────────────────────
-- Scheduling: record every source PDF of a completed batch.
--
-- SECURITY DEFINER because it is called from a trigger on batches, which a
-- tenant user owns, while upload_retention is service-managed.
--
-- ON CONFLICT DO NOTHING, so calling it again for the same batch is a no-op
-- rather than an error or a second obligation. Returns the number of NEW rows.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.schedule_upload_retention(p_batch_id UUID)
RETURNS INTEGER AS $$
DECLARE
    _n INTEGER := 0;
BEGIN
    IF p_batch_id IS NULL THEN RETURN 0; END IF;
    IF to_regclass('public.batches') IS NULL
       OR to_regclass('public.check_jobs') IS NULL THEN
        RETURN 0;
    END IF;

    WITH src AS (
        SELECT
            b.tenant_id,
            b.id                                   AS batch_id,
            j.job_id,
            COALESCE(NULLIF(split_part(split_part(j.pdf_url, '/object/public/', 2), '/', 1), ''),
                     'checks')                     AS bucket,
            'jobs/' || j.job_id                    AS prefix,
            NULLIF(regexp_replace(split_part(j.pdf_url, '/object/public/', 2),
                                  '^[^/]+/', ''), '') AS object_path,
            j.pdf_url,
            COALESCE(b.completed_at, NOW())        AS completed_at
        FROM public.batches b
        JOIN public.check_jobs j ON j.batch_id = b.id
        WHERE b.id = p_batch_id
          AND j.pdf_url IS NOT NULL
    )
    INSERT INTO public.upload_retention (
        tenant_id, batch_id, job_id, storage_bucket, storage_prefix,
        storage_path, pdf_url, completed_at, delete_after
    )
    SELECT
        s.tenant_id, s.batch_id, s.job_id, s.bucket, s.prefix,
        s.object_path, s.pdf_url, s.completed_at,
        s.completed_at + (public.upload_retention_days() || ' days')::interval
    FROM src s
    ON CONFLICT (tenant_id, storage_bucket, storage_prefix, job_id) DO NOTHING;

    GET DIAGNOSTICS _n = ROW_COUNT;
    RETURN _n;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;


-- The trigger. Fires once, on the transition INTO 'complete'.
CREATE OR REPLACE FUNCTION public.batches_schedule_retention()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.status = 'complete'
       AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'complete') THEN
        PERFORM public.schedule_upload_retention(NEW.id);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

DO $$
BEGIN
    IF to_regclass('public.batches') IS NOT NULL THEN
        DROP TRIGGER IF EXISTS batches_schedule_retention ON public.batches;
        CREATE TRIGGER batches_schedule_retention
            AFTER INSERT OR UPDATE OF status ON public.batches
            FOR EACH ROW EXECUTE FUNCTION public.batches_schedule_retention();
    ELSE
        RAISE WARNING '035: batches missing (migration 032 not applied) — retention will not be scheduled until it is';
    END IF;
END $$;

-- Backfill: batches that completed before this migration existed still owe the
-- firm a deletion. Same ON CONFLICT, so re-running costs nothing.
DO $$
DECLARE
    b RECORD;
BEGIN
    IF to_regclass('public.batches') IS NOT NULL
       AND to_regclass('public.check_jobs') IS NOT NULL THEN
        FOR b IN SELECT id FROM public.batches WHERE status = 'complete' LOOP
            PERFORM public.schedule_upload_retention(b.id);
        END LOOP;
    END IF;
END $$;


-- ──────────────────────────────────────────────────────────────────────────────
-- The sweep's two RPCs. Both service-role only: deleting a customer's file is
-- not a tenant-user action.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.upload_retention_due(p_limit INTEGER DEFAULT 100)
RETURNS TABLE (
    id             UUID,
    tenant_id      UUID,
    batch_id       UUID,
    job_id         TEXT,
    storage_bucket TEXT,
    storage_prefix TEXT,
    storage_path   TEXT,
    delete_after   TIMESTAMPTZ,
    attempts       INTEGER
) AS $$
    SELECT r.id, r.tenant_id, r.batch_id, r.job_id, r.storage_bucket,
           r.storage_prefix, r.storage_path, r.delete_after, r.attempts
      FROM public.upload_retention r
     -- 'deleted' and 'missing' are terminal, so a second sweep over the same
     -- window returns nothing to do. This predicate IS the sweep's idempotency.
     WHERE r.status IN ('pending', 'failed')
       AND r.delete_after <= NOW()
     ORDER BY r.delete_after ASC
     LIMIT LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
$$ LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = public;

REVOKE ALL ON FUNCTION public.upload_retention_due(INTEGER) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.upload_retention_due(INTEGER) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.upload_retention_due(INTEGER) TO service_role;


-- Record the outcome of one deletion.
--
-- Idempotent twice over: a row already in a terminal state is returned
-- unchanged (no error, no second audit row), and 'missing' — the file was
-- already gone — is recorded as a success.
--
-- The source PDF's URL is cleared off check_jobs so the UI stops offering a
-- link to a file that no longer exists. Nothing else on check_jobs is touched:
-- pdf_name, total_checks, checks_data and every checks/matches/batches row stay
-- exactly as they were, which is the whole point of "keep the extracted data
-- and the history".
CREATE OR REPLACE FUNCTION public.complete_upload_retention(
    p_id              UUID,
    p_outcome         TEXT,
    p_objects_deleted INTEGER DEFAULT 0,
    p_error           TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
    _row public.upload_retention;
BEGIN
    IF p_outcome NOT IN ('deleted', 'missing', 'failed') THEN
        RAISE EXCEPTION 'complete_upload_retention: outcome must be deleted, missing or failed';
    END IF;

    SELECT * INTO _row FROM public.upload_retention WHERE id = p_id;
    IF _row.id IS NULL THEN
        RETURN jsonb_build_object('ok', FALSE, 'reason', 'not_found');
    END IF;
    IF _row.status IN ('deleted', 'missing') THEN
        -- Already settled. A repeated sweep is a no-op, not an error.
        RETURN jsonb_build_object('ok', TRUE, 'already_settled', TRUE, 'status', _row.status);
    END IF;

    UPDATE public.upload_retention
       SET status          = p_outcome,
           attempts        = attempts + 1,
           objects_deleted = COALESCE(p_objects_deleted, 0),
           last_error      = CASE WHEN p_outcome = 'failed' THEN p_error ELSE NULL END,
           deleted_at      = CASE WHEN p_outcome IN ('deleted', 'missing') THEN NOW() ELSE NULL END
     WHERE id = p_id;

    IF p_outcome IN ('deleted', 'missing')
       AND to_regclass('public.check_jobs') IS NOT NULL THEN
        UPDATE public.check_jobs
           SET pdf_url = NULL
         WHERE job_id = _row.job_id
           AND pdf_url IS NOT NULL;
    END IF;

    RETURN jsonb_build_object('ok', TRUE, 'already_settled', FALSE, 'status', p_outcome);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

REVOKE ALL ON FUNCTION public.complete_upload_retention(UUID, TEXT, INTEGER, TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.complete_upload_retention(UUID, TEXT, INTEGER, TEXT)
    FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.complete_upload_retention(UUID, TEXT, INTEGER, TEXT)
    TO service_role;


-- RLS. A firm may READ its own retention schedule — "your files go on the 14th"
-- is information the firm is owed. Nobody but the service role may write it.
ALTER TABLE public.upload_retention ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Tenant reads own upload_retention" ON public.upload_retention;
CREATE POLICY "Tenant reads own upload_retention"
    ON public.upload_retention FOR SELECT
    TO authenticated
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Service role full access to upload_retention" ON public.upload_retention;
CREATE POLICY "Service role full access to upload_retention"
    ON public.upload_retention FOR ALL
    TO service_role
    USING (TRUE) WITH CHECK (TRUE);

GRANT SELECT ON public.upload_retention TO authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.upload_retention FROM authenticated;
REVOKE ALL ON public.upload_retention FROM anon;


-- ============================================================================
-- PART 2 — REPORTS
--
-- One read-only aggregator. No new tables, no materialised rollup: the numbers
-- are counted out of the rows that already exist, so a report can never drift
-- from the data it describes.
--
-- Date semantics, stated once because a report that is vague about its window
-- is worse than no report:
--
--   * batches are included when their PERIOD OVERLAPS [p_from, p_to] —
--     period_start <= p_to AND period_end >= p_from. That is what an
--     accountant means by "August", not "the row was touched in August".
--   * usage_ledger rows are included by occurred_at, the moment the cheque was
--     processed.
--   * export_history rows are included by created_at, and are NOT narrowed by
--     the company or account filter: export_history has no batch link today, so
--     narrowing it would silently drop every export. `exports.scope` says so.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.report_summary(
    p_tenant_id UUID,
    p_from      DATE,
    p_to        DATE,
    p_realm_id  TEXT DEFAULT NULL,
    p_account   TEXT DEFAULT NULL,
    p_batch_id  UUID DEFAULT NULL,
    p_row_limit INTEGER DEFAULT 50
)
RETURNS JSONB AS $$
DECLARE
    _claims     TEXT := current_setting('request.jwt.claims', TRUE);
    _is_service BOOLEAN;
    _ids        UUID[] := '{}'::uuid[];
    _limit      INTEGER := LEAST(GREATEST(COALESCE(p_row_limit, 50), 1), 200);

    _has_batches BOOLEAN := to_regclass('public.batches')       IS NOT NULL;
    _has_checks  BOOLEAN := to_regclass('public.checks')         IS NOT NULL;
    _has_matches BOOLEAN := to_regclass('public.matches')        IS NOT NULL;
    _has_ledger  BOOLEAN := to_regclass('public.usage_ledger')   IS NOT NULL;
    _has_exports BOOLEAN := to_regclass('public.export_history') IS NOT NULL;

    _batches   JSONB := jsonb_build_object('total', 0, 'complete', 0, 'open', 0,
                                           'abandoned', 0, 'approved', 0);
    _volume    JSONB := jsonb_build_object('checks_total', 0, 'matches_total', 0,
                                           'matched', 0, 'approved', 0,
                                           'rejected', 0, 'needs_attention', 0);
    _checks_part  JSONB := '{}'::jsonb;
    _matches_part JSONB := '{}'::jsonb;
    _processed BIGINT := 0;
    _exports   JSONB := jsonb_build_object('total', 0, 'by_format', '{}'::jsonb);
    _companies JSONB := '[]'::jsonb;
    _rows      JSONB := '[]'::jsonb;
BEGIN
    IF p_from IS NULL OR p_to IS NULL OR p_to < p_from THEN
        RAISE EXCEPTION 'report_summary: p_from and p_to are required and p_to must not precede p_from';
    END IF;

    -- SECURITY INVOKER, so RLS already scopes every read below. This is the
    -- second gate: a caller may only ask about their own tenant. The API's
    -- requireCapability(reports.view) is the first.
    _is_service := _claims IS NULL OR _claims = ''
                OR COALESCE(_claims::jsonb ->> 'role' = 'service_role', FALSE);
    IF NOT _is_service AND p_tenant_id IS DISTINCT FROM public.user_tenant_id() THEN
        RAISE EXCEPTION 'report_summary: tenant mismatch'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF _has_batches THEN
        SELECT COALESCE(array_agg(b.id), '{}'::uuid[])
          INTO _ids
          FROM public.batches b
         WHERE b.tenant_id    = p_tenant_id
           AND b.period_start <= p_to
           AND b.period_end   >= p_from
           AND (p_realm_id IS NULL OR b.realm_id = p_realm_id)
           AND (p_account  IS NULL OR b.account_id = p_account OR b.account_name = p_account)
           AND (p_batch_id IS NULL OR b.id = p_batch_id);

        SELECT jsonb_build_object(
                   'total',     count(*),
                   'complete',  count(*) FILTER (WHERE status = 'complete'),
                   'open',      count(*) FILTER (WHERE status = 'open'),
                   'abandoned', count(*) FILTER (WHERE status = 'abandoned'),
                   'approved',  count(*) FILTER (WHERE approved_at IS NOT NULL))
          INTO _batches
          FROM public.batches
         WHERE id = ANY(_ids);

        SELECT COALESCE(jsonb_agg(t.item ORDER BY t.n DESC), '[]'::jsonb)
          INTO _companies
          FROM (
              SELECT jsonb_build_object(
                         'realm_id',     realm_id,
                         'company_name', max(company_name),
                         'batches',      count(*)) AS item,
                     count(*) AS n
                FROM public.batches
               WHERE id = ANY(_ids)
               GROUP BY realm_id
               LIMIT 100
          ) t;

        SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.sort_at DESC), '[]'::jsonb)
          INTO _rows
          FROM (
              SELECT b.id, b.realm_id, b.company_name, b.account_id, b.account_name,
                     b.period_label, b.period_start, b.period_end, b.status,
                     b.approved_by, b.approved_at, b.completed_at,
                     -- public.batch_counts() ships with batches in migration
                     -- 032, so the _has_batches guard covers it too. Reused
                     -- rather than re-counted, so a row in this report and the
                     -- same row in History cannot disagree.
                     public.batch_counts(b.id) AS counts,
                     COALESCE(b.completed_at, b.updated_at) AS sort_at
                FROM public.batches b
               WHERE b.id = ANY(_ids)
               ORDER BY COALESCE(b.completed_at, b.updated_at) DESC
               LIMIT _limit
          ) t;
    END IF;

    -- checks and matches are counted in separate guarded branches, and each
    -- MERGES into _volume rather than replacing it, so a database that has one
    -- table and not the other still returns the figures it can actually count.
    IF _has_checks AND array_length(_ids, 1) IS NOT NULL THEN
        SELECT jsonb_build_object('checks_total', count(*))
          INTO _checks_part
          FROM public.checks c
         WHERE c.batch_id = ANY(_ids);
        _volume := _volume || _checks_part;
    END IF;

    IF _has_matches AND array_length(_ids, 1) IS NOT NULL THEN
        SELECT jsonb_build_object(
                   'matches_total',   count(*),
                   'matched',         count(*) FILTER (WHERE status = 'matched'),
                   'approved',        count(*) FILTER (WHERE status = 'approved'),
                   'rejected',        count(*) FILTER (WHERE status = 'rejected'),
                   -- The same set as NEEDS_ATTENTION_STATUSES / batch_counts().
                   'needs_attention', count(*) FILTER (
                       WHERE status IN ('pending', 'flagged', 'discrepancy', 'unmatched')))
          INTO _matches_part
          FROM public.matches m
         WHERE m.batch_id = ANY(_ids);
        _volume := _volume || _matches_part;
    END IF;

    IF _has_ledger THEN
        SELECT count(*) INTO _processed
          FROM public.usage_ledger l
         WHERE l.tenant_id   = p_tenant_id
           AND l.occurred_at >= p_from::timestamptz
           AND l.occurred_at <  (p_to + 1)::timestamptz
           AND (p_realm_id IS NULL OR l.realm_id = p_realm_id);
    END IF;

    IF _has_exports THEN
        SELECT jsonb_build_object(
                   'total', count(*),
                   'by_format', COALESCE(
                       (SELECT jsonb_object_agg(f, n) FROM (
                            SELECT export_format AS f, count(*) AS n
                              FROM public.export_history
                             WHERE tenant_id = p_tenant_id
                               AND created_at >= p_from::timestamptz
                               AND created_at <  (p_to + 1)::timestamptz
                             GROUP BY export_format) g),
                       '{}'::jsonb))
          INTO _exports
          FROM public.export_history
         WHERE tenant_id  = p_tenant_id
           AND created_at >= p_from::timestamptz
           AND created_at <  (p_to + 1)::timestamptz;
    END IF;

    RETURN jsonb_build_object(
        'range',   jsonb_build_object('from', p_from, 'to', p_to),
        'filters', jsonb_build_object('realm_id', p_realm_id, 'account', p_account,
                                      'batch_id', p_batch_id),
        -- Which figures are real. A missing table is reported, never zeroed.
        'sources', jsonb_build_object(
                       'batches', _has_batches, 'checks', _has_checks,
                       'matches', _has_matches, 'usage_ledger', _has_ledger,
                       'export_history', _has_exports),
        'batches',   _batches,
        'volume',    _volume,
        'cheques_processed', jsonb_build_object(
            'count',  _processed,
            'source', 'usage_ledger.occurred_at',
            -- usage_ledger has realm_id but no account, so the account filter
            -- cannot narrow this figure. Saying so beats a wrong number.
            'account_filter_applied', FALSE),
        'exports', _exports || jsonb_build_object(
            'scope', 'tenant and date range only — export_history has no batch link'),
        'companies', _companies,
        'rows',      _rows,
        'row_limit', _limit);
END;
$$ LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = public;

GRANT EXECUTE ON FUNCTION public.report_summary(UUID, DATE, DATE, TEXT, TEXT, UUID, INTEGER)
    TO authenticated;


-- ============================================================================
-- Verification (read-only; run by hand after applying)
--
--   SELECT public.upload_retention_days();                      -- 14
--   SELECT count(*) FROM public.upload_retention;               -- scheduled
--   SELECT * FROM public.upload_retention_due(10);              -- service role
--   SELECT public.report_summary(
--            (SELECT id FROM public.tenants LIMIT 1),
--            date_trunc('month', now())::date,
--            (date_trunc('month', now()) + interval '1 month - 1 day')::date);
-- ============================================================================

-- ========================================================================
-- 036_qb_accounts.sql
-- ========================================================================
-- ============================================================================
-- 036: qb_accounts — the cached chart of bank and credit-card accounts that
--      backs the account switcher (CHECKLIST section 4)
--
-- WHY A TABLE AND NOT A LIVE QBO QUERY
--
-- The account switcher sits in the top bar, so it is mounted on every page of
-- the app. Querying QuickBooks per render would be:
--
--   * slow — an Intuit round trip (plus a token refresh when stale) in front
--     of chrome that must paint immediately; and
--   * a quota risk that fails CLOSED. Intuit's free tier is 500,000 reads a
--     month and it BLOCKS rather than bills when exceeded. A switcher on every
--     page turns ordinary navigation into read volume, and the thing that
--     breaks when the quota trips is not the switcher — it is every customer's
--     sync, all at once, until the month rolls over. A cache makes the read
--     count a function of how often someone presses Refresh, not of how many
--     pages they visit.
--
-- The data is also slow-moving: a firm's chart of accounts changes far less
-- often than its transactions. Balances drift, which is why the switcher has
-- an explicit refresh action and why `synced_at` is surfaced in the UI rather
-- than hidden — a stale number that admits its age is honest, a stale number
-- presented as live is not.
--
-- WHAT IS DELIBERATELY NOT STORED
--
-- QBO's `Account.AcctNum` is the full account number. Only the last four are
-- kept here, derived at sync time. The switcher shows four digits, so storing
-- the rest would be holding a bank account number we have no use for.
--
-- Scoped per (tenant, realm) because a firm connects several QuickBooks
-- companies and each has its own chart of accounts. RLS is tenant-scoped the
-- same way every other table here is; writes go through the service role from
-- pages/api/qbo/accounts.ts, so `authenticated` gets SELECT only.
--
-- Idempotent and guarded, matching migrations 026-035: earlier migrations are
-- not assumed to have run.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.qb_accounts (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id            UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    -- Not a FK to qb_connections: a realm can be disconnected and reconnected,
    -- and the cached chart should survive that rather than cascade away.
    realm_id             TEXT NOT NULL,
    -- QBO Account.Id, unique within a realm.
    qb_account_id        TEXT NOT NULL,
    name                 TEXT NOT NULL,
    fully_qualified_name TEXT,
    -- QBO AccountType. Only 'Bank' and 'Credit Card' are synced — those are
    -- the two groups the switcher shows, and the old query hardcoded
    -- AccountType = 'Bank', which is exactly why credit cards were invisible.
    account_type         TEXT NOT NULL,
    account_sub_type     TEXT,
    -- Last four of AcctNum. The rest is never stored (see header).
    last_four            TEXT,
    current_balance      NUMERIC(14, 2),
    active               BOOLEAN NOT NULL DEFAULT TRUE,
    synced_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT qb_accounts_unique UNIQUE (tenant_id, realm_id, qb_account_id),
    CONSTRAINT qb_accounts_type_check CHECK (account_type IN ('Bank', 'Credit Card')),
    CONSTRAINT qb_accounts_last_four_check CHECK (last_four IS NULL OR last_four ~ '^[0-9]{1,4}$')
);

-- The switcher's only query: one realm, grouped by type, name order.
CREATE INDEX IF NOT EXISTS idx_qb_accounts_realm
    ON public.qb_accounts (tenant_id, realm_id, account_type, name);

ALTER TABLE public.qb_accounts ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF to_regprocedure('public.user_tenant_id()') IS NULL THEN
        RAISE NOTICE '036: public.user_tenant_id() absent — qb_accounts RLS policy skipped, service role still works';
        RETURN;
    END IF;

    DROP POLICY IF EXISTS "Users can view own tenant qb_accounts" ON public.qb_accounts;
    CREATE POLICY "Users can view own tenant qb_accounts"
        ON public.qb_accounts FOR SELECT TO authenticated
        USING (tenant_id = public.user_tenant_id());
END $$;

DROP POLICY IF EXISTS "Service role full access to qb_accounts" ON public.qb_accounts;
CREATE POLICY "Service role full access to qb_accounts"
    ON public.qb_accounts FOR ALL TO service_role USING (true) WITH CHECK (true);

-- The sync is a server-side upsert under the service role, so a signed-in user
-- can read the cache but can never write a balance into it.
REVOKE ALL ON public.qb_accounts FROM anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.qb_accounts FROM authenticated;
GRANT SELECT ON public.qb_accounts TO authenticated;

COMMENT ON TABLE public.qb_accounts IS
    'Cached QBO Bank and Credit Card accounts per (tenant, realm), backing the account switcher. The switcher is in the top bar on every page, so this exists so that navigating the app does not spend Intuit read quota — the free tier blocks rather than bills at 500k reads/month. Refreshed on demand by pages/api/qbo/accounts.ts; synced_at is shown in the UI.';

COMMENT ON COLUMN public.qb_accounts.last_four IS
    'Last four of QBO Account.AcctNum. The full number is deliberately never stored — the UI shows four digits and we have no use for the rest.';

-- ========================================================================
-- 037_one_trial_per_qb_company.sql
-- ========================================================================
-- ============================================================================
-- 037: One free trial per QuickBooks company (CHECKLIST section 6)
--
-- Michael's question: what stops someone taking a second free trial with a new
-- email address? Nothing, while identity is the email. The firm's QuickBooks
-- realm id is the stable identity — the same books cannot be two firms — so a
-- realm gets exactly one trial, claimed the first time it is connected.
--
-- Three pieces, deliberately small:
--
--   1. qb_realm_trials   — realm_id is the PRIMARY KEY. That single constraint
--                          IS the rule; nothing has to remember to check first.
--   2. tenants.trial_blocked_* — why a tenant's trial is void, so the existing
--                          resolver can report it instead of a second code path.
--   3. claim_realm_trial() — service-role only. Called once, at the moment a
--                          QuickBooks company is connected.
--
-- tenant_usage_state() (migration 029) is REPLACED rather than wrapped, so the
-- meter the UI draws and the gate that blocks work stay the same single answer.
-- Nothing here touches history: a blocked trial still reads every past job.
--
-- Idempotent: safe to re-run.
-- ============================================================================

-- ──────────────────────────────────────────────────────────────────────────────
-- 1. The claim table
-- ──────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.qb_realm_trials (
    -- Intuit's realm id, the natural key. PRIMARY KEY, not UNIQUE-on-a-surrogate:
    -- the uniqueness is the whole point of the table.
    realm_id     TEXT PRIMARY KEY,

    -- The tenant that got the trial for this company. ON DELETE RESTRICT: if the
    -- row vanished with the tenant, deleting the firm would hand out a fresh
    -- trial for the same books, which is exactly the loophole being closed.
    tenant_id    UUID NOT NULL REFERENCES public.tenants(id) ON DELETE RESTRICT,

    company_name TEXT,
    claimed_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_qb_realm_trials_tenant
    ON public.qb_realm_trials (tenant_id);

ALTER TABLE public.qb_realm_trials ENABLE ROW LEVEL SECURITY;

-- A tenant may see its own claim (so Settings can say "this company's trial was
-- used on <date>"). It may never see another firm's, and may never write: a
-- tenant that could delete its claim row could re-trial at will.
DROP POLICY IF EXISTS "Users can view own tenant qb_realm_trials" ON public.qb_realm_trials;
CREATE POLICY "Users can view own tenant qb_realm_trials"
    ON public.qb_realm_trials FOR SELECT
    TO authenticated
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Service role full access to qb_realm_trials" ON public.qb_realm_trials;
CREATE POLICY "Service role full access to qb_realm_trials"
    ON public.qb_realm_trials FOR ALL
    TO service_role
    USING (true)
    WITH CHECK (true);

REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.qb_realm_trials FROM authenticated;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.qb_realm_trials FROM anon;
GRANT SELECT ON public.qb_realm_trials TO authenticated;

-- Backfill: every company already connected has already had its trial. Taken
-- from qb_connections, oldest connection per realm wins, because that is the
-- tenant whose trial actually ran. ON CONFLICT DO NOTHING makes the re-run a
-- no-op rather than a reassignment.
INSERT INTO public.qb_realm_trials (realm_id, tenant_id, company_name, claimed_at)
SELECT DISTINCT ON (c.realm_id)
       c.realm_id, c.tenant_id, c.company_name,
       COALESCE(c.connected_at, now())
  FROM public.qb_connections c
 WHERE c.realm_id IS NOT NULL
   AND c.tenant_id IS NOT NULL
 ORDER BY c.realm_id, COALESCE(c.connected_at, now()) ASC
ON CONFLICT (realm_id) DO NOTHING;

-- ──────────────────────────────────────────────────────────────────────────────
-- 2. Why a tenant's trial is void
-- ──────────────────────────────────────────────────────────────────────────────
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS trial_blocked_reason   TEXT;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS trial_blocked_realm_id TEXT;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS trial_blocked_at       TIMESTAMPTZ;

COMMENT ON COLUMN public.tenants.trial_blocked_reason IS
    'Non-NULL means this tenant is not entitled to a trial. Currently only realm_trial_already_used (migration 037). Read by tenant_usage_state(); has no effect once subscription_status = active or a comp grant is live.';

-- ──────────────────────────────────────────────────────────────────────────────
-- 3. claim_realm_trial() — called when a QuickBooks company is connected
--
-- First claim wins. A second tenant connecting the same realm is not blocked
-- from CONNECTING (they may well be a paying firm, or the same firm migrating);
-- it is blocked from a free trial, and only while it is actually trialing.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.claim_realm_trial(
    p_tenant_id    UUID,
    p_realm_id     TEXT,
    p_company_name TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
    _owner      UUID;
    _claimed_at TIMESTAMPTZ;
    _status     TEXT;
    _blocked    BOOLEAN := FALSE;
BEGIN
    IF p_tenant_id IS NULL OR p_realm_id IS NULL OR btrim(p_realm_id) = '' THEN
        RAISE EXCEPTION 'claim_realm_trial: tenant_id and realm_id are required';
    END IF;

    INSERT INTO public.qb_realm_trials (realm_id, tenant_id, company_name)
    VALUES (btrim(p_realm_id), p_tenant_id, p_company_name)
    ON CONFLICT (realm_id) DO NOTHING;

    SELECT tenant_id, claimed_at INTO _owner, _claimed_at
      FROM public.qb_realm_trials
     WHERE realm_id = btrim(p_realm_id);

    -- This tenant owns the claim (either just now, or from an earlier connect).
    IF _owner = p_tenant_id THEN
        RETURN jsonb_build_object(
            'claimed', TRUE, 'trial_blocked', FALSE,
            'realm_id', btrim(p_realm_id),
            'owner_tenant_id', _owner, 'claimed_at', _claimed_at
        );
    END IF;

    -- Another tenant already used this company's trial.
    SELECT subscription_status INTO _status FROM public.tenants WHERE id = p_tenant_id;

    IF COALESCE(_status, 'trialing') = 'trialing' THEN
        UPDATE public.tenants
           SET trial_blocked_reason   = 'realm_trial_already_used',
               trial_blocked_realm_id = btrim(p_realm_id),
               trial_blocked_at       = now()
         WHERE id = p_tenant_id
           AND trial_blocked_reason IS NULL;   -- first block stands; keeps the audit honest
        _blocked := TRUE;
    END IF;

    INSERT INTO public.audit_logs (tenant_id, user_id, action, new_value, metadata)
    VALUES (
        p_tenant_id, NULL, 'trial.realm_already_used', NULL,
        jsonb_build_object(
            'realm_id', btrim(p_realm_id),
            'owner_tenant_id', _owner,
            'owner_claimed_at', _claimed_at,
            'subscription_status', _status,
            'trial_blocked', _blocked
        )
    );

    RETURN jsonb_build_object(
        'claimed', FALSE, 'trial_blocked', _blocked,
        'realm_id', btrim(p_realm_id),
        'owner_tenant_id', _owner, 'claimed_at', _claimed_at
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- Service role only. A tenant session that could call this could claim a realm
-- it has not connected, locking a competitor out of their own trial.
REVOKE ALL ON FUNCTION public.claim_realm_trial(UUID, TEXT, TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.claim_realm_trial(UUID, TEXT, TEXT) FROM authenticated, anon;
GRANT EXECUTE ON FUNCTION public.claim_realm_trial(UUID, TEXT, TEXT) TO service_role;

-- ──────────────────────────────────────────────────────────────────────────────
-- 4. tenant_usage_state(), replaced so the blocked trial is reported by the one
--    resolver the meter and both write paths already read.
--
--    Identical to migration 029 except for the two marked lines in the trialing
--    branch and the two extra keys in the returned object.
-- ──────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.tenant_usage_state(
    p_tenant_id UUID,
    p_at        TIMESTAMPTZ DEFAULT now()
)
RETURNS JSONB AS $$
DECLARE
    _claims     TEXT := current_setting('request.jwt.claims', TRUE);
    _is_service BOOLEAN;
    _t          public.tenants;
    _comp       public.comp_grants;
    _is_comped  BOOLEAN := FALSE;
    _p_start    DATE;
    _p_end      DATE;
    _used_period  INTEGER := 0;
    _used_trial   INTEGER := 0;
    _used_comp    INTEGER := 0;
    _days_left    INTEGER;
    _checks_left  INTEGER;
    _allowed      BOOLEAN;
    _reason       TEXT := NULL;
    _allowance    INTEGER;
BEGIN
    _is_service := _claims IS NULL
                OR _claims = ''
                OR COALESCE(_claims::jsonb ->> 'role' = 'service_role', FALSE);

    IF NOT _is_service AND p_tenant_id IS DISTINCT FROM public.user_tenant_id() THEN
        RAISE EXCEPTION 'tenant_usage_state: not permitted for another tenant'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO _t FROM public.tenants WHERE id = p_tenant_id;
    IF _t.id IS NULL THEN
        RETURN jsonb_build_object(
            'tenant_id', p_tenant_id,
            'processing_allowed', FALSE,
            'block_reason', 'unknown_tenant'
        );
    END IF;

    SELECT period_start, period_end INTO _p_start, _p_end
      FROM public.current_billing_period(p_tenant_id, p_at);

    SELECT COALESCE(SUM(quantity), 0) INTO _used_period
      FROM public.usage_ledger
     WHERE tenant_id = p_tenant_id
       AND billing_period_start = _p_start;

    SELECT COALESCE(SUM(quantity), 0) INTO _used_trial
      FROM public.usage_ledger
     WHERE tenant_id = p_tenant_id
       AND occurred_at >= COALESCE(_t.trial_started_at, _t.created_at, p_at);

    SELECT * INTO _comp
      FROM public.comp_grants
     WHERE tenant_id = p_tenant_id
       AND revoked_at IS NULL
       AND starts_at <= p_at
       AND expires_at > p_at
     ORDER BY expires_at DESC
     LIMIT 1;

    _is_comped := _comp.id IS NOT NULL;

    IF _is_comped THEN
        SELECT COALESCE(SUM(quantity), 0) INTO _used_comp
          FROM public.usage_ledger
         WHERE tenant_id = p_tenant_id
           AND occurred_at >= _comp.starts_at;
    END IF;

    _allowance := _t.plan_check_allowance;

    IF _is_comped THEN
        _days_left   := GREATEST(0, CEIL(EXTRACT(EPOCH FROM (_comp.expires_at - p_at)) / 86400.0))::int;
        _checks_left := CASE WHEN _comp.check_limit IS NULL
                            THEN NULL
                            ELSE GREATEST(0, _comp.check_limit - _used_comp) END;
        _allowed := _comp.check_limit IS NULL OR _used_comp < _comp.check_limit;
        IF NOT _allowed THEN _reason := 'comp_check_limit_reached'; END IF;

    ELSIF _t.subscription_status = 'active' THEN
        _days_left   := NULL;
        _checks_left := CASE WHEN _allowance IS NULL
                            THEN NULL
                            ELSE GREATEST(0, _allowance - _used_period) END;
        _allowed := TRUE;

    ELSIF _t.subscription_status IN ('past_due', 'canceled', 'expired') THEN
        _days_left   := 0;
        _checks_left := 0;
        _allowed     := FALSE;
        _reason      := 'subscription_' || _t.subscription_status;

    -- ── 037: this QuickBooks company already had its one trial. ──────────────
    ELSIF _t.trial_blocked_reason IS NOT NULL THEN
        _days_left   := 0;
        _checks_left := 0;
        _allowed     := FALSE;
        _reason      := _t.trial_blocked_reason;

    ELSE
        -- Trialing. 14 days OR 250 cheques, whichever comes first.
        _days_left   := GREATEST(0, CEIL(EXTRACT(EPOCH FROM (_t.trial_ends_at - p_at)) / 86400.0))::int;
        _checks_left := GREATEST(0, COALESCE(_t.trial_check_limit, 250) - _used_trial);
        IF _t.trial_ends_at <= p_at THEN
            _allowed := FALSE;
            _reason  := 'trial_expired';
        ELSIF _used_trial >= COALESCE(_t.trial_check_limit, 250) THEN
            _allowed := FALSE;
            _reason  := 'trial_check_limit_reached';
        ELSE
            _allowed := TRUE;
        END IF;
    END IF;

    RETURN jsonb_build_object(
        'tenant_id',               p_tenant_id,
        'plan',                    _t.plan,
        'subscription_status',     _t.subscription_status,
        'as_of',                   p_at,

        'trial_started_at',        _t.trial_started_at,
        'trial_ends_at',           _t.trial_ends_at,
        'trial_check_limit',       COALESCE(_t.trial_check_limit, 250),
        'trial_checks_used',       _used_trial,
        'trial_blocked_reason',    _t.trial_blocked_reason,
        'trial_blocked_realm_id',  _t.trial_blocked_realm_id,

        'days_remaining',          _days_left,
        'checks_remaining',        _checks_left,

        'billing_period_start',    _p_start,
        'billing_period_end',      _p_end,
        'checks_used_this_period', _used_period,
        'plan_check_allowance',    _allowance,

        'is_comped',               _is_comped,
        'comp_expires_at',         _comp.expires_at,
        'comp_reason',             _comp.reason,
        'comp_check_limit',        _comp.check_limit,
        'comp_checks_used',        CASE WHEN _is_comped THEN _used_comp ELSE NULL END,

        'processing_allowed',      _allowed,
        'block_reason',            _reason
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public;

GRANT EXECUTE ON FUNCTION public.tenant_usage_state(UUID, TIMESTAMPTZ) TO authenticated, service_role;

COMMENT ON TABLE public.qb_realm_trials IS
    'One free trial per QuickBooks company. realm_id is the PRIMARY KEY, so the first tenant to connect a company claims its trial and a second signup with a new email address cannot get another. Written only by claim_realm_trial() under the service key.';
COMMENT ON FUNCTION public.claim_realm_trial(UUID, TEXT, TEXT) IS
    'Called when a QuickBooks company is connected. Claims the realm''s one trial for this tenant, or — if another tenant already holds it and this tenant is still trialing — sets tenants.trial_blocked_reason and writes an audit_logs row. Never blocks the connection itself.';

-- ========================================================================
-- 038_fk_and_hot_path_indexes.sql
-- ========================================================================
-- ============================================================================
-- 038: Indexes for every unindexed foreign key, plus the hot read paths.
--
-- pg_stat_user_tables showed check_jobs read by sequential scan 3,835 times;
-- every page filters it by tenant_id, which had no index. Postgres does not
-- index foreign keys automatically, so the RLS predicate
-- (tenant_id = user_tenant_id()) and every ON DELETE walked whole tables.
--
-- Idempotent: CREATE INDEX IF NOT EXISTS throughout. Safe to run twice.
-- ============================================================================

-- Tenant scoping (the RLS predicate on every user query).
CREATE INDEX IF NOT EXISTS idx_check_jobs_tenant_created  ON public.check_jobs (tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_qb_entries_tenant          ON public.qb_entries (tenant_id);
CREATE INDEX IF NOT EXISTS idx_quickbooks_entries_tenant  ON public.quickbooks_entries (tenant_id);
CREATE INDEX IF NOT EXISTS idx_app_settings_tenant        ON public.app_settings (tenant_id);
CREATE INDEX IF NOT EXISTS idx_processing_stages_tenant   ON public.processing_stages (tenant_id);
CREATE INDEX IF NOT EXISTS idx_mfa_recovery_codes_tenant  ON public.mfa_recovery_codes (tenant_id);
CREATE INDEX IF NOT EXISTS idx_stripe_events_tenant       ON public.stripe_events (tenant_id);

-- Hot read paths: review screens, matches by status, checks by job.
CREATE INDEX IF NOT EXISTS idx_checks_tenant_batch        ON public.checks (tenant_id, batch_id);
CREATE INDEX IF NOT EXISTS idx_checks_tenant_number       ON public.checks (tenant_id, check_number);
CREATE INDEX IF NOT EXISTS idx_matches_tenant_status      ON public.matches (tenant_id, status, confidence_score);

-- Remaining foreign keys (user / actor columns, cascades and audit joins).
CREATE INDEX IF NOT EXISTS idx_checks_user                ON public.checks (user_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_user            ON public.audit_logs (user_id);
CREATE INDEX IF NOT EXISTS idx_export_history_user        ON public.export_history (user_id);
CREATE INDEX IF NOT EXISTS idx_vouched_checks_vouched_by  ON public.vouched_checks (vouched_by);
CREATE INDEX IF NOT EXISTS idx_qb_connections_user        ON public.qb_connections (user_id);
CREATE INDEX IF NOT EXISTS idx_qb_transactions_user       ON public.qb_transactions (user_id);
CREATE INDEX IF NOT EXISTS idx_matches_user               ON public.matches (user_id);
CREATE INDEX IF NOT EXISTS idx_matches_qb_txn             ON public.matches (qb_txn_id);
CREATE INDEX IF NOT EXISTS idx_matches_resolved_by        ON public.matches (resolved_by);
CREATE INDEX IF NOT EXISTS idx_matches_approved_by        ON public.matches (approved_by);
CREATE INDEX IF NOT EXISTS idx_match_audit_log_user       ON public.match_audit_log (user_id);
CREATE INDEX IF NOT EXISTS idx_upload_fingerprints_user   ON public.upload_fingerprints (user_id);
CREATE INDEX IF NOT EXISTS idx_usage_ledger_user          ON public.usage_ledger (user_id);
CREATE INDEX IF NOT EXISTS idx_comp_grants_granted_by     ON public.comp_grants (granted_by);
CREATE INDEX IF NOT EXISTS idx_comp_grants_revoked_by     ON public.comp_grants (revoked_by);
CREATE INDEX IF NOT EXISTS idx_team_invitations_invited_by ON public.team_invitations (invited_by);
CREATE INDEX IF NOT EXISTS idx_batches_approved_by        ON public.batches (approved_by);
CREATE INDEX IF NOT EXISTS idx_billing_refunds_refunded_by ON public.billing_refunds (refunded_by);

ANALYZE public.check_jobs, public.checks, public.matches, public.qb_entries, public.qb_transactions;

-- ── audit_logs drift ────────────────────────────────────────────────────────
-- 001_schema.sql declares (field, old_value, new_value, job_id), but the live
-- table was created with (entity_type, entity_id, old_values, new_values). The
-- triggers from 029 (comp grants), 033 (refunds) and 037 (one trial per QB
-- company) and pages/api/checks/[id]/update.ts write the singular names, so
-- every one of those inserts failed. Adding the columns repairs all of them
-- without rewriting the triggers; nothing reads them as required.
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS field     TEXT;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS old_value TEXT;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS new_value TEXT;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS job_id    TEXT;

-- Make PostgREST see functions and tables added by earlier migrations
-- (report_summary() was reported "missing" until this ran).
NOTIFY pgrst, 'reload schema';

-- ========================================================================
-- 039_fix_signup_trigger_search_path.sql
-- ========================================================================
-- ============================================================================
-- 039: Fix "Database error saving new user" on signup
--
-- handle_new_user() (last set in 014) is SECURITY DEFINER with no search_path
-- and unqualified table names. Supabase Auth inserts into auth.users with
-- search_path = auth, so "tenants" / "user_profiles" don't resolve and the
-- whole signup rolls back. Every later migration (026+) uses SET search_path,
-- this function was never brought in line.
--
-- Also: 014 coerced every plan outside the legacy set to 'starter'; 026 made
-- essential | professional | scale the current plans, so accept those.
-- ============================================================================

DO $$
DECLARE
    _profiles TEXT := CASE
        WHEN to_regclass('public.user_profiles') IS NOT NULL THEN 'user_profiles'
        ELSE 'profiles'
    END;
BEGIN
    EXECUTE format($fn$
        CREATE OR REPLACE FUNCTION public.handle_new_user()
        RETURNS TRIGGER AS $func$
        DECLARE
            _tenant_id UUID;
            _company_name TEXT;
            _full_name TEXT;
            _plan TEXT;
        BEGIN
            _company_name := COALESCE(
                NULLIF(btrim(NEW.raw_user_meta_data->>'company_name'), ''),
                NULLIF(btrim(NEW.raw_user_meta_data->>'full_name'), ''),
                split_part(NEW.email, '@', 1)
            );
            _full_name := COALESCE(
                NULLIF(btrim(NEW.raw_user_meta_data->>'full_name'), ''),
                split_part(NEW.email, '@', 1)
            );
            _plan := COALESCE(NEW.raw_user_meta_data->>'plan', 'essential');
            IF _plan NOT IN ('essential', 'professional', 'scale') THEN
                _plan := 'essential';
            END IF;

            INSERT INTO public.tenants (name, slug, plan)
            VALUES (
                _company_name,
                lower(regexp_replace(_company_name, '[^a-zA-Z0-9]+', '-', 'g')) || '-' || substr(NEW.id::text, 1, 8),
                _plan
            )
            RETURNING id INTO _tenant_id;

            INSERT INTO public.%I (id, tenant_id, email, full_name, role)
            VALUES (NEW.id, _tenant_id, NEW.email, _full_name, 'admin');

            IF to_regclass('public.tenant_settings') IS NOT NULL THEN
                INSERT INTO public.tenant_settings (tenant_id) VALUES (_tenant_id);
            END IF;

            RETURN NEW;
        EXCEPTION
            WHEN OTHERS THEN
                RAISE WARNING 'Error in handle_new_user: %% (SQLSTATE: %%)', SQLERRM, SQLSTATE;
                RAISE EXCEPTION 'Database error saving new user: %%', SQLERRM;
        END;
        $func$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
    $fn$, _profiles);
END $$;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
    AFTER INSERT ON auth.users
    FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- ========================================================================
-- 039_realtime_matches.sql
-- ========================================================================
-- 039: publish `matches` for Supabase Realtime.
--
-- WHY: two reviewers from the same accounting firm work one reconciliation
-- batch. The Review step now subscribes to postgres_changes on matches filtered
-- by batch_id (frontend/hooks/useRealtimeMatches.ts). Realtime only emits rows
-- for tables in the `supabase_realtime` publication — without this migration
-- the subscription connects, reports SUBSCRIBED, and silently receives nothing.
-- A 200 from the socket is not proof of delivery.
--
-- SAFETY: realtime honours RLS, evaluating the SELECT policy per row as the
-- connected user. `matches` already has, from 013_qb_multi_company_match.sql:
--     FOR SELECT USING (tenant_id = public.user_tenant_id())
-- so publishing it cannot leak another firm's rows. The block below REFUSES to
-- publish if that guard is ever absent, rather than opening a cross-tenant
-- firehose on a table whose RLS was dropped.
--
-- Idempotent: safe to run repeatedly.

DO $$
DECLARE
    v_rls_enabled boolean;
    v_select_policies int;
BEGIN
    IF to_regclass('public.matches') IS NULL THEN
        RAISE WARNING '039: public.matches absent — skipping realtime publication';
        RETURN;
    END IF;

    SELECT c.relrowsecurity INTO v_rls_enabled
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'public' AND c.relname = 'matches';

    SELECT count(*) INTO v_select_policies
      FROM pg_policies
     WHERE schemaname = 'public'
       AND tablename  = 'matches'
       AND cmd IN ('SELECT', 'ALL')
       AND qual ILIKE '%tenant_id%';

    IF NOT v_rls_enabled OR v_select_policies = 0 THEN
        RAISE EXCEPTION '039: refusing to publish public.matches to realtime — '
            'RLS enabled=%, tenant-scoped SELECT policies=%. Restore the tenant '
            'isolation policy from 013_qb_multi_company_match.sql first.',
            v_rls_enabled, v_select_policies;
    END IF;

    -- Supabase ships this publication; create it on a bare Postgres so the
    -- migration is runnable outside a Supabase project too.
    IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
        CREATE PUBLICATION supabase_realtime;
        RAISE NOTICE '039: created publication supabase_realtime';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_publication_tables
         WHERE pubname = 'supabase_realtime'
           AND schemaname = 'public'
           AND tablename  = 'matches'
    ) THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.matches;
        RAISE NOTICE '039: added public.matches to supabase_realtime';
    END IF;

    -- UPDATE/DELETE events carry only the primary key in their OLD row under
    -- the default replica identity, which is not enough for realtime to apply
    -- the tenant RLS check or the batch_id filter to them. FULL makes the old
    -- row complete. matches is a review-sized table, so the extra WAL is cheap.
    IF EXISTS (
        SELECT 1 FROM pg_class c
          JOIN pg_namespace n ON n.oid = c.relnamespace
         WHERE n.nspname = 'public' AND c.relname = 'matches'
           AND c.relreplident <> 'f'
    ) THEN
        ALTER TABLE public.matches REPLICA IDENTITY FULL;
    END IF;
END $$;

-- The subscription filters on batch_id; 032 already indexes (batch_id, status).
-- Verification (expect one row):
--   SELECT * FROM pg_publication_tables
--    WHERE pubname = 'supabase_realtime' AND tablename = 'matches';

-- ========================================================================
-- 040_waitlist.sql
-- ========================================================================
-- 040: the Kyriq IQ waitlist.
--
-- WHY: "Join the waitlist" on the landing page was a mailto: link. It threw the
-- visitor out of the site into whatever mail client the OS happened to open,
-- and on a machine with no mail client configured it did nothing at all. Every
-- sign-up it did produce landed in one inbox as free text, so nobody could
-- answer "how many people want this".
--
-- This table is the record instead. It is the ONE place the landing form writes.
--
-- NOT TENANT-SCOPED, deliberately. Everything else here carries tenant_id and an
-- RLS policy keyed to it, but a waitlist signup happens before the person has an
-- account, so there is no tenant to scope to and no authenticated user to check.
-- The protection is therefore the opposite shape: no client role may touch this
-- table AT ALL, and both routes that use it hold the service-role key server
-- side. Writing it with the anon key from the browser is what would turn it into
-- a public mailing list, so that path is closed here rather than in app code.
--
-- Idempotent: safe to run repeatedly.

CREATE TABLE IF NOT EXISTS public.waitlist (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email       TEXT NOT NULL,
    name        TEXT,
    company     TEXT,
    note        TEXT,
    -- Which surface produced the signup, so a second entry point later can be
    -- measured separately rather than silently merged into the first.
    source      TEXT NOT NULL DEFAULT 'landing_kyriq_iq',
    -- Set once the confirmation email is accepted by the provider. NULL means
    -- the row exists but nothing was delivered, which is the case worth seeing.
    confirmed_at TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- One row per address. A second submission updates the existing row rather than
-- creating a duplicate, so the count is a count of PEOPLE. Addresses are
-- compared case-insensitively because Someone@x.com and someone@x.com are one
-- person; the API lowercases on the way in and this index enforces it even if a
-- future caller forgets.
CREATE UNIQUE INDEX IF NOT EXISTS waitlist_email_key
    ON public.waitlist (lower(email));

CREATE INDEX IF NOT EXISTS waitlist_created_at_idx
    ON public.waitlist (created_at DESC);

ALTER TABLE public.waitlist ENABLE ROW LEVEL SECURITY;

-- A policy that matches nothing. RLS with no policy already denies, but an
-- explicit FALSE states the intent, so the next person to read this file does
-- not "helpfully" add a permissive one. service_role bypasses RLS and is how
-- both routes reach the table.
DROP POLICY IF EXISTS "waitlist_no_client_access" ON public.waitlist;
CREATE POLICY "waitlist_no_client_access"
    ON public.waitlist
    FOR ALL
    TO anon, authenticated
    USING (false)
    WITH CHECK (false);

-- Belt and braces: RLS governs row visibility, but the table-level grant is a
-- separate gate. Revoking it means a mistaken permissive policy later still
-- cannot expose the list.
REVOKE ALL ON public.waitlist FROM anon, authenticated;

COMMENT ON TABLE public.waitlist IS
    'Kyriq IQ waitlist signups from the public landing form. Not tenant-scoped: '
    'signups happen before an account exists. Service-role access only.';

-- ========================================================================
-- 041_waitlist_email_unique.sql
-- ========================================================================
-- 041: make the waitlist's one-row-per-person rule usable by ON CONFLICT.
--
-- 040 enforced uniqueness with a UNIQUE INDEX on lower(email). That does keep
-- duplicates out, but Postgres cannot match `ON CONFLICT (email)` to an index
-- built on an EXPRESSION, so the upsert in pages/api/waitlist.ts failed with
-- "there is no unique or exclusion constraint matching the ON CONFLICT
-- specification" and every signup after the first returned a 500.
--
-- Rather than complicate the query with the expression form, the constraint is
-- now the plain one the route expects:
--
--   UNIQUE (email)              -- what ON CONFLICT (email) binds to
--   CHECK  (email = lower(email))  -- what keeps the uniqueness meaningful
--
-- The CHECK is the half that must not be lost. Without it, UNIQUE(email) alone
-- would happily hold Someone@x.com AND someone@x.com as two people, which is the
-- exact duplicate 040 set out to prevent. The API lowercases on the way in; this
-- is what makes that a guarantee rather than a convention.
--
-- Idempotent: safe to run repeatedly.

-- Existing rows must satisfy the CHECK before it can be added. The table is new
-- and the route has always lowercased, so this normally affects nothing, but a
-- row written by hand would otherwise make the ALTER fail.
UPDATE public.waitlist SET email = lower(email) WHERE email <> lower(email);

-- Collapse any pair that differed only by case, keeping the earliest signup —
-- that is the one whose confirmation email was actually sent.
DELETE FROM public.waitlist a
 USING public.waitlist b
 WHERE a.id <> b.id
   AND lower(a.email) = lower(b.email)
   AND a.created_at > b.created_at;

DROP INDEX IF EXISTS public.waitlist_email_key;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'public.waitlist'::regclass
           AND conname  = 'waitlist_email_unique'
    ) THEN
        ALTER TABLE public.waitlist
            ADD CONSTRAINT waitlist_email_unique UNIQUE (email);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'public.waitlist'::regclass
           AND conname  = 'waitlist_email_lowercase'
    ) THEN
        ALTER TABLE public.waitlist
            ADD CONSTRAINT waitlist_email_lowercase CHECK (email = lower(email));
    END IF;
END $$;

-- ========================================================================
-- 042_export_history_matches_schema.sql
-- ========================================================================
-- 042: make public.export_history match the schema the code was written against.
--
-- SYMPTOM: the Reports page said "Reports are not available yet —
-- public.report_summary() is missing — apply 035". That message was wrong twice
-- over. 035 HAD been applied and the function existed; calling it returned
--
--     42703  column "export_format" does not exist
--
-- and /api/reports/summary classifies a missing *column* with the same
-- isMissingObject() branch as a missing *function*, so it reported the one thing
-- that was not the problem. (The message is left alone here: the branch is a
-- reasonable catch-all, and once this migration runs it stops firing.)
--
-- CAUSE: 001_schema.sql declares export_history.export_format, and 035's
-- report_summary groups by it. The live table instead had export_type, and was
-- missing job_id, check_count and file_name as well. Nothing in the repo ever
-- wrote export_type — it appears in no migration and no application code — so
-- the live table is a hand-made shape that drifted from 001 and was never
-- reconciled, which is the same root cause as the empty migration ledger that
-- 026-041 had to be pushed through.
--
-- RESOLUTION: 001 is canonical. Nothing reads or writes this table yet, and it
-- is empty, so the rename is free. This is the repo's own named defect class —
-- "check table and column names against supabase/migrations/" — so it is fixed
-- in the database rather than by teaching the function the wrong name.
--
-- Idempotent: safe to run repeatedly, and safe on a database that already
-- matches 001 (every branch is guarded).

DO $$
BEGIN
    IF to_regclass('public.export_history') IS NULL THEN
        RAISE WARNING '042: public.export_history absent — nothing to reconcile';
        RETURN;
    END IF;

    -- Rename only when the old name is there AND the new one is not, so this
    -- cannot clobber a correct column or run twice.
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = 'export_history'
           AND column_name = 'export_type'
    ) AND NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = 'export_history'
           AND column_name = 'export_format'
    ) THEN
        ALTER TABLE public.export_history RENAME COLUMN export_type TO export_format;
        RAISE NOTICE '042: renamed export_history.export_type -> export_format';
    END IF;

    -- A table that had neither column still needs one, or report_summary fails
    -- exactly as it did before.
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = 'export_history'
           AND column_name = 'export_format'
    ) THEN
        ALTER TABLE public.export_history ADD COLUMN export_format TEXT;
        RAISE NOTICE '042: added missing export_history.export_format';
    END IF;
END $$;

-- The remaining columns 001 declares. Added without NOT NULL: the table is empty
-- today, but a NOT NULL with no default would fail on any row a future rerun
-- found, and nothing depends on their nullability.
ALTER TABLE public.export_history ADD COLUMN IF NOT EXISTS job_id      TEXT;
ALTER TABLE public.export_history ADD COLUMN IF NOT EXISTS check_count INTEGER DEFAULT 0;
ALTER TABLE public.export_history ADD COLUMN IF NOT EXISTS file_name   TEXT;

-- 001 constrains the format to the set the product actually exports. Added only
-- when absent, and NOT VALID so it governs new rows without forcing a scan that
-- could fail on legacy values written under the old column name.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'public.export_history'::regclass
           AND conname  = 'export_history_export_format_check'
    ) THEN
        ALTER TABLE public.export_history
            ADD CONSTRAINT export_history_export_format_check
            CHECK (export_format IS NULL
                   OR export_format IN ('csv','iif','xero','zoho','excel','qbo_api','sage'))
            NOT VALID;
        RAISE NOTICE '042: added export_format check constraint';
    END IF;
END $$;

-- ========================================================================
-- 043_check_documents_rag.sql
-- ========================================================================
-- ============================================================================
-- 043: check_documents, a RAG-ready row per extracted check
--
-- One row per (tenant, job, check) with the extracted fields, the engine that
-- produced them and a short text summary the voice agent can search. The
-- embedding column is added only when pgvector is available, so this migration
-- runs on a project without the extension too. Idempotent.
--
-- Numbered 043 because 040-042 already exist on main; 040_checks_rag.sql in the
-- plan was renamed to avoid the clash.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.check_documents (
    id            UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id     UUID        NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    job_id        TEXT        NOT NULL,
    check_id      TEXT        NOT NULL,
    engine        TEXT        NOT NULL,
    fields        JSONB       NOT NULL DEFAULT '{}'::jsonb,
    summary       TEXT        NOT NULL DEFAULT '',
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT check_documents_job_check_engine_key UNIQUE (tenant_id, job_id, check_id, engine)
);

CREATE INDEX IF NOT EXISTS idx_check_documents_tenant_job
    ON public.check_documents (tenant_id, job_id);

-- Vector search only where the extension exists. Done with DO so a project
-- without pgvector still gets the table above.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'vector') THEN
        CREATE EXTENSION IF NOT EXISTS vector;
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema = 'public' AND table_name = 'check_documents' AND column_name = 'embedding'
        ) THEN
            ALTER TABLE public.check_documents ADD COLUMN embedding vector(1536);
        END IF;
    END IF;
END $$;

ALTER TABLE public.check_documents ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Tenant isolation check_documents select" ON public.check_documents;
CREATE POLICY "Tenant isolation check_documents select"
    ON public.check_documents FOR SELECT
    USING (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Tenant isolation check_documents insert" ON public.check_documents;
CREATE POLICY "Tenant isolation check_documents insert"
    ON public.check_documents FOR INSERT
    WITH CHECK (tenant_id = public.user_tenant_id());

DROP POLICY IF EXISTS "Tenant isolation check_documents update" ON public.check_documents;
CREATE POLICY "Tenant isolation check_documents update"
    ON public.check_documents FOR UPDATE
    USING (tenant_id = public.user_tenant_id())
    WITH CHECK (tenant_id = public.user_tenant_id());

-- ========================================================================
-- 044_check_jobs_doc_kind.sql
-- ========================================================================
-- ============================================================================
-- 044: check_jobs.doc_kind — what an upload turned out to be
--
-- The upload page already classifies each file (frontend/lib/document-kind.ts)
-- but never saved the verdict, so History and Reports could not tell a bank
-- statement from a sheet of cheque images. The backend now computes the same
-- verdict at upload-analyze time (backend/doc_kind.py) and stores it here.
-- Nullable: rows that predate this migration stay NULL and render as unknown.
-- Idempotent.
-- ============================================================================

ALTER TABLE public.check_jobs ADD COLUMN IF NOT EXISTS doc_kind TEXT;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'check_jobs_doc_kind_check'
          AND conrelid = 'public.check_jobs'::regclass
    ) THEN
        ALTER TABLE public.check_jobs
            ADD CONSTRAINT check_jobs_doc_kind_check
            CHECK (doc_kind IS NULL OR doc_kind IN
                ('cheque-sheet', 'bank-statement', 'single-cheque', 'no-cheques'));
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_check_jobs_tenant_doc_kind
    ON public.check_jobs (tenant_id, doc_kind);

COMMENT ON COLUMN public.check_jobs.doc_kind IS
    'Detected document kind, same vocabulary as frontend/lib/document-kind.ts. NULL = classified before migration 044.';

-- ========================================================================
-- 045_check_jobs_user_id.sql
-- ========================================================================
-- ============================================================================
-- 045: check_jobs.user_id
--
-- backend/api_server.py has written user_id on check_jobs since the usage
-- ledger landed (inserts near lines 1313/1481/1508, updates at 1329/1626), and
-- the startup loader reads it back. The column was never migrated, so on the
-- live project every signed-in upload's insert fails with PGRST204 ("Could not
-- find the 'user_id' column"), the job exists only in one process's memory,
-- and the upload page polls into "Job not found". Idempotent.
-- ============================================================================

ALTER TABLE public.check_jobs
    ADD COLUMN IF NOT EXISTS user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_check_jobs_tenant_user
    ON public.check_jobs (tenant_id, user_id);

COMMENT ON COLUMN public.check_jobs.user_id IS
    'The signed-in user who uploaded the job; NULL for rows created before migration 045 or by unauthenticated analysis.';

-- ========================================================================
-- 046_check_jobs_page_kinds.sql
-- ========================================================================
-- ============================================================================
-- 046: check_jobs.page_kinds — what each page of an upload is
--
-- doc_kind (044) is one verdict per file. A whole bank statement is both: a
-- transaction table on some pages and cheque images on others, and the client
-- wants "Statement + 227 cheque images", not a single label. The backend now
-- classifies every page at upload-analyze time (backend/page_kinds.py) and
-- stores the list here: a JSON array of 'statement' | 'cheque-images' |
-- 'both' | 'other', one entry per page in page order.
-- Nullable: rows that predate this migration stay NULL. Idempotent.
-- ============================================================================

ALTER TABLE public.check_jobs ADD COLUMN IF NOT EXISTS page_kinds JSONB;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'check_jobs_page_kinds_array'
          AND conrelid = 'public.check_jobs'::regclass
    ) THEN
        ALTER TABLE public.check_jobs
            ADD CONSTRAINT check_jobs_page_kinds_array
            CHECK (page_kinds IS NULL OR jsonb_typeof(page_kinds) = 'array');
    END IF;
END $$;

COMMENT ON COLUMN public.check_jobs.page_kinds IS
    'Per-page kinds in page order: statement | cheque-images | both | other (backend/page_kinds.py). NULL = analysed before migration 046.';

COMMIT;
